local config = {
  ui_story_5031_50310101_1_dialog_content = "Senhoras, senhores e convidados de todas as esferas da vida! Bem-vindo ao <color=#FFB400>O Ilusionista e o Circo do Velho Bill</color>! Meu nome é <color=#FFB400>Rainbow</color>, e eu serei seu anfitrião para o show de hoje à noite!",
  ui_story_5031_50310101_2_dialog_content = "Todos os que se juntaram a nós a bordo do Emerald nesta esplêndida noite são os convidados mais ilustres do nosso circo.",
  ui_story_5031_50310101_3_dialog_content = "Por favor, deixe suas preocupações de lado e aproveite nosso maravilhoso desempenho.",
  ui_story_5031_50310101_4_dialog_content = "As apresentações espetaculares oferecidas pelo Illusionist & Old Bill's Circus são destinadas a desafiar todas as razões e exceder sua imaginação mais selvagem!",
  ui_story_5031_50310101_5_dialog_content = "Este momento mágico pertence a você, a mim, ao mundo inteiro!",
  ui_story_5031_50310101_6_dialog_content = "Sem mais delongas, vamos dar as boas-vindas ao nosso primeiro ato: as acrobacias de três irmãs que dominam a arte do trapézio! Por favor, dê as boas-vindas a Merylt—",
  ui_story_5031_50310101_7_dialog_content = "Subli—",
  ui_story_5031_50310101_8_dialog_content = "E Frimet—",
  ui_story_5031_50310101_9_dialog_content = "Enquanto eles sobem ao palco!",
  ui_story_5031_50310101_10_dialog_content = "U-uh, Rainbow...? O equipamento do trapézio ainda não está sendo consertado?",
  ui_story_5031_50310101_11_dialog_content = "Sim, mesmo nós não somos capazes de voar sozinhos.",
  ui_story_5031_50310101_12_dialog_content = "Heehee... Na verdade, eu venho treinando com o homem forte do circo já faz um tempo.",
  ui_story_5031_50310101_13_dialog_content = "Eu poderia até ser capaz de lançar vocês dois no ar sozinho!",
  ui_story_5031_50310101_14_dialog_content = "E-Que tal não, isso é muito perigoso... Além disso, pode haver danos colaterais...",
  ui_story_5031_50310101_15_dialog_content = "Ei, chefe, você poderia colocar alguns centavos, você sabe.",
  ui_story_5031_50310101_16_dialog_content = "Não podemos fazer um ensaio geral se nosso equipamento não estiver pronto!",
  ui_story_5031_50310101_17_dialog_content = "Considerando o quão talentosos somos, duvido que precisemos ensaiar!",
  ui_story_5031_50310101_18_dialog_content = "Subli... Essa não é uma maneira muito legal de falar com o Ringmaster Jeno.",
  ui_story_5031_50310101_19_dialog_content = "Hum? Estamos trabalhando nisso enquanto falamos.",
  ui_story_5031_50310101_20_dialog_content = "Os suprimentos de Elvis finalmente chegaram. Eles estão dando os retoques finais no seu equipamento agora.",
  ui_story_5031_50310101_21_dialog_content = "Se vocês três não quiserem ensaiar, vão em frente e encontrem um lugar para descansar um pouco.",
  ui_story_5031_50310101_22_dialog_content = "Rainbow, vá encontrar aquela figurante que dizia ser capaz de falar com os animais e traga-a.",
  ui_story_5031_50310101_23_dialog_content = "Ela pode substituir o domador de feras que ainda está doente de comer gelo raspado.",
  ui_story_5031_50310101_24_dialog_content = "Entendido!",
  ui_story_5031_50310101_25_dialog_content = "Você está pronta, senhorita Fia?",
  ui_story_5031_50310101_26_dialog_content = "J-Só um minuto!",
  ui_story_5031_50310101_27_dialog_content = "Vem, Bica! Por aqui, por favor!",
  ui_story_5031_50310101_28_dialog_content = "Ei.",
  ui_story_5031_50310101_29_dialog_content = "Como eu disse, Bica. Pule e dê uma cambalhota, ok?",
  ui_story_5031_50310101_30_dialog_content = "Oi!",
  ui_story_5031_50310101_31_dialog_content = "Por favor, Bica! Só desta vez, você poderia, por favor, me ouvir? Aquele ringmaster de aparência assustadora ainda está assistindo!",
  ui_story_5031_50310101_32_dialog_content = "Oi!!",
  ui_story_5031_50310101_33_dialog_content = "Ai! Acalme-se, vou pedir desculpas, apenas pare de me morder!",
  ui_story_5031_50310101_34_dialog_content = "Para para para!!",
  ui_story_5031_50310101_35_dialog_content = "O que está acontecendo lá em cima? Resolva seus problemas fora do palco, não interrompa o ensaio!",
  ui_story_5031_50310101_36_dialog_content = "Mestre de cerimônias Jeno!",
  ui_story_5031_50310101_37_dialog_content = "O que? Você e seu amiguinho finalmente terminaram o bate-papo?",
  ui_story_5031_50310101_38_dialog_content = "Ele não vai ouvir uma palavra do que eu digo, Ringmaster Jeno! Foi totalmente estragado podre!",
  ui_story_5031_50310101_39_dialog_content = "Mimado podre, você diz?",
  ui_story_5031_50310101_40_dialog_content = "Isso mesmo! E isso me mordeu muito forte agora também!",
  ui_story_5031_50310101_41_dialog_content = "Ah, isso é perfeitamente normal.",
  ui_story_5031_50310101_42_dialog_content = "Normal?!",
  ui_story_5031_50310101_43_dialog_content = "Como parte do circo, eles têm os mesmos privilégios que todos os outros. Ou seja, eles são livres para recusar qualquer trabalho sempre que não quiserem trabalhar.",
  ui_story_5031_50310101_44_dialog_content = "O que?!",
  ui_story_5031_50310101_45_dialog_content = "Este circo não é nada parecido com os que eu li! Nem mesmo perto!",
  ui_story_5031_50310101_46_dialog_content = "Todos os circos dos livros tratam seus animais com crueldade e usam o medo para fazê-los atuar. Você quer me dizer que seu circo não faz isso?",
  ui_story_5031_50310101_47_dialog_content = "E o que diabos lhe deu essa ideia?",
  ui_story_5031_50310101_48_dialog_content = "Eu nunca ouvi falar de tais métodos... Por que eu, ou qualquer outra pessoa, os machucaria? Afinal, eles não são apenas nossos colegas artistas, mas nossos queridos e importantes amigos.",
  ui_story_5031_50310101_49_dialog_content = "Basta olhar para esta Bica, e sua pelagem macia e fofa. Por que alguém machucaria algo tão precioso?",
  ui_story_5031_50310101_50_dialog_content = "Oi!",
  ui_story_5031_50310101_51_dialog_content = "De qualquer forma, meu circo nunca maltrataria nossos artistas animais assim. Nem agora, nem nunca.",
  ui_story_5031_50310101_52_dialog_content = "Cada domador que veio antes de você foi capaz de encontrar uma maneira de guiá-los através de suas performances. Você terá que encontrar seu próprio caminho, também.",
  ui_story_5031_50310101_53_dialog_content = "Com quem você pensa que está falando?!",
  ui_story_5031_50310101_54_dialog_content = "*Solucionando* Você deve saber, meu nome é Fia, a maior extrozoóloga do mundo! Minha conexão com bestas maravilhosas é mais forte do que a de qualquer outra pessoa!",
  ui_story_5031_50310101_55_dialog_content = "Como... Como eu poderia perder...",
  ui_story_5031_50310101_56_dialog_content = "Não se preocupe, PlayerName. Uma apresentação de balé não é um desafio para mim.",
  ui_story_5031_50310101_57_dialog_content = "Eu nunca pensei que veria você dançar balé, Carleen.",
  ui_story_5031_50310101_58_dialog_content = "No Colossus, ouvi outros aurorianos de Lumopolis falarem sobre suas impressionantes habilidades de balé. Alguém disse uma vez que você até surpreendeu um instrutor profissional com seu desempenho!",
  ui_story_5031_50310101_59_dialog_content = "Isso é verdade? Se assim for, não posso deixar de me sentir animado para vê-lo também!",
  ui_story_5031_50310101_60_dialog_content = "PlayerName!!",
  ui_story_5031_50310101_61_dialog_content = "Fia? Você não deveria estar praticando sua performance de domar feras? O que você está fazendo aqui?",
  ui_story_5031_50310101_62_dialog_content = "Wah, wah... Esses monstrinhos podres estão me deixando louco! Eles não ouvem porque não podem trabalhar sempre que quiserem!",
  ui_story_5031_50310101_63_dialog_content = "Quando penso nisso... e como meu próprio mestre manda em mim... eu... eu... Waaaaaaah!!!",
  ui_story_5031_50310101_64_dialog_content = "E-Ei, agora! Não chore, Fia...",
  ui_story_5031_50310101_65_dialog_content = "Você deveria ser o maior extrozoologista do mundo, lembra?",
  ui_story_5031_50310101_66_dialog_content = "Eu sei que! Então, por que o \"maior extrozoólogo do mundo\" ainda tem que se movimentar o dia todo cumprindo as ordens de seu mestre?!",
  ui_story_5031_50310101_67_dialog_content = "Tente não pensar nisso, ok? Lembra do jeito que você costuma me provocar? Você precisa desse tipo de energia agora!",
  ui_story_5031_50310101_68_dialog_content = "O QUE!?",
  ui_story_5031_50310101_69_dialog_content = "Bem, quero dizer... Lembra-se de todas aquelas dificuldades que superamos juntos? Foi tudo para realizar o seu maior sonho!",
  ui_story_5031_50310101_70_dialog_content = "Wah... Meu maior sonho... e as dificuldades que superamos...",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>Logo após chegar em Harbour City</color>",
  ui_story_5031_50310101_72_dialog_content = "Obrigado por convidar Vice e eu para Harbour City, Carleen.",
  ui_story_5031_50310101_73_dialog_content = "Este lugar é muito bom, não é? Tão calmo e tranquilo... Um lugar perfeito para descansar e relaxar!",
  ui_story_5031_50310101_74_dialog_content = "Estou tão feliz que todos podem vir também!",
  ui_story_5031_50310101_75_dialog_content = "O prazer é meu. Todo mundo tem trabalhado muito ultimamente, então pensei que todos nós poderíamos usar uma pequena pausa para recuperar nossos corpos e mentes.",
  ui_story_5031_50310101_76_dialog_content = "Eu era apenas uma garotinha da última vez que vim a Harbor City, mas mesmo assim deixou uma impressão profunda em mim.",
  ui_story_5031_50310101_77_dialog_content = "Eu nunca pensei que este lugar iria prosperar tanto, no entanto. O atual laird da cidade deve ser um líder bastante sábio.",
  ui_story_5031_50310101_78_dialog_content = "<size=33>Encontrei você...</size>",
  ui_story_5031_50310101_79_dialog_content = "Você acha que ele é qualquer coisa como Lord Schwartz?",
  ui_story_5031_50310101_80_dialog_content = "Vendo o olhar feliz no rosto de todos aqui... Isso realmente me faz pensar que tipo de pessoa está no comando por aqui.",
  ui_story_5031_50310101_81_dialog_content = "Eu... não acredito que os dois sejam tão parecidos.",
  ui_story_5031_50310101_82_dialog_content = "Por cortesia, devemos fazer uma visita ao laird da cidade agora que estamos aqui.",
  ui_story_5031_50310101_83_dialog_content = "Eu vi um cartaz na rua agora, que dizia algo sobre um circo e um carnaval a bordo de um dos grandes navios de cruzeiro?",
  ui_story_5031_50310101_84_dialog_content = "Podíamos perguntar ao laird da cidade mais sobre isso também.",
  ui_story_5031_50310101_85_dialog_content = "Se estamos aqui para relaxar, então esta é uma ótima maneira de começar! Uma verdadeira experiência de \"férias de verão\"!",
  ui_story_5031_50310101_86_dialog_content = "Sim! Eu não me importaria de perguntar sobre o que mais fazer aqui em Harbour City, também! Ou que tipo de guloseimas saborosas eles oferecem!",
  ui_story_5031_50310101_87_dialog_content = "Vice mal pode conter sua excitação... Acho que realmente faz muito tempo desde que fizemos uma pausa.",
  ui_story_5031_50310101_88_dialog_content = "<size=33>Alvo bloqueado—PlayerName!</size>",
  ui_story_5031_50310101_89_dialog_content = "Bem, o que estamos esperando? Vamos goo—<size=50>AI!</size>",
  ui_story_5031_50310101_90_dialog_content = "Ai, ai! Minhas costas!",
  ui_story_5031_50310101_91_dialog_content = "(Espere, isso parece muito familiar...)",
  ui_story_5031_50310101_92_dialog_content = "Fique para trás, ou eu vou pedir ajuda! Quero dizer!",
  ui_story_5031_50310101_93_dialog_content = "Vai-",
  ui_story_5031_50310101_94_option_content = "Força... Ai!!",
  ui_story_5031_50310101_95_dialog_content = "Minhas costas!!",
  ui_story_5031_50310101_96_dialog_content = "Lo lo lo!",
  ui_story_5031_50310101_97_dialog_content = "Bom trabalho, Kylo. Ok, recue pela floresta como planejado!",
  ui_story_5031_50310101_98_dialog_content = "Mas eu só... Olha, eu só quero um amigo.",
  ui_story_5031_50310101_99_dialog_content = "Ei...",
  ui_story_5031_50310101_100_dialog_content = "Todo mundo diz que eu só posso fazer amizade com bestas maravilhosas. Eu só queria provar que não era verdade, e que eu posso fazer amizade com aurorianos e celestitas também...",
  ui_story_5031_50310101_101_dialog_content = "Heehee... Ei, PlayerName, isso faz de você meu primeiro amigo!",
  ui_story_5031_50310101_102_dialog_content = "Estou tão feliz que você é meu amigo, PlayerName!",
  ui_story_5031_50310101_103_dialog_content = "Veja, mestre! Eu fiz um amigo!",
  ui_story_5031_50310101_104_dialog_content = "S-Então é mesmo você, Fia!!",
  ui_story_5031_50310101_105_dialog_content = "Por que você me atacou daquela lata de lixo?!",
  ui_story_5031_50310101_106_dialog_content = "Heehe! Peguei, PlayerName!",
  ui_story_5031_50310101_107_dialog_content = "Fia?",
  ui_story_5031_50310101_108_dialog_content = "Sim, esta é a Fia. Não se importe com ela, é assim que ela é.",
  ui_story_5031_50310101_109_dialog_content = "Então este é o pequeno extrozoologista que você encontrou antes?",
  ui_story_5031_50310101_110_dialog_content = "Já ouvi falar deles e de seu campo de estudo, mas nunca esperei encontrar um tão jovem.",
  ui_story_5031_50310101_111_dialog_content = "Já faz um tempo, Fia.",
  ui_story_5031_50310101_112_dialog_content = "Oi, Vice! Há quanto tempo!",
  ui_story_5031_50310101_113_dialog_content = "Permita-me apresentar-me, senhorita Carleen. Meu nome é Fia e sou a extrozoóloga número um do mundo!",
  ui_story_5031_50310101_114_dialog_content = "Ou pelo menos serei algum dia. Meu aprendizado acabou, então ainda tenho muito espaço para melhorar. Se eu causar algum problema para você no futuro, por favor, tente ser paciente comigo!",
  ui_story_5031_50310101_115_dialog_content = "Um prazer conhecê-lo. Eu sou Carleen de Lumópolis. Sabe, você me lembra muito Raphael.",
  ui_story_5031_50310101_116_dialog_content = "Eu deveria apresentá-lo quando a chance surgir. Imagino que vocês dois vão se dar muito bem.",
  ui_story_5031_50310101_117_dialog_content = "Espere um segundo...",
  ui_story_5031_50310101_118_dialog_content = "Por que você está agindo tão fofo e inocente, de repente?",
  ui_story_5031_50310101_119_dialog_content = "Do que você está falando, PlayerName? Eu sou sempre tão doce, não sou? Não é legal dizer algo assim, você sabe!",
  ui_story_5031_50310101_120_dialog_content = "Sim, claro... Vamos ver quanto tempo você aguenta dessa vez, Fia.",
  ui_story_5031_50310101_121_dialog_content = "Enfim, o que você está fazendo aqui em primeiro lugar? E onde está Kyllo?",
  ui_story_5031_50310101_122_dialog_content = "Shhh! Não tão alto! Se você quer saber, Kyllo e eu estamos em um <color=#FFB400>missão secreta</color>. Ordens do mestre!",
  ui_story_5031_50310101_123_dialog_content = "Kyllo está investigando as águas próximas enquanto falamos!",
  ui_story_5031_50310101_124_dialog_content = "\"Missão secreta\"? Ele não te mandou em alguma perseguição de novo, não é?",
  ui_story_5031_50310101_125_dialog_content = "Além disso... Kyllo estava enorme na última vez que vi vocês! Você não acha que vai chamar muita atenção?",
  ui_story_5031_50310101_126_dialog_content = "Ah! Essa era sua forma gigante! Kyllo desde então dominou a arte de alternar entre formas, sabe?",
  ui_story_5031_50310101_127_dialog_content = "O Mestre disse que com treinamento suficiente... poderia até atingir uma forma humana!",
  ui_story_5031_50310101_128_dialog_content = "Isso... soa um pouco assustador, para ser honesto.",
  ui_story_5031_50310101_129_dialog_content = "Não tenha medo! Não há nada a temer, contanto que você não enlouqueça Kyllo!",
  ui_story_5031_50310101_130_dialog_content = "Mas chega de Kyllo! A missão em questão é de vital importância e tem a ver com uma <color=#FFB400>exótico</color> bicho maravilhoso!",
  ui_story_5031_50310101_131_dialog_content = "Erm... eu não pretendia bisbilhotar, de forma alguma...",
  ui_story_5031_50310101_132_dialog_content = "Mas você não acha que deveria falar baixo, Fia?",
  ui_story_5031_50310101_133_dialog_content = "Além disso, é seguro assumir que sua razão para procurar PlayerName é recrutá-lo para sua \"missão secreta\"?",
  ui_story_5031_50310101_134_dialog_content = "Opa! Acho que eu estava sendo um pouco barulhento, hein?",
  ui_story_5031_50310101_135_dialog_content = "Bem, já que vocês dois são amigos íntimos de PlayerName, acho que posso confiar em vocês com os detalhes de qualquer maneira.",
  ui_story_5031_50310101_136_dialog_content = "Agora, deixe-me explicar a situação o mais claramente possível.",
  ui_story_5031_50310101_137_dialog_content = "Tudo começou há poucos dias...",
  ui_story_5031_50310101_138_dialog_content = "O que! Cidade do Porto? Sério?!",
  ui_story_5031_50310101_139_dialog_content = "Uau! Ouvi dizer que a paisagem é incrível lá, e que há muita comida saborosa também!",
  ui_story_5031_50310101_140_dialog_content = "Eu nunca soube que você se importava tanto, Mestre! Me mandando de férias depois de todo o trabalho duro que fiz...",
  ui_story_5031_50310101_141_dialog_content = "As praias de lá são bem famosas, agora que me lembro. Eu preciso ir escolher um maiô!",
  ui_story_5031_50310101_142_dialog_content = "Você está ficando muito à frente de si mesmo, você sabe...",
  ui_story_5031_50310101_143_dialog_content = "Se fosse uma viagem tão legal, minhas malas já estariam prontas.",
  ui_story_5031_50310101_144_dialog_content = "Estou mandando você em uma missão, Fia, não em férias.",
  ui_story_5031_50310101_145_dialog_content = "Aqui está algum dinheiro para despesas de viagem. Vá em frente.",
  ui_story_5031_50310101_146_dialog_content = "Ei! O que eu devo fazer com uma mudança de idiota como esta?!",
  ui_story_5031_50310101_147_dialog_content = "E-Espere, Mestre! Onde você está indo?!",
  ui_story_5031_50310101_148_dialog_content = "Grrr... Eu deveria saber! Aquele meu mestre imprestável nunca seria desse tipo!",
  ui_story_5031_50310101_149_dialog_content = "Uh... Acha que pode ir direto ao ponto da história, Fia? Acho que já ouvimos o suficiente sobre seu mestre...",
  ui_story_5031_50310101_150_dialog_content = "Estou chegando a isso!",
  ui_story_5031_50310101_151_dialog_content = "Ahem... O objetivo de nossa missão é uma besta maravilhosa conhecida como <color=#FFB400>Baleia-nuvem</color>.",
  ui_story_5031_50310101_152_dialog_content = "Meu mestre está rastreando seu Lumina especial há algum tempo. Há sinais de que chegou às águas de Harbour City.",
  ui_story_5031_50310101_153_dialog_content = "Mas depois que chegamos, o Lumina de repente desapareceu...",
  ui_story_5031_50310101_154_dialog_content = "Minha teoria é que, porque desapareceu tão repentinamente e completamente, o Cloudwhale não deve ter deixado Harbour City... Em vez disso, algo deve ter acontecido com ele!",
  ui_story_5031_50310101_155_dialog_content = "Entendo... Isso soa ameaçador, de fato.",
  ui_story_5031_50310101_156_dialog_content = "Sem brincadeira, e mais ainda... Meu mestre diz que o poder deste Cloudwhale é ainda maior que o de um Drakolion.",
  ui_story_5031_50310101_157_dialog_content = "As lendas dizem que seu poder faz com que Eclipsites se encolha de medo, e que seu Lumina pode dissipar até mesmo o Darkflow mais espesso.",
  ui_story_5031_50310101_158_dialog_content = "Diz-se também que o Cloudwhale tem uma vida útil extremamente longa, por isso é altamente improvável que tenha morrido de causas naturais.",
  ui_story_5031_50310101_159_dialog_content = "Considerando tudo isso, meu mestre está preocupado que tenha caído em mãos erradas.",
  ui_story_5031_50310101_160_dialog_content = "O Cloudwhale é dócil por natureza, mas se seu poder for mal utilizado pelas pessoas erradas, os resultados podem ser catastróficos...",
  ui_story_5031_50310101_161_dialog_content = "Se tudo for como você diz... então não podemos ficar de braços cruzados.",
  ui_story_5031_50310101_162_dialog_content = "Você tem alguma pista do paradeiro dele?",
  ui_story_5031_50310101_163_dialog_content = "Hmm... Nenhuma! Depois que meu mestre jogou essa tarefa em mim, ele saiu sem dizer outra palavra...",
  ui_story_5031_50310101_164_dialog_content = "Então você estava vagando sem rumo por Harbour City esse tempo todo até encontrar meu rastro? Então você acabou de me emboscar aqui?",
  ui_story_5031_50310101_165_dialog_content = "Você acertou em cheio na cabeça, PlayerName! Não só isso, mas o dinheiro que o Mestre me deu para as despesas de viagem já foi gasto...",
  ui_story_5031_50310101_166_dialog_content = "Não sei o que fazer se você não apareceu, PlayerName!",
  ui_story_5031_50310101_167_dialog_content = "Eu sabia.",
  ui_story_5031_50310101_168_dialog_content = "Por que não começamos coletando informações? Estávamos a caminho de visitar o laird da cidade.",
  ui_story_5031_50310101_169_dialog_content = "Ele pode saber uma coisa ou duas sobre a situação.",
  ui_story_5031_50310101_170_dialog_content = "Ok! eu ouviria Carleen. Vamos lá!",
  ui_story_5031_50310101_171_dialog_content = "Ei! Por que se apressar, Fia? Você sabe mesmo para onde está indo?",
  ui_story_5031_50310101_172_dialog_content = "Ela está realmente empolgada, não está?",
  ui_story_5031_50310201_1_dialog_content = "Laird <color=#FFB400>Elvis</color>, os soldados leais a você estão prontos agora.",
  ui_story_5031_50310201_2_dialog_content = "As coisas estão acontecendo exatamente como você planejou, senhor. Usaremos o transporte de suprimentos e fogos de artifício para Esmeralda como cobertura.",
  ui_story_5031_50310201_3_dialog_content = "Sim, eu vejo.",
  ui_story_5031_50310201_4_dialog_content = "Muito bem, Capitão Patou. Talvez você seja realmente o único em quem posso confiar desta vez...",
  ui_story_5031_50310201_5_dialog_content = "Como você diz, senhor. Por favor, deixe o resto comigo. Foi uma grande honra servir ao meu laird.",
  ui_story_5031_50310201_6_dialog_content = "Infelizmente... Se houvesse mais tempo para esperar, eu não o colocaria em tal risco.",
  ui_story_5031_50310201_7_dialog_content = "Laird Elvis! Capitão Patu! F-Perdoe a intrusão!",
  ui_story_5031_50310201_8_dialog_content = "Que grosseria... Pensei ter deixado perfeitamente claro que ninguém pode entrar?",
  ui_story_5031_50310201_9_dialog_content = "S-Sim, Capitão. Por favor, perdoe-me, mas um nobre veio visitar...",
  ui_story_5031_50310201_10_dialog_content = "Que nobre? Componha-se, soldado! Você está a serviço da Casa Modali, agora aja como tal!",
  ui_story_5031_50310201_11_dialog_content = "Entendido! eu-é a senhora Carleen, a princesa de Lumopolis, senhor!",
  ui_story_5031_50310201_12_dialog_content = "O que? Princesa Carleen de Lumopolis, você diz?",
  ui_story_5031_50310201_13_dialog_content = "De acordo com Carleen, Harbour City ficou sob a jurisdição e proteção oficial de Lumopolis pouco antes da Crise de Darkover.",
  ui_story_5031_50310201_14_dialog_content = "Isso significa que eles confiaram em sua própria força para defender sua casa antes disso?",
  ui_story_5031_50310201_15_dialog_content = "Documentos históricos afirmam que Harbour City já foi repleta de Eclipsites. Esses desafortunados moradores lutaram dia e noite para evitar que ela caísse no flagelo do Eclipsite.",
  ui_story_5031_50310201_16_dialog_content = "Ao longo da batalha prolongada, os governantes da Casa <color=#FFB400>Modali</color>, que possuía imensa Lumina, aliada a outras potências.",
  ui_story_5031_50310201_17_dialog_content = "Depois de inúmeras batalhas sangrentas, eles finalmente conseguiram expulsar completamente esses invasores.",
  ui_story_5031_50310201_18_dialog_content = "Err...",
  ui_story_5031_50310201_19_dialog_content = "Abençoado pelo <color=#FFB400>Deus da Luz</color>, esta cidade raramente foi perturbada por Eclipsites desde então.",
  ui_story_5031_50310201_20_dialog_content = "As pessoas agora vivem suas vidas em paz, e a economia floresceu significativamente.",
  ui_story_5031_50310201_21_dialog_content = "Sinto-me honrado por conhecer tão bem a história de Harbour City, Sua Alteza.",
  ui_story_5031_50310201_22_dialog_content = "Também sou grato a você e a Lumopolis por sua generosa proteção. Afinal, nunca teríamos sobrevivido à Crise de Darkover dependendo do <color=#FFB400>Bênção do Deus da Luz</color> sozinho.",
  ui_story_5031_50310201_23_dialog_content = "Sou Elvis Modali, descendente da Casa Modali e laird de Harbour City.",
  ui_story_5031_50310201_24_dialog_content = "(Estranho... Por que a Lumina ao redor deste homem está tão fraca?)",
  ui_story_5031_50310201_25_dialog_content = "Saudações, Laird Elvis. Rezo para que nossa visita não tenha lhe causado muitos inconvenientes.",
  ui_story_5031_50310201_26_dialog_content = "Claro que não, Alteza. Eu só gostaria que você tivesse mandado uma mensagem antes, para que eu pudesse ter recebido você e seus companheiros adequadamente.",
  ui_story_5031_50310201_27_dialog_content = "Isso não será necessário, pois esperávamos vê-lo sem a habitual fanfarra ou formalidades. Por favor, não seja especial conosco.",
  ui_story_5031_50310201_28_dialog_content = "Afinal, viemos para Harbour City não como delegados de qualquer tipo, mas como viajantes comuns de férias.",
  ui_story_5031_50310201_29_dialog_content = "Tenha certeza, Sua Alteza, eu entendo perfeitamente sua situação. Posso presumir que esses dois companheiros seus são ninguém menos que a Srta. Vice e o lendário celestita?",
  ui_story_5031_50310201_30_dialog_content = "Saudações, eu sou PlayerName.",
  ui_story_5031_50310201_31_dialog_content = "E eu sou Vice, Laird Elvis. Embora eu nunca esperasse que você reconhecesse PlayerName, muito menos eu.",
  ui_story_5031_50310201_32_dialog_content = "U-Um...!",
  ui_story_5031_50310201_33_dialog_content = "Oh? E quem pode ser?",
  ui_story_5031_50310201_34_dialog_content = "H-Olá! Meu nome é Fia! Eu sou um extrozoólogo profissional, bem como amigo de PlayerName, Vice, e Carleen!",
  ui_story_5031_50310201_35_dialog_content = "Um extrozoólogo? Hehe, entendo... Prazer em conhecê-la, Srta. Fia.",
  ui_story_5031_50310201_36_dialog_content = "Eu preparei um banquete. Como laird de Harbour City, ficarei honrado se você se juntar a mim para uma refeição.",
  ui_story_5031_50310201_37_dialog_content = "Entendo... E você está bastante interessado no evento realizado a bordo do <color=#FFB400>Esmeralda</color>, Senhorita Vice?",
  ui_story_5031_50310201_38_dialog_content = "Na verdade, fui eu quem convidou <color=#FFB400>o ilusionista e o circo do velho Bill</color> e o Emerald para Harbour City.",
  ui_story_5031_50310201_39_dialog_content = "Minha esperança é que eles possam entregar uma experiência inesquecível para as pessoas da minha cidade neste verão.",
  ui_story_5031_50310201_40_dialog_content = "O navio inteiro pertence ao circo? Com certeza tem um ar romântico...",
  ui_story_5031_50310201_41_dialog_content = "De fato. Se você e seus acompanhantes estiverem interessados, você pode sempre considerar participar das festividades.",
  ui_story_5031_50310201_42_dialog_content = "O apresentador é meu amigo de infância. Embora não nos vejamos há algum tempo, ele é tão capaz quanto confiável.",
  ui_story_5031_50310201_43_dialog_content = "Não tenho dúvidas de que ele proporcionará o melhor entretenimento para toda a cidade.",
  ui_story_5031_50310201_44_dialog_content = "Ah... O navio de cruzeiro!",
  ui_story_5031_50310201_45_dialog_content = "Hum, desculpe-me! Um de seus amigos poderia nos mostrar o interior do navio, Laird Elvis?",
  ui_story_5031_50310201_46_dialog_content = "Hum?",
  ui_story_5031_50310201_47_dialog_content = "<size=33>Fia! Que tipo de pedido estranho é esse?</size>",
  ui_story_5031_50310201_48_dialog_content = "Acabei de me lembrar que Kyllo me disse que um navio estranho e enorme havia atracado em Harbour City não muito tempo atrás.",
  ui_story_5031_50310201_49_dialog_content = "Se o Cloudwhale desapareceu de repente, ele poderia ter sido mantido dentro desse tipo de navio!",
  ui_story_5031_50310201_50_dialog_content = "Minhas desculpas, mas temo que não possa conceder a você este pedido.",
  ui_story_5031_50310201_51_dialog_content = "É... Por quê?",
  ui_story_5031_50310201_52_dialog_content = "Eu mesmo não tenho certeza dos detalhes, mas isso diz respeito a uma das regras do circo.",
  ui_story_5031_50310201_53_dialog_content = "Ontem, subi a bordo do navio para falar com <color=#FFB400>Jeno</color>, o apresentador, sobre fornecer suprimentos para sua trupe.",
  ui_story_5031_50310201_54_dialog_content = "Achei que Jeno me daria um passeio pelas cabanas, mas ele só estava disposto a me mostrar até o corredor quando discutimos nossos negócios.",
  ui_story_5031_50310201_55_dialog_content = "Por curiosidade, mencionei que desejava ver o interior deste grande e maravilhoso navio...",
  ui_story_5031_50310201_56_dialog_content = "Mas ele me recusou, afirmando que era política deles que apenas os membros do circo pudessem ir mais longe na cabine.",
  ui_story_5031_50310201_57_dialog_content = "Como amigo e parceiro de negócios, isso foi o máximo que consegui. Temo que a entrada para você esteja ainda mais fora de questão.",
  ui_story_5031_50310201_58_dialog_content = "Existe alguma razão em particular pela qual você gostaria de entrar no navio? Posso negociar com o mestre de cerimônias em seu nome.",
  ui_story_5031_50310201_59_dialog_content = "Na verdade, Fia era...",
  ui_story_5031_50310201_60_dialog_content = "Ahaha! Isso também foi por curiosidade! Eu venho de um lugar muito pequeno e nunca vi o interior de um navio antes.",
  ui_story_5031_50310201_61_dialog_content = "<size=33>Não se esqueça, estamos em uma missão secreta! Não podemos derramar nenhuma informação sobre nosso objetivo exótico!</size>",
  ui_story_5031_50310201_62_dialog_content = "Eu entendo como você deve se sentir, Srta. Fia. Afinal, navios tão grandes quanto o Emerald não são exatamente comuns, mesmo em Harbor City.",
  ui_story_5031_50310201_63_dialog_content = "Tenho certeza de que você também não está sozinho. Muitos frequentadores do carnaval devem estar morrendo de vontade de saber mais sobre o navio e o que está dentro dele.",
  ui_story_5031_50310201_64_dialog_content = "Bem... Permita-me tentar falar com Jeno mais uma vez.",
  ui_story_5031_50310201_65_dialog_content = "Sério? Muito obrigado senhor!",
  ui_story_5031_50310201_66_dialog_content = "É um prazer, mas, por favor, tente não ter muitas esperanças. Jeno foi rápido em recusar até mesmo seu patrocinador.",
  ui_story_5031_50310201_67_dialog_content = "No entanto, haverá muitas outras festividades para participar no convés, como concurso de culinária, carnaval e show de circo.",
  ui_story_5031_50310201_68_dialog_content = "Acredito que também irão satisfazer sua curiosidade, Srta. Fia.",
  ui_story_5031_50310201_69_dialog_content = "*Tosse*",
  ui_story_5031_50310201_70_dialog_content = "Senhor!",
  ui_story_5031_50310201_71_dialog_content = "Estou bem, Patou.",
  ui_story_5031_50310201_72_dialog_content = "Parece que na excitação de Sua Alteza e da visita de todos, esqueci completamente de tomar meu remédio.",
  ui_story_5031_50310201_73_dialog_content = "Laird Elvis...",
  ui_story_5031_50310201_74_dialog_content = "Obrigado por sua amável hospitalidade.",
  ui_story_5031_50310201_75_dialog_content = "A honra é minha, Alteza. Espero que meu lapso momentâneo de saúde não tenha estragado sua diversão.",
  ui_story_5031_50310201_76_dialog_content = "De jeito nenhum. Por favor, cuide bem de si mesmo, Laird.",
  ui_story_5031_50310201_77_dialog_content = "Nós vamos para o Esmeralda em breve para ver o carnaval. Por favor, não se levante por nossa causa. Estaremos a caminho.",
  ui_story_5031_50310201_78_dialog_content = "... Eu entendo. No entanto, tenho que preparar um presente para Vossa Alteza antes de partir para a Esmeralda mais tarde.",
  ui_story_5031_50310201_79_dialog_content = "É costume os súditos oferecerem presentes aos seus soberanos. Por favor, aceite-o, Sua Alteza.",
  ui_story_5031_50310201_80_dialog_content = "Se você insiste.",
  ui_story_5031_50310201_81_dialog_content = "Venham todos. É hora de ir.",
  ui_story_5031_50310201_82_dialog_content = "...",
  ui_story_5031_50310201_83_dialog_content = "Senhor.",
  ui_story_5031_50310201_84_dialog_content = "Ordene aos nossos homens que se preparem, Patou.",
  ui_story_5031_50310201_85_dialog_content = "Poderia... Lumopolis poderia ter descoberto nossas ações tão rapidamente?",
  ui_story_5031_50310201_86_dialog_content = "Acho que ainda é cedo para dizer com certeza... Mas, por enquanto, devemos ficar de olho neles.",
  ui_story_5031_50310201_87_dialog_content = "Não importa o que aconteça, o plano deve prosseguir hoje.",
  ui_story_5031_50310201_88_dialog_content = "Perdoe minha ignorância, senhor, mas você não pode simplesmente pedir ajuda ao mestre de cerimônias Jeno?",
  ui_story_5031_50310201_89_dialog_content = "Como você disse, ele é seu amigo de infância.",
  ui_story_5031_50310201_90_dialog_content = "As coisas não são tão simples, Patou. Nossa história compartilhada não significa necessariamente que posso confiar nele.",
  ui_story_5031_50310201_91_dialog_content = "Afinal, ele negou meu pedido para ver o interior de sua nave sem hesitação.",
  ui_story_5031_50310201_92_dialog_content = "De acordo com minhas descobertas, ele atualmente deve sua lealdade ao <color=#FFB400>Ordem Verdadeira</color>.",
  ui_story_5031_50310201_93_dialog_content = "Se nosso objetivo for revelado devido à nossa imprudência... todo o plano pode muito bem desmoronar em um instante.",
  ui_story_5031_50310201_94_dialog_content = "Neste ponto, não tenho certeza se posso ou não confiar naquele homem, a quem uma vez chamei de \"amigo\"...",
  ui_story_5031_50310201_95_dialog_content = "Eu entendo, senhor. Deixe para mim.",
  ui_story_5031_50310201_96_dialog_content = "Muito bem. Vou continuar olhando para Jeno para ver se ele ainda é a mesma pessoa que eu conheci...",
  ui_story_5031_50310201_97_dialog_content = "Laird Elvis parece ser uma pessoa muito legal, hein? Ele nos recebeu tão calorosamente e também foi gentil com Vice e eu.",
  ui_story_5031_50310201_98_dialog_content = "Sim, ele parece muito mais gentil do que alguns dos nobres que conhecemos antes. Ele não se comporta com o mesmo tipo de pretensão que eles.",
  ui_story_5031_50310201_99_dialog_content = "De fato. A Casa Modali é bem diferente de muitas outras famílias nobres. Eles são incrivelmente protetores de seu próprio povo e também são amados por muitos.",
  ui_story_5031_50310201_100_dialog_content = "Quando se trata de governança, sua família é uma das melhores, mas infelizmente...",
  ui_story_5031_50310201_101_dialog_content = "Ah... Tem algo a ver com o quão fraco é o Lumina dele?",
  ui_story_5031_50310201_102_dialog_content = "Parece que você também notou. Quando Elvis começou a tossir incontrolavelmente mais cedo... bem, vamos apenas dizer que não foi devido a um resfriado comum.",
  ui_story_5031_50310201_103_dialog_content = "Até a cicatriz em seu rosto... Sua doença é conhecida por outros como a <color=#FFB400>Síndrome de Modali</color>.",
  ui_story_5031_50310201_104_dialog_content = "Então a cicatriz em seu rosto é devido à sua doença? Eu nunca teria adivinhado...",
  ui_story_5031_50310201_105_dialog_content = "Então... É sério?",
  ui_story_5031_50310201_106_dialog_content = "Eu não entendo muito sobre a doença além do nome, para ser honesto. Só fiquei sabendo disso de passagem, enquanto fazia meus estudos de história.",
  ui_story_5031_50310201_107_dialog_content = "Quando cedi à minha curiosidade, rapidamente descobri que as informações sobre a Síndrome de Modali e a própria família eram surpreendentemente escassas.",
  ui_story_5031_50310201_108_dialog_content = "Tudo o que aprendi é que esta doença esgota rapidamente o Lumina das vítimas e impede que ele se recupere aos níveis normais por um período prolongado de tempo.",
  ui_story_5031_50310201_109_dialog_content = "Não é tão debilitante para aqueles com níveis acima da média de Lumina, mas para outros... contrair a doença de forma rápida e grave prejudica sua capacidade de levar uma vida normal.",
  ui_story_5031_50310201_110_dialog_content = "Em casos extremos, a doença pode até ser fatal.",
  ui_story_5031_50310201_111_dialog_content = "É tão ruim assim?!",
  ui_story_5031_50310201_112_dialog_content = "Sim... Mas esta doença é extremamente única e só apareceu em Harbor City. Como tal, os estudiosos acreditam que de alguma forma está ligado a esta região.",
  ui_story_5031_50310201_113_dialog_content = "A população de Harbour City, por outro lado, está inteiramente convencida de que a doença é um símbolo de sua <color=#FFB400>linhagem heróica</color>.",
  ui_story_5031_50310201_114_dialog_content = "Eles dizem que seus ancestrais, aqueles que se defenderam dos Eclipsitas no passado, corajosamente e voluntariamente suportaram essa maldição pelo bem de seu povo.",
  ui_story_5031_50310201_115_dialog_content = "Como tal, seus descendentes também têm a chance de contraí-lo.",
  ui_story_5031_50310201_116_dialog_content = "Felizmente, parece que os casos confirmados desta doença têm diminuído gradualmente nos últimos anos.",
  ui_story_5031_50310201_117_dialog_content = "Oh... eu vejo, eu vejo.",
  ui_story_5031_50310201_118_dialog_content = "Você não precisa fingir que entendeu tudo isso, sabe?",
  ui_story_5031_50310201_119_dialog_content = "O-Claro que entendi! Só porque sou jovem não significa que sou burro!",
  ui_story_5031_50310201_120_dialog_content = "Em todo caso, acho que o laird entende seu próprio destino melhor do que ninguém.",
  ui_story_5031_50310201_121_dialog_content = "Assim como eu, nasci para ser o maior extrozoologista do mundo!",
  ui_story_5031_50310201_122_dialog_content = "Carregar a glória de incontáveis gerações passadas... Deve ser um fardo complicado e pesado de carregar.",
  ui_story_5031_50310201_123_dialog_content = "Como pessoas de fora, acho que não temos o direito de julgar a situação.",
  ui_story_5031_50310201_124_dialog_content = "Fia faz um ponto muito bom.",
  ui_story_5031_50310201_125_dialog_content = "Sim, ela faz, embora ela pudesse ter feito o mesmo ponto por não dizer nada também.",
  ui_story_5031_50310201_126_dialog_content = "Ele Ele! De qualquer forma, devemos realmente nos concentrar em embarcar no Emerald e dar uma olhada ao redor. Venha, vamos!",
  ui_story_5031_50310201_127_dialog_content = "Apresse-se e salve o exótico. Complete esta missão e terei tempo para jogar!",
  ui_story_5031_50310201_128_dialog_content = "Espere um segundo, Fia! O que te dá tanta certeza de que você conseguirá acessar o interior da Esmeralda, afinal?",
  ui_story_5031_50310201_129_dialog_content = "Vou ter que confiar no meu charme incrível, não é?",
  ui_story_5031_50310201_130_dialog_content = "Que \"encanto incrível\"... Você teria mais sorte fingindo ser um pequeno animal e fazendo um teste para o circo.",
  ui_story_5031_50310201_131_dialog_content = "Argh!",
  ui_story_5031_50310201_132_dialog_content = "Essa foi outra piada curta, não foi?!",
  ui_story_5031_50310201_133_dialog_content = "Venha aqui!",
  ui_story_5031_50310201_134_dialog_content = "E-Ei, isso doeu! Pare de puxar tanto, Fia!",
  ui_story_5031_50310201_135_dialog_content = "Você está indo direto para o oceano, seu grande idiota! Kyllo pode te jogar como uma bola, por tudo que me importa!",
  ui_story_5031_50310201_136_dialog_content = "O que? Você está chamando Kyllo de foca ou algo assim? Eu não acho que Kyllo iria gostar disso!",
  ui_story_5031_50310201_137_dialog_content = "Eu não me importo!",
  ui_story_5031_50310201_138_dialog_content = "Ufa... Vê-los discutindo assim de alguma forma me deixa mais à vontade.",
  ui_story_5031_50310201_139_dialog_content = "Sim... Faz tempo que não relaxamos assim.",
  ui_story_5031_50310201_140_dialog_content = "Espere aí!",
  ui_story_5031_50310201_141_dialog_content = "A-Tudo bem, pare com isso! O que é isso, Carleen?",
  ui_story_5031_50310201_142_dialog_content = "Ali... O que os Eclipsites estão fazendo nesta praia?!",
  ui_story_5031_50310201_143_dialog_content = "Preparem-se para a batalha e fiquem em guarda, pessoal! Algo está estranho sobre esses Eclipses...",
  ui_story_5031_50310202_1_dialog_content = "Graah...",
  ui_story_5031_50310202_2_dialog_content = "Por que esses Eclipses eram tão fracos...?",
  ui_story_5031_50310202_3_dialog_content = "Vocês, tudo bem?",
  ui_story_5031_50310202_4_dialog_content = "Espere... V-você é a princesa Carleen! M-Minhas desculpas se você se machucou... Foi por causa da minha negligência que aqueles Eclipsites conseguiram!",
  ui_story_5031_50310202_5_dialog_content = "Não há necessidade de pânico. Não somos cidadãos desarmados e somos perfeitamente capazes de nos defender.",
  ui_story_5031_50310202_6_dialog_content = "No entanto, você e seus homens precisam permanecer vigilantes o tempo todo. O perigo pode estar à espreita em cada esquina.",
  ui_story_5031_50310202_7_dialog_content = "Entendido! Obrigado por sua orientação, Sua Alteza! Aumentaremos nossas patrulhas, bem como investigaremos a origem desses Eclipsitos!",
  ui_story_5031_50310202_8_dialog_content = "Muito bem, agora mãos à obra, soldado.",
  ui_story_5031_50310202_9_dialog_content = "Sim, Sua Alteza!",
  ui_story_5031_50310202_10_dialog_content = "Isso foi tão legal, Carleen! Você parecia e soava como uma rainha!",
  ui_story_5031_50310202_11_dialog_content = "Claro que sim, Fia! Carleen é filha do Senhor de Lumopolis, e naturalmente ela vai se tornar uma governante sábia um dia.",
  ui_story_5031_50310202_12_dialog_content = "Th-Obrigado... Mas ainda tenho muito que aprender.",
  ui_story_5031_50310202_13_dialog_content = "Mas chega disso. A Esmeralda está logo à frente, então vamos continuar.",
  ui_story_5031_50310202_14_dialog_content = "Quem quiser participar do concurso de culinária, venha por aqui!",
  ui_story_5031_50310202_15_dialog_content = "Parece que estamos aqui, hein? Este lugar com certeza é animado!",
  ui_story_5031_50310202_16_dialog_content = "Vamos começar coletando informações primeiro, PlayerName.",
  ui_story_5031_50310202_17_dialog_content = "Sim, isso faz sentido.",
  ui_story_5031_50310202_18_dialog_content = "Olá, posso te perguntar sobre o carnaval...?",
  ui_story_5031_50310202_19_dialog_content = "Ei! Bem-vindo ao Circo do Ilusionista e do Velho Bill!",
  ui_story_5031_50310202_20_dialog_content = "Parece que esta é a primeira vez que você vê nosso circo, certo? Não precisam ser tímidos, pessoal! Por aqui!",
  ui_story_5031_50310202_21_dialog_content = "Só não crie problemas a bordo da nave, ok? Eu não serei tão legal se você começar a causar confusão...",
  ui_story_5031_50310202_22_dialog_content = "Vamos, Merylt! O mestre de cerimônias Jeno nos postou aqui para dar as boas-vindas aos convidados, então não perca tempo!",
  ui_story_5031_50310202_23_dialog_content = "Aqui aqui. Parece que alguém está chegando agora, e ele é exatamente o seu tipo! Por que você não diz olá, Merylt?",
  ui_story_5031_50310202_24_dialog_content = "Ahh! Subli, não me empurre...",
  ui_story_5031_50310202_25_dialog_content = "Diga, ele com certeza se parece com ele, não é? Merylt, dê uma olhada mais de perto!",
  ui_story_5031_50310202_26_dialog_content = "Huh? Parece com quem? O que vocês dois estão falando?",
  ui_story_5031_50310202_27_dialog_content = "Ele se parece com o cara daquele pôster do Umbraton Daily! Aquele que Merylt escondeu para si mesma!",
  ui_story_5031_50310202_28_dialog_content = "Er... Do que exatamente você está falando?",
  ui_story_5031_50310202_29_dialog_content = "Espere, eles são muito parecidos! Por acaso você não é aquele celestita, é?",
  ui_story_5031_50310202_30_dialog_content = "S-Sim, na verdade estou... Mas como vocês três sabem sobre mim?",
  ui_story_5031_50310202_31_dialog_content = "!!",
  ui_story_5031_50310202_32_dialog_content = "Por que Merylt está fugindo, Subli?",
  ui_story_5031_50310202_33_dialog_content = "Devemos deter esse cara agora?",
  ui_story_5031_50310202_34_dialog_content = "O-O quê?!",
  ui_story_5031_50310202_35_dialog_content = "Hahaha, que graça! Calma, Frimet. Vamos deixá-los para Rainbow. Por enquanto, vá procurar Merylt, ok?",
  ui_story_5031_50310202_36_dialog_content = "Ei! Você está vadiando de novo?",
  ui_story_5031_50310202_37_dialog_content = "Desculpe por isso, pessoal! Esses três estão apenas ajudando por enquanto.",
  ui_story_5031_50310202_38_dialog_content = "Você deve estar aqui para o carnaval, imagino?",
  ui_story_5031_50310202_39_dialog_content = "Permita-me apresentar-me. Eu sou Rainbow, a apresentadora de circo, contato com o cliente, diretora de segurança e aprendiz de engenheiro naval!",
  ui_story_5031_50310202_40_dialog_content = "Th-Isso é um bocado...",
  ui_story_5031_50310202_41_dialog_content = "Heehe! É por isso que todo mundo acha que eu sou tão incrível, sabe?",
  ui_story_5031_50310202_42_dialog_content = "Prazer em conhecê-lo, Rainbow! Você pode, por favor, me dizer como entrar na nave—Ooh!",
  ui_story_5031_50310202_43_dialog_content = "O que você está fazendo? Você realmente acha que ela vai deixar você entrar só porque você pediu?",
  ui_story_5031_50310202_44_dialog_content = "M-Mas o que devemos fazer, então?",
  ui_story_5031_50310202_45_dialog_content = "Olá. Só queríamos saber mais sobre o carnaval e como melhor aproveitá-lo.",
  ui_story_5031_50310202_46_dialog_content = "Bem, o carnaval ainda está se preparando no momento. Não há problema em ficar no convés e esperar o sinal.",
  ui_story_5031_50310202_47_dialog_content = "Por enquanto, convido todos vocês a conferir o concurso de culinária que está sendo realizado nas proximidades!",
  ui_story_5031_50310202_48_dialog_content = "Uma competição feroz está prestes a acontecer, e há muitas barracas de comida maravilhosas para visitar!",
  ui_story_5031_50310202_49_dialog_content = "Caminhe por esse caminho, e você não vai perder!",
  ui_story_5031_50310202_50_dialog_content = "Obrigado pelo seu tempo. Nós vamos dar uma olhada ao redor.",
  ui_story_5031_50310202_51_dialog_content = "Aqueles membros do circo eram muito especiais, não eram?",
  ui_story_5031_50310202_52_dialog_content = "Especialmente aquelas três irmãs... Elas pareciam muito interessadas em PlayerName.",
  ui_story_5031_50310202_53_dialog_content = "Sério...? Prefiro não me envolver com pessoas estranhas...",
  ui_story_5031_50310202_54_dialog_content = "Não posso deixar de pensar que as coisas estão ficando muito loucas ao meu redor. Estou ansioso para um pouco de descanso e relaxamento.",
  ui_story_5031_50310202_55_dialog_content = "Hum. O que eu tenho que fazer para entrar neste navio?",
  ui_story_5031_50310202_56_dialog_content = "Eu realmente pensei que tinha convencido aquela gentil senhora.",
  ui_story_5031_50310202_57_dialog_content = "Então você não acha que um pouco de honestidade demais faria você ser jogado ao mar em vez disso?",
  ui_story_5031_50310202_58_dialog_content = "Não se esqueça do que Elvis disse – o interior do navio é reservado para o pessoal do circo.",
  ui_story_5031_50310202_59_dialog_content = "O melhor lugar para começarmos a procurar é acima do convés. Quem sabe... podemos encontrar algo.",
  ui_story_5031_50310202_60_dialog_content = "Espere um segundo... aquela barraca um pouco mais adiante... Eu posso ver alguns rostos familiares lá.",
  ui_story_5031_50310202_61_dialog_content = "É com prazer que apresento uma das melhores formas do mundo de dissipar este calor feroz do verão.",
  ui_story_5031_50310202_62_dialog_content = "Incluindo nosso sabor mais recente—<color=#FFB400>Edição Limitada Harbour City Breeze</color>.",
  ui_story_5031_50310202_63_dialog_content = "Recompensaremos ainda qualquer compra de dez copos de gelo raspado com uma bolsa térmica especial gravada com a imagem de um Caelestite!",
  ui_story_5031_50310202_64_dialog_content = "Muito bem. Suas dez xícaras de gelo raspado e a bolsa térmica, linda dama.",
  ui_story_5031_50310202_65_dialog_content = "Fui eu que inventei esse estilo particular de raspadinha! E eu não posso acreditar Kleken usou sua foto para o saco!",
  ui_story_5031_50310202_66_dialog_content = "Vice... Certamente você se lembra que \"<color=#FFB400>Transferência de Segredo Comercial</color>\"você assinou com Kleken ano passado?",
  ui_story_5031_50310202_67_dialog_content = "Eu temo muito que este seja o resultado.",
  ui_story_5031_50310202_68_dialog_content = "Uh-oh... é muito doce.",
  ui_story_5031_50310202_69_dialog_content = "Não tem a complexidade do gelo raspado de Vice.",
  ui_story_5031_50310202_70_dialog_content = "Eu gostaria de uma xícara também!",
  ui_story_5031_50310202_71_dialog_content = "Diga, você simplesmente não pode ajudar a si mesmo, pode?",
  ui_story_5031_50310202_72_dialog_content = "Vice ainda está muito deprimida com sua triste história de transferência de propriedade intelectual.",
  ui_story_5031_50310202_73_dialog_content = "Eu estou totalmente bem com isso... Estou apenas feliz, seja lá como aconteceu, que todos agora tenham a chance de desfrutar de um delicioso gelo raspado e eu só... eu só quero...",
  ui_story_5031_50310202_74_dialog_content = "eu vou conseguir Kleken para transferir essa propriedade intelectual de volta para mim!",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>Um pouco mais tarde</color>",
  ui_story_5031_50310202_76_dialog_content = "Uau! Verdadeiramente gelado.",
  ui_story_5031_50310202_77_dialog_content = "Não coma tudo de uma vez ou você terá um congelamento cerebral!",
  ui_story_5031_50310202_78_dialog_content = "É Vice ainda falando com Kleken? Eles estão bem?",
  ui_story_5031_50310202_79_dialog_content = "PlayerName!",
  ui_story_5031_50310202_80_dialog_content = "Eh? O que é aquela voz familiar?",
  ui_story_5031_50310202_81_dialog_content = "PlayerName, eu não posso acreditar que realmente é você!",
  ui_story_5031_50310202_82_dialog_content = "Fleur, o que você está fazendo aqui?",
  ui_story_5031_50310202_83_dialog_content = "Oh? Você não está aqui para participar do Campeonato do Pote de Feitiçaria? É uma coisa de festival de competição gourmet. Deve começar em breve.",
  ui_story_5031_50310202_84_dialog_content = "E eu também gostaria de lhe agradecer por sua ajuda com aqueles pães assados naquela época.",
  ui_story_5031_50310202_85_dialog_content = "Eu pensei um pouco. E eu decidi participar da competição. Não há melhor maneira de melhorar e divulgar meu estilo único.",
  ui_story_5031_50310202_86_dialog_content = "De nada. Devo dizer que não tinha ouvido nada sobre essa competição gourmet até agora. Como se chamava de novo? \"<color=#FFB400>Pote de Feitiço</color>\"?",
  ui_story_5031_50310202_87_dialog_content = "Aguentar! Isso é uma referência ao cara do Iron Chef do Rediesel Desert?",
  ui_story_5031_50310202_88_dialog_content = "O conhecedor do Eclipse, tio Johnny? O mesmo! E aquele Pote de Feitiço que ele usa!",
  ui_story_5031_50310202_89_dialog_content = "Espere. Quem é esse personagem \"Tio Johnny\", Carleen?",
  ui_story_5031_50310202_90_dialog_content = "Apenas um crítico gastronômico muito popular que vive no deserto Rediesel. Não sei muito mais do que isso.",
  ui_story_5031_50310202_91_dialog_content = "O que você tem tão para isso?",
  ui_story_5031_50310202_92_dialog_content = "Ele não é apenas um velho crítico de restaurante de dois bits! Ele inventou os pratos mais famosos de todo este continente naquela panela!",
  ui_story_5031_50310202_93_dialog_content = "D-Você acha que o próprio tio Johnny vai participar do campeonato?",
  ui_story_5031_50310202_94_dialog_content = "Ah, não, um chef de sua estatura certamente tem coisas melhores a fazer do que... espere, seu pote de assinatura também está disponível?",
  ui_story_5031_50310202_95_dialog_content = "Exatamente certo! O vencedor do primeiro prêmio recebe nada menos do que o pote de feitiçaria do masterchef!",
  ui_story_5031_50310202_96_dialog_content = "Não tenho ideia se o próprio homem estará lá, mas tenho certeza de que um prêmio como esse atrairá todas as estrelas de todo o mundo!",
  ui_story_5031_50310202_97_dialog_content = "E eu quero participar! Eu posso? Eles vão me deixar?",
  ui_story_5031_50310202_98_dialog_content = "Coloque esse pote mágico nas mãos de Vice, e será maravilhoso para todos nós no Colossus!",
  ui_story_5031_50310202_99_dialog_content = "Oh! Mas não enlouqueça comigo, PlayerName. Quem sabe o que vai acontecer?",
  ui_story_5031_50310202_100_dialog_content = "Eu sinto Muito, Fleur. Eu só preciso ter uma palavra com PlayerName em silêncio.",
  ui_story_5031_50310202_101_dialog_content = "Não seja tão insistente, Carleen, Fia.",
  ui_story_5031_50310202_102_dialog_content = "Ei! Fleur, espere por mim! Eu estou voltando!",
  ui_story_5031_50310202_103_dialog_content = "Tudo bem. Eu estarei esperando.",
  ui_story_5031_50310202_104_dialog_content = "Estarei esperando por você aqui, PlayerName!",
  ui_story_5031_50310202_105_dialog_content = "PlayerName, não vamos nos apressar, ok?",
  ui_story_5031_50310202_106_dialog_content = "Eu sinto Muito. Acho que exagerei um pouco ali.",
  ui_story_5031_50310202_107_dialog_content = "Você disse isso. Acho que alguém realmente quer colocar as mãos naquele pote mágico, PlayerName.",
  ui_story_5031_50310202_108_dialog_content = "O que você está fazendo aqui? Eu finalmente encontrei você!",
  ui_story_5031_50310202_109_dialog_content = "Vice? Como foi sua discussão com Kleken vai?",
  ui_story_5031_50310202_110_dialog_content = "Um fracasso miserável! Meu único consolo é que consegui colocar minhas mãos em alguns copos grátis de gelo raspado para vocês!",
  ui_story_5031_50310202_111_dialog_content = "Tenha a eles, amigos! Deixe essas sobremesas geladas limparem a sensação de fracasso! *Mastigando*",
  ui_story_5031_50310202_112_dialog_content = "eu não acho Vice se divertiu muito... *Mastigando*",
  ui_story_5031_50310202_113_dialog_content = "Argh. Congelamento do cérebro!",
  ui_story_5031_50310202_114_dialog_content = "Isso é o que acontece quando você come tudo de uma vez, sabe. Ow... eu tenho isso também.",
  ui_story_5031_50310202_115_dialog_content = "Eh? Vê aquela escada ali apontando para baixo? Não me diga que era a entrada para os conveses inferiores o tempo todo?",
  ui_story_5031_50310202_116_dialog_content = "Eh? Deixe-me dar uma olhada.",
  ui_story_5031_50310202_117_dialog_content = "Eu acho que realmente é... Bem? Devemos descer?",
  ui_story_5031_50310202_118_dialog_content = "Quer dizer que não vê problema em arrombar e entrar?",
  ui_story_5031_50310202_119_dialog_content = "Se estamos falando dos mesmos malfeitores que sequestraram o Cloudwhale, eles não vão exatamente estender o tapete de boas-vindas.",
  ui_story_5031_50310202_120_dialog_content = "No final do dia, temos que tentar.",
  ui_story_5031_50310202_121_dialog_content = "TOC Toc. Desculpe a intrusão. Por favor, deixe-me entrar!",
  ui_story_5031_50310202_122_dialog_content = "Você acabou de dizer literalmente \"toc-toc\"?",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5031_50310202_124_dialog_content = "Ahh!",
  ui_story_5031_50310202_125_dialog_content = "Quem tá falando?!",
  ui_story_5031_50310202_126_dialog_content = "Oh, me desculpe! Turistas de passagem!",
  ui_story_5031_50310202_127_dialog_content = "Outro grupo de almas perdidas, imagino? Pronto para jogar tudo ao vento por uma chance de entrar nesta porta?",
  ui_story_5031_50310202_128_dialog_content = "Alternativamente, você pode simplesmente sair daqui.",
  ui_story_5031_50310202_129_dialog_content = "Uh?",
  ui_story_5031_50310202_130_dialog_content = "O que quero dizer é que os conveses inferiores estão fora dos limites para os passageiros!",
  ui_story_5031_50310202_131_dialog_content = "Por favor, faça o seu caminho de volta.",
  ui_story_5031_50310202_132_dialog_content = "Oh, desculpe! Nós vamos sair agora.",
  ui_story_5031_50310202_133_dialog_content = "O que você sabe... Não é tão fácil entrar.",
  ui_story_5031_50310202_134_dialog_content = "Este é um enigma... sem dúvida.",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310202_136_dialog_content = "\"Atenção todos os passageiros! Os preparativos para a competição de carnaval foram concluídos recentemente.\"",
  ui_story_5031_50310202_137_dialog_content = "\"Todos os participantes interessados, por favor, dirija-se à área designada para inscrição e registro.\"",
  ui_story_5031_50310202_138_dialog_content = "\"Os participantes podem receber uma recompensa significativa de Nightium, bem como a chance de experimentar um dia na vida de um membro do circo.\"",
  ui_story_5031_50310202_139_dialog_content = "\"O vencedor do primeiro prêmio também recebe um grande prêmio pessoalmente nas mãos do apresentador.\"",
  ui_story_5031_50310202_140_dialog_content = "O que você acha? Um dia na vida de um membro do circo também pode significar um dia de acesso aos conveses inferiores.",
  ui_story_5031_50310202_141_dialog_content = "Não é uma má ideia, se assim posso dizer.",
  ui_story_5031_50310202_142_dialog_content = "Vamos, vamos dar uma olhada mais de perto.",
  ui_story_5031_50310202_143_dialog_content = "Meu, meu, eu nunca teria adivinhado. Que multidão!",
  ui_story_5031_50310202_144_dialog_content = "Tsk... Eles são como uma horda de gafanhotos me cercando.",
  ui_story_5031_50310202_145_dialog_content = "O que um juiz respeitável como eu, juiz Matthieu, está fazendo entre essa ralé?",
  ui_story_5031_50310202_146_dialog_content = "...",
  ui_story_5031_50310202_147_dialog_content = "Vá perturbar outra pessoa!",
  ui_story_5031_50310202_148_dialog_content = "Tsk. Esta comoção não é boa para o meu humor delicado. Estou até sendo curto com você, Loewe.",
  ui_story_5031_50310202_149_dialog_content = "Carleen, acho que esses dois são de Lumopolis.",
  ui_story_5031_50310202_150_dialog_content = "Eles são da Sala da Justiça, talvez... mas quem se importa.",
  ui_story_5031_50310202_151_dialog_content = "Vice! PlayerName e Carleen! E...?",
  ui_story_5031_50310202_152_dialog_content = "Policial Gronru! Isto é...",
  ui_story_5031_50310202_153_dialog_content = "Sou Fia, uma extrozoóloga. Prazer em conhecê-lo!",
  ui_story_5031_50310202_154_dialog_content = "Maravilhoso. Espero que você tenha sido uma boa influência para as criancinhas, Caelestite?",
  ui_story_5031_50310202_155_dialog_content = "O que você está olhando para mim?!",
  ui_story_5031_50310202_156_dialog_content = "Então, o que devemos o prazer, oficial Gronru?",
  ui_story_5031_50310202_157_dialog_content = "Eu apenas vim com um palpite de que o show seria divertido - ao lado de seu querido colega de escola -",
  ui_story_5031_50310202_158_dialog_content = "C-Ce... U-Hum, oi, eu sou Ciel... ex-colega de classe de Vice.",
  ui_story_5031_50310202_159_dialog_content = "Ce?",
  ui_story_5031_50310202_160_dialog_content = "Há quanto tempo! Na verdade, já faz muito tempo. Não vejo muito vocês desde que comecei a trabalhar com PlayerName.",
  ui_story_5031_50310202_161_dialog_content = "Ciel é bastante tímido. Esse é o tique nervoso dela — o \"ce\".",
  ui_story_5031_50310202_162_dialog_content = "Mas quem se importa com isso, certo? Costumávamos chamá-la de um gênio absoluto quando se trata de qualquer coisa relacionada à engenharia, certo?",
  ui_story_5031_50310202_163_dialog_content = "Justo. Uma pessoa inteligente que é estável é difícil de encontrar.",
  ui_story_5031_50310202_164_dialog_content = "Policial Gronru, Senhorita Ciel, você está aqui para se divertir?",
  ui_story_5031_50310202_165_dialog_content = "Não não! Eu não estaria vestindo essa roupa abafada se fosse curtir o carnaval.",
  ui_story_5031_50310202_166_dialog_content = "Não me diga que o meu estimado celestita não percebeu? Ou você, Vice?",
  ui_story_5031_50310202_167_dialog_content = "Você mencionou o tamanho deste navio prodigioso? Considere a complexidade de sua estrutura e fabricação!",
  ui_story_5031_50310202_168_dialog_content = "Aproveitei a primeira oportunidade que pude para arrastar Ciel para investigar essa obra de arte da engenharia.",
  ui_story_5031_50310202_169_dialog_content = "Que pena que não conseguimos encontrar um caminho para os conveses inferiores! Um simples levantamento do exterior não pode fornecer informações suficientes.",
  ui_story_5031_50310202_170_dialog_content = "Tudo isso deve inexoravelmente nos levar agora a participar da competição!",
  ui_story_5031_50310202_171_dialog_content = "Então, Vice, você vai ajudar o oficial Gronru e sua amiga?",
  ui_story_5031_50310202_172_dialog_content = "Isso é muito bom. Não quero interferir nas maquinações do \"Team Colossus\". E acredito que os organizadores são bastante flexíveis quanto ao tamanho das equipes.",
  ui_story_5031_50310202_173_dialog_content = "E acredito plenamente que as habilidades de Ciel não são inferiores às do meu estimado amigo, Vice!",
  ui_story_5031_50310202_174_dialog_content = "Eu, uh, eu vou fazer o meu melhor!",
  ui_story_5031_50310202_175_dialog_content = "Bem, então, é hora de nos prepararmos para esta deliciosa e promissora brincadeira! Nos vemos em breve.",
  ui_story_5031_50310202_176_dialog_content = "Oh meu Deus. Já estamos alinhando adversários difíceis, eu vejo...",
  ui_story_5031_50310202_177_dialog_content = "Por que eles são tão lentos para anunciar os detalhes?",
  ui_story_5031_50310202_178_dialog_content = "Ah, acho que acabei de ver duas pessoas subindo no palco.",
  ui_story_5031_50310202_179_dialog_content = "Aquele é o Laird Elvis? E há outra figura, toda em preto?",
  ui_story_5031_50310202_180_dialog_content = "Aham.",
  ui_story_5031_50310202_181_dialog_content = "Bem-vindos, todos! Meus amados concidadãos de Harbour City e viajantes por toda parte!",
  ui_story_5031_50310202_182_dialog_content = "Sou o laird de Harbour City, Elvis Modali.",
  ui_story_5031_50310202_183_dialog_content = "Laird Elvis!",
  ui_story_5031_50310202_184_dialog_content = "Elvis Modali! Elvis Modali!",
  ui_story_5031_50310202_185_dialog_content = "Obrigada. E é minha honra e privilégio convidar uma verdadeira lenda dos mares conosco neste dia de verão—",
  ui_story_5031_50310202_186_dialog_content = "O lendário Illusionist & Old Bill's Circus fará outra apresentação espetacular neste carnaval!",
  ui_story_5031_50310202_187_dialog_content = "Eu sou o mestre de cerimônias do Circo do Ilusionista e do Velho Bill, Jeno Gallacher. Obrigado a todos pela calorosa recepção.",
  ui_story_5031_50310202_188_dialog_content = "Em vista da justiça, será meu costume nos procedimentos de hoje entregar as regras antes de cada desafio.",
  ui_story_5031_50310202_189_dialog_content = "Os competidores que passarem em todos os desafios não só terão a experiência de um dia na vida de um membro do circo...",
  ui_story_5031_50310202_190_dialog_content = "Mas também receberá um presente especial e precioso preparado pessoalmente por mim.",
  ui_story_5031_50310202_191_dialog_content = "Como muitas vezes e com razão se acredita, uma trupe de circo é também um depósito de muitas bugigangas extraordinárias.",
  ui_story_5031_50310202_192_dialog_content = "E, para falar a verdade, o circo que administro não é exceção!",
  ui_story_5031_50310202_193_dialog_content = "Nossas longas viagens em busca de maravilhas foram abençoadas de maneiras muito físicas e extraordinárias.",
  ui_story_5031_50310202_194_dialog_content = "Assim como os múltiplos tesouros concedidos pelo próprio oceano - ou seja, o grande prêmio final deste carnaval!",
  ui_story_5031_50310202_195_dialog_content = "Sinta-se à vontade para imaginar este tesouro exótico. Espere ansiosamente. Você não vai se decepcionar!",
  ui_story_5031_50310202_196_dialog_content = "Uau! Parece super valioso!",
  ui_story_5031_50310202_197_dialog_content = "Nós vamos ficar ricos!",
  ui_story_5031_50310202_197X1_dialog_content = "Um tesouro exótico concedido pelo mar... Eu sei!",
  ui_story_5031_50310202_197X2_dialog_content = "Essa deve ser a Nuvem—Opa!",
  ui_story_5031_50310202_197X3_dialog_content = "Calma! Fique quieto. Você quer que mais oponentes conheçam sua verdadeira identidade e lutem conosco por isso?",
  ui_story_5031_50310202_197X4_dialog_content = "Opa, entendi. Então vamos confiar em nós mesmos para vencer a partida e salvar o Cloudwhale!",
  ui_story_5031_50310202_198_dialog_content = "Além disso, dificilmente você ficaria impressionado se tivéssemos apenas um único juiz para nossa competição.",
  ui_story_5031_50310202_199_dialog_content = "Então, é com grande prazer que convido o grande líder de Harbour City, Laird Elvis, para co-julgar comigo!",
  ui_story_5031_50310202_200_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310202_201_dialog_content = "Uh...? Jeno? Isso é algo que deveríamos ter discutido primeiro?",
  ui_story_5031_50310202_202_dialog_content = "Há algum problema, senhor? Eu teria pensado que você ficaria grato por uma chance de aproveitar o que qualquer homem em sua posição deveria ser capaz de fazer!",
  ui_story_5031_50310202_203_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310202_204_dialog_content = "Eu vejo.",
  ui_story_5031_50310202_205_dialog_content = "Nós confiamos que vocês irão aproveitar os eventos para o conteúdo de seus corações, pessoal!",
  ui_story_5031_50310301_0_dialog_content = "Hum, então essa renda deve entrar aqui...",
  ui_story_5031_50310301_0X1_dialog_content = "Huh? Como é que há outra renda?",
  ui_story_5031_50310301_0X2_dialog_content = "Este... Uh, deve passar pelo outro lado?",
  ui_story_5031_50310301_0X3_dialog_content = "Obrigado por ajudar, Vice.",
  ui_story_5031_50310301_0X4_dialog_content = "Sem problemas. Apenas espere e deixe-me descobrir isso em um minuto.",
  ui_story_5031_50310301_0X5_dialog_content = "Sem pressa. Não estou com pressa.",
  ui_story_5031_50310301_0X6_dialog_content = "Hum, deveria ser assim, certo?",
  ui_story_5031_50310301_0X7_dialog_content = "Hum, talvez não...",
  ui_story_5031_50310301_0X8_dialog_content = "... Vice.",
  ui_story_5031_50310301_0X9_dialog_content = "Hum? O que é isso? Eu te machuquei?",
  ui_story_5031_50310301_0X10_dialog_content = "Não. É só que... Posso te perguntar uma coisa pessoal?",
  ui_story_5031_50310301_0X11_dialog_content = "Pessoal?",
  ui_story_5031_50310301_0X12_dialog_content = "Sim... gostaria de saber como se sentiu... quando obteve o novo poder.",
  ui_story_5031_50310301_0X13_dialog_content = "Ah, entendo... Isso não é nada pessoal!",
  ui_story_5031_50310301_0X14_dialog_content = "Levante um pouco o cotovelo direito.",
  ui_story_5031_50310301_0X15_dialog_content = "Ah com certeza.",
  ui_story_5031_50310301_0X16_dialog_content = "Hum... Mas essa é realmente uma pergunta difícil.",
  ui_story_5031_50310301_0X17_dialog_content = "Não é que eu não queira responder... É apenas difícil de descrever.",
  ui_story_5031_50310301_0X18_dialog_content = "Sim, eu sei.",
  ui_story_5031_50310301_0X19_dialog_content = "Para mim, parecia que meu potencial estava sendo desbloqueado.",
  ui_story_5031_50310301_0X20_dialog_content = "Ganhei uma perspectiva diferente sobre Lumina, mas também com certos riscos.",
  ui_story_5031_50310301_0X21_dialog_content = "Riscos?",
  ui_story_5031_50310301_0X22_dialog_content = "Sim, eu estava tão sonolenta durante o processo. Achei que nunca fosse acordar.",
  ui_story_5031_50310301_0X23_dialog_content = "Continuei pensando no antigo eu, com medo de me perder se relaxasse mesmo por um segundo.",
  ui_story_5031_50310301_0X24_dialog_content = "Também vi muitas coisas maravilhosas, como se estivesse lá.",
  ui_story_5031_50310301_0X25_dialog_content = "Essas ilusões pareciam tão reais, como um teste para mim.",
  ui_story_5031_50310301_0X26_dialog_content = "Felizmente, agarrei-me a um vislumbre de consciência e preservei até o fim.",
  ui_story_5031_50310301_0X27_dialog_content = "Eu vejo. Então, é um processo de desbloquear seu potencial...?",
  ui_story_5031_50310301_0X28_dialog_content = "Sim, é o que eu acho.",
  ui_story_5031_50310301_0X29_dialog_content = "Na verdade, muitos aurorianos obtêm esses avanços em uma crise.",
  ui_story_5031_50310301_0X30_dialog_content = "Acho que foi isso que aconteceu comigo.",
  ui_story_5031_50310301_0X31_dialog_content = "Mas mesmo agora, eu ainda não consigo dominá-lo completamente.",
  ui_story_5031_50310301_0X32_dialog_content = "Isso é provavelmente porque ainda é novo para você. Você vai, dado o tempo.",
  ui_story_5031_50310301_0X33_dialog_content = "Isso é verdade!",
  ui_story_5031_50310301_0X34_dialog_content = "Se você quiser tentar, talvez possa começar com a liberação da consciência?",
  ui_story_5031_50310301_0X35_dialog_content = "Liberação de consciência?",
  ui_story_5031_50310301_0X36_dialog_content = "Sim. Isso é o que eu faria toda vez que quisesse ativar meu poder, embora não seja bem-sucedido o tempo todo.",
  ui_story_5031_50310301_0X37_dialog_content = "Entendi. Saquei.",
  ui_story_5031_50310301_0X38_dialog_content = "Vou tentar mais tarde. Obrigada, Vice.",
  ui_story_5031_50310301_0X39_dialog_content = "Sem problemas!",
  ui_story_5031_50310301_0X40_dialog_content = "Lá vamos nós, a última renda!",
  ui_story_5031_50310301_0X41_dialog_content = "Ufa, vestir a roupa nobre com certeza é uma dor!",
  ui_story_5031_50310301_0X42_dialog_content = "E seu material parece bastante único. Nunca vi isso na Illumina.",
  ui_story_5031_50310301_0X43_dialog_content = "Esta é a minha primeira vez também. Provavelmente é uma especialidade de Harbour City.",
  ui_story_5031_50310301_0X44_dialog_content = "Afinal, roupas formais são o forte deles.",
  ui_story_5031_50310301_0X45_dialog_content = "Obrigado novamente pela ajuda, Vice.",
  ui_story_5031_50310301_0X46_dialog_content = "Não se preocupe. Mas você fica muito bonita nisso, Carleen!",
  ui_story_5031_50310301_0X47_dialog_content = "Vamos mostrar para PlayerName e Fia. Eles vão se surpreender!",
  ui_story_5031_50310301_1_dialog_content = "Por que não é Carleen volta ainda?",
  ui_story_5031_50310301_2_dialog_content = "As meninas levam tempo para se trocar, sem mencionar que a roupa parece muito intrincada.",
  ui_story_5031_50310301_2X1_dialog_content = "Mesmo com a ajuda de Vice, ainda deve demorar um pouco.",
  ui_story_5031_50310301_3_dialog_content = "Você tem razão. Por que tenho a sensação de que os nobres precisam de um servo apenas para se vestir?",
  ui_story_5031_50310301_4_dialog_content = "Que tal você dar Carleen uma mão também, Fia?",
  ui_story_5031_50310301_5_dialog_content = "Ei? O que sou eu, seu servo agora? Me mandando assim!",
  ui_story_5031_50310301_6_dialog_content = "Por favor. não são Carleen e Vice fazendo o seu melhor para ajudá-lo a localizar o Cloudwhale?",
  ui_story_5031_50310301_7_dialog_content = "Tudo bem, tudo bem! Eu nunca ajudei alguém a colocar um vestido antes. Eu posso tentar.",
  ui_story_5031_50310301_8_dialog_content = "PlayerName, pegue leve com Fia.",
  ui_story_5031_50310301_9_dialog_content = "Desculpe por deixar todo mundo esperando...",
  ui_story_5031_50310301_10_dialog_content = "Nós iremos! Carleen, você está... absolutamente deslumbrante!",
  ui_story_5031_50310301_11_dialog_content = "Sim! Parece confortável, prático e realmente se encaixa bem em você, Carleen!",
  ui_story_5031_50310301_12_dialog_content = "Obrigado a todos. É incrível o número de alfaiates profissionais e designers de moda incríveis em Harbour City.",
  ui_story_5031_50310301_13_dialog_content = "Eu realmente me sinto extremamente confortável nisso.",
  ui_story_5031_50310301_14_dialog_content = "O que você acha, PlayerName?",
  ui_story_5031_50310301_15_dialog_content = "Eu sinto Muito. Fiquei fascinado por um segundo. Mas o que eu ia dizer era que...",
  ui_story_5031_50310301_16_dialog_content = "Lindo! Gracioso! Poderoso!",
  ui_story_5031_50310301_17_dialog_content = "Você é filho do Schwartz família em todos os sentidos, Carleen, e esta roupa deslumbrante só mostra isso.",
  ui_story_5031_50310301_18_dialog_content = "Eu não sei o que dizer. Acho que devo agradecer-lhe, Laird Elvis.",
  ui_story_5031_50310301_19_dialog_content = "Por favor, é o mínimo que posso fazer. Procurava algo que me lembrasse as características nobres e exemplares do Schwartz família.",
  ui_story_5031_50310301_20_dialog_content = "Você pode considerar a roupa como uma espécie de bom presságio para sua entrada bem-sucedida na competição!",
  ui_story_5031_50310301_21_dialog_content = "Eu sou necessário em outro lugar, mas estou ansioso para vê-lo novamente mais tarde!",
  ui_story_5031_50310301_22_dialog_content = "Oh, me desculpe, acho que não tive a chance de compartilhar meus pensamentos sobre o vestido novo de Carleen.",
  ui_story_5031_50310301_23_dialog_content = "Urgh. Laird Elvis roubou meu trovão.",
  ui_story_5031_50310301_24_dialog_content = "Ei, acho que você não precisa dizer nada...",
  ui_story_5031_50310301_25_dialog_content = "Você já disse o suficiente com os olhos.",
  ui_story_5031_50310301_26_dialog_content = "Hã?",
  ui_story_5031_50310301_27_dialog_content = "Cumprimentos a todos! É hora de eu dar a todos vocês um breve resumo do evento.",
  ui_story_5031_50310301_28_dialog_content = "Permita-me apresentar-me. Eu sou Rainbow, a apresentadora de circo, contato com o cliente, diretora de segurança e aprendiz de engenheiro naval!",
  ui_story_5031_50310301_29_dialog_content = "Mas hoje estarei usando o chapéu do mestre de cerimônias da competição!",
  ui_story_5031_50310301_30_dialog_content = "Nesta primeira etapa, peço a todos que levem daqui uma de minhas pistolas de água especialmente preparadas.",
  ui_story_5031_50310301_31_dialog_content = "Essas pistolas de água foram modificadas para canalizar Lumina para disparar um projétil especial.",
  ui_story_5031_50310301_32_dialog_content = "As regras são muito simples: acerte os alvos dados pelo Ringmaster Jeno com sua pistola d'água.",
  ui_story_5031_50310301_33_dialog_content = "Devo informá-lo que não vamos impedir que competidores ou equipes usem as pistolas de água uns nos outros!",
  ui_story_5031_50310301_34_dialog_content = "Apenas as cinco equipes com melhor pontuação passarão para a próxima rodada. Os eliminados são lançados ao mar como punição.",
  ui_story_5031_50310301_35_dialog_content = "Então não queremos nenhum competidor que não saiba nadar! Ou pelo menos certifique-se de ter um dispositivo de flutuação com você!",
  ui_story_5031_50310301_36_dialog_content = "As equipes podem ser de qualquer tamanho, mas observe que sua pontuação final será obtida dividindo a pontuação de sua equipe pelo número de membros.",
  ui_story_5031_50310301_37_dialog_content = "Essas regras são muito boas para nós, certo?",
  ui_story_5031_50310301_38_dialog_content = "Nós vamos ganhar o prêmio com certeza com Jona e Azure em nossa equipe!",
  ui_story_5031_50310301_39_dialog_content = "Armas de água? Parece bobo, mas não posso ignorar esse grande prêmio...",
  ui_story_5031_50310301_40_dialog_content = "O que mais vamos fazer com o nosso tempo de qualquer maneira? É apenas um pouco de diversão inofensiva.",
  ui_story_5031_50310301_41_dialog_content = "Ei! Nós temos feito isso!",
  ui_story_5031_50310301_42_dialog_content = "Não conte suas galinhas muito cedo! De qualquer forma, vocês dois acabaram de se juntar à Rediesel Wrench.",
  ui_story_5031_50310301_43_dialog_content = "Lembre-se de como os caras da Rediesel Wrench lidam com as coisas na frente de estranhos! Nós nos orgulhamos.",
  ui_story_5031_50310301_44_dialog_content = "Não se preocupe com nada! Você entendeu!",
  ui_story_5031_50310301_45_dialog_content = "Apenas algumas coisas para lembrar! Entendi!",
  ui_story_5031_50310301_46_dialog_content = "Todos estão claros sobre as regras?",
  ui_story_5031_50310301_47_dialog_content = "Alto e claro!",
  ui_story_5031_50310301_48_dialog_content = "Espere! Se essas armas de água funcionarem em Lumina, como isso vai funcionar para mim?",
  ui_story_5031_50310301_49_dialog_content = "Oh sim. Não considerei isso para os celestitas.",
  ui_story_5031_50310301_50_dialog_content = "Merylt, você acha que poderia ir até a equipe do Caelestite e ajudá-los?",
  ui_story_5031_50310301_51_dialog_content = "O-o que eu devo fazer com isso? Não podemos participar...",
  ui_story_5031_50310301_52_dialog_content = "Boba. Por que mesmo incluí-lo? Ele não é muito de um broto de feijão.",
  ui_story_5031_50310301_53_dialog_content = "Chefe, e o celestita?",
  ui_story_5031_50310301_54_dialog_content = "Podemos levar em conta as deficiências. Conte o celestita e aquela garotinha como um só.",
  ui_story_5031_50310301_55_dialog_content = "Ei! Em que universo é um celestita mais eu meia pessoa cada?",
  ui_story_5031_50310301_56_dialog_content = "Faça do seu jeito. Dois participantes então.",
  ui_story_5031_50310301_57_dialog_content = "Uh, na verdade, eu sou um pouco jovem e não muito em forma... Pensando bem, talvez faça sentido nos combinar!",
  ui_story_5031_50310301_58_dialog_content = "Então, não havendo objeção, entregarei seus alvos em breve—",
  ui_story_5031_50310301_59_dialog_content = "Vamos! Uma salva de palmas para nossos competidores malucos!",
  ui_story_5031_50310301_60_dialog_content = "Agora, uiva! Como você quer dizer isso! Bestas de Hades!",
  ui_story_5031_50310301_61_dialog_content = "Espere! Espero que o Boss não esteja realmente pensando em convocar aqueles...",
  ui_story_5031_50310301_62_dialog_content = "Rápido! Cubra os olhos de Rainbow! Ela vai enlouquecer se ver um Eclipse!",
  ui_story_5031_50310301_63_dialog_content = "Graah!",
  ui_story_5031_50310301_64_dialog_content = "Eclipses?!",
  ui_story_5031_50310301_65_dialog_content = "Eclipses!!",
  ui_story_5031_50310301_66_dialog_content = "Frimet! Faça algo para me ajudar com Rainbow. Ela vai perder!",
  ui_story_5031_50310301_67_dialog_content = "Chefe estúpido! Por que escolher Eclipsites?!",
  ui_story_5031_50310301_68_dialog_content = "Eh... porque funciona tão bem com esse vento.",
  ui_story_5031_50310301_69_dialog_content = "PlayerName, Fia - fique atrás de mim e Vice.",
  ui_story_5031_50310301_70_dialog_content = "Não se preocupem, queridos amigos! Esses Eclipsitos são pouco mais do que ilusões que eu conjurei com o \"<color=#FFB400>Origem</color>.\"",
  ui_story_5031_50310301_71_dialog_content = "Com o poder de minhas próprias mãos, analisei a \"origem\" do poder dos Eclipsitas no decorrer de minhas batalhas!",
  ui_story_5031_50310301_72_dialog_content = "E, com o uso do \"<color=#FFB400>Cartão de Origem</color>,\" criou as ilusões realistas e ágeis que você vê diante de você.",
  ui_story_5031_50310301_73_dialog_content = "Ah...",
  ui_story_5031_50310301_74_dialog_content = "Ah...",
  ui_story_5031_50310301_75_dialog_content = "Como você pode ver, os Eclipsites estão completamente sob meu controle e são excelentes alvos.",
  ui_story_5031_50310301_76_dialog_content = "Então, que comecem os jogos!",
  ui_story_5031_50310401_1_dialog_content = "Ei! Ficar ocupado! Eu quero que você limpe esses Eclipsites, porque não há como a Rediesel Wrench se contentar com o segundo!",
  ui_story_5031_50310401_2_dialog_content = "Entendi, chefe! Mas e os aurorianos?",
  ui_story_5031_50310401_3_dialog_content = "E eles? Você é uma chave Rediesel! Agora bata-o para fora do parque!",
  ui_story_5031_50310401_4_dialog_content = "Faça a Rediesel Wrench parecer boa e atire em qualquer um em seu caminho para o lado do navio!",
  ui_story_5031_50310401_5_dialog_content = "Entendido.",
  ui_story_5031_50310401_6_dialog_content = "Intenso, Jona.",
  ui_story_5031_50310401_7_dialog_content = "Qual é o problema? Nenhum cara, por mais fofo que seja, está acima da punição!",
  ui_story_5031_50310401_8_dialog_content = "Fofo é fofo, mas mais fofo ainda é aquele grande prêmio...",
  ui_story_5031_50310401_9_dialog_content = "Urgh... Jona e Azure estão aqui - eles são profissionais de armas.",
  ui_story_5031_50310401_10_dialog_content = "Eles disseram que você só ganha pontos por atirar em Eclipsites, mas esses caras da Rediesel Wrench estão apenas atirando em outros jogadores!",
  ui_story_5031_50310401_11_dialog_content = "Se as ilusões de Jeno não fossem uma cobertura tão excelente, teríamos sido baleados ao mar há muito tempo.",
  ui_story_5031_50310401_12_dialog_content = "Ainda podemos ser, a menos que possamos fazer algo em vez de apenas esperar aqui. Siga o meu comando! Nós vamos lutar o nosso caminho!",
  ui_story_5031_50310401_13_dialog_content = "Aguentar, Carleen!",
  ui_story_5031_50310401_14_dialog_content = "Isso é o que você ganha por não seguir o espírito das regras, seus trapaceiros sujos - flor de gelo, não, tiro de gelo!",
  ui_story_5031_50310401_15_dialog_content = "Caramba!",
  ui_story_5031_50310401_16_dialog_content = "B-Chefe!",
  ui_story_5031_50310401_17_dialog_content = "Isso é dois deles para baixo. Rápido, venham aqui, todos.",
  ui_story_5031_50310401_18_dialog_content = "Excelente trabalho... Direto para o oceano com a assinatura de gelo de Carleen. Ei, Carleen, atrás da capa, rápido!",
  ui_story_5031_50310401_19_dialog_content = "Agora é sua chance, PlayerName!",
  ui_story_5031_50310401_20_dialog_content = "Isso é o que você ganha por ser um patrulheiro solitário, Carleen! Isso significa-",
  ui_story_5031_50310401_21_dialog_content = "Eu tenho você agora, minha bela princesa de Lumopolis!",
  ui_story_5031_50310401_22_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310401_23_dialog_content = "!!",
  ui_story_5031_50310401_24_dialog_content = "Carleen!",
  ui_story_5031_50310401_25_dialog_content = "Eu... sinto muito, PlayerName.",
  ui_story_5031_50310401_26_dialog_content = "Tudo fica bem quando termina bem. eu não esperava Jona ser tão bom com uma pistola de água Lumina.",
  ui_story_5031_50310401_27_dialog_content = "Ei! Seus bandidos desprezíveis de Rediesel! Pare de pegar em nós!",
  ui_story_5031_50310401_28_dialog_content = "Isso não vai funcionar. Temos que resolver esse impasse.",
  ui_story_5031_50310401_29_dialog_content = "Uma competição muito emocionante, pessoal.",
  ui_story_5031_50310401_30_dialog_content = "Sim. De fato. Cheio de feitos de poder que eu não esperava.",
  ui_story_5031_50310401_31_dialog_content = "Um poder que obtive da Verdadeira Ordem...",
  ui_story_5031_50310401_32_dialog_content = "Do qual tenho certeza que você já ouviu mais lendas negativas como um nobre de Lumopolis, senhor.",
  ui_story_5031_50310401_33_dialog_content = "Na verdade, o que a \"origem\" representa mais do que tudo é apenas outra forma de criar suspense para efeito performativo.",
  ui_story_5031_50310401_34_dialog_content = "Na verdade, o que possuo é apenas o poder de transformar energia... um hábito eficaz com a prática, como você pode ver.",
  ui_story_5031_50310401_35_dialog_content = "Não sou de ficar particularmente ofendido com poderes estranhos. Não se preocupe.",
  ui_story_5031_50310401_36_dialog_content = "Mas por que Eclipses?",
  ui_story_5031_50310401_37_dialog_content = "Estamos todos aqui para participar do carnaval, não estamos? O que é um carnaval senão uma série de encontros emocionantes e de tirar o fôlego?",
  ui_story_5031_50310401_38_dialog_content = "Acho que Eclipses se encaixam muito bem.",
  ui_story_5031_50310401_39_dialog_content = "Não posso culpar sua lógica de negócios. Alimento para o pensamento.",
  ui_story_5031_50310401_40_dialog_content = "Naturalmente, devo sempre pensar no caso de negócios como o mestre de cerimônias de toda a trupe de circo.",
  ui_story_5031_50310401_41_dialog_content = "Minhas desculpas pela intrusão, Laird Elvis.",
  ui_story_5031_50310401_42_dialog_content = "Pato...? Mais tarde, Jeno.",
  ui_story_5031_50310401_43_dialog_content = "Que novidades você tem?",
  ui_story_5031_50310401_44_dialog_content = "Um relatório, verificado. Localizamos um quarto que corresponde à sua descrição anterior.",
  ui_story_5031_50310401_45_dialog_content = "O que? Maravilhoso...",
  ui_story_5031_50310401_46_dialog_content = "Infelizmente, o quarto está protegido por um cadeado muito seguro que nunca vimos. A entrada forçada certamente daria o alarme.",
  ui_story_5031_50310401_47_dialog_content = "Eu entendo. Então teremos que encontrar uma chave capaz de abri-la.",
  ui_story_5031_50310401_48_dialog_content = "Suponho que tal chave possa ser encontrada nos aposentos de Jeno ou em sua pessoa. Podemos tentar as duas vias simultaneamente.",
  ui_story_5031_50310401_49_dialog_content = "Elvis!",
  ui_story_5031_50310401_50_dialog_content = "Espero não estar incomodando você, mas outro time acabou de marcar um grande ponto, e as pessoas estão clamando para que você honre o ponto.",
  ui_story_5031_50310401_51_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310401_52_dialog_content = "Desculpas, Jeno. Depois de mais algumas palavras com Patou.",
  ui_story_5031_50310401_53_dialog_content = "Então, o que devemos fazer, senhor?",
  ui_story_5031_50310401_54_dialog_content = "Você e seus homens têm autoridade para fazer o que for necessário para revistar a sala.",
  ui_story_5031_50310401_55_dialog_content = "Mas temo que qualquer ausência significativa dos eventos do dia desperte as suspeitas de Jeno.",
  ui_story_5031_50310401_56_dialog_content = "É intrigante quantos participantes aurorianos temos com motivos desconhecidos... e suspeito que as mesmas ideias.",
  ui_story_5031_50310401_57_dialog_content = "Portanto, atribua uma vigilância apertada sobre eles. Qualquer um que queira fazer um movimento precisará fazê-lo quando estiver quieto — quando o convés estiver menos ocupado.",
  ui_story_5031_50310401_58_dialog_content = "Presumo, senhor, devemos continuar procurando em silêncio e aguardar novas ordens de sua senhoria.",
  ui_story_5031_50310401_59_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310401_60_dialog_content = "Finalmente estou de volta, pessoal! E venho por este meio anunciar que a equipa Rediesel Wrench conquistou mais um ponto!",
  ui_story_5031_50310401_61_dialog_content = "De volta mesmo. Estávamos começando a nos perguntar.",
  ui_story_5031_50310401_62_dialog_content = "Desculpas, Jeno, pela longa espera.",
  ui_story_5031_50310402_1_dialog_content = "E essa chave? Como vou saber onde você colocou?",
  ui_story_5031_50310402_2_dialog_content = "Pareces um pouco estranho, Elvis?",
  ui_story_5031_50310402_3_dialog_content = "Quero dizer, parecia que algo que seu guarda-costas disse o desagradou.",
  ui_story_5031_50310402_4_dialog_content = "Eu confio que está tudo bem? Nenhuma doença de qualquer tipo?",
  ui_story_5031_50310402_5_dialog_content = "Não não. Estou muito bem, obrigado.",
  ui_story_5031_50310402_6_dialog_content = "Eu só estava me ocupando com alguns assuntos de estado. Desculpe por lhe dar essa impressão.",
  ui_story_5031_50310402_7_dialog_content = "Espero que arrastá-lo até aqui não o tenha afastado de um trabalho importante?",
  ui_story_5031_50310402_8_dialog_content = "Eu estava pensando que talvez você realmente aprecie esta oportunidade de aproveitar o maravilhoso festival com seu povo.",
  ui_story_5031_50310402_9_dialog_content = "Oh? É a primeira vez que vejo Boss se desculpar?",
  ui_story_5031_50310402_10_dialog_content = "Eu penso que sim. Acho que ele pode falar como uma pessoa normal se quiser.",
  ui_story_5031_50310402_11_dialog_content = "Se você tem tanto tempo livre, vá ajudar a Rainbow, ok?",
  ui_story_5031_50310402_12_dialog_content = "Pffff.",
  ui_story_5031_50310402_13_dialog_content = "Sheesh. É como pastorear gatos, de manhã até a noite.",
  ui_story_5031_50310402_14_dialog_content = "Ah, não se preocupe comigo. Eu só estava...",
  ui_story_5031_50310402_15_dialog_content = "Tenho me preocupado com alguns assuntos importantes que precisam de uma decisão.",
  ui_story_5031_50310402_16_dialog_content = "Esta oportunidade de relaxar significou uma chance de novos insights sobre algumas coisas e pessoas. É muito útil.",
  ui_story_5031_50310402_17_dialog_content = "Maravilhoso! Você deve me dizer se achar o dia incômodo por qualquer motivo.",
  ui_story_5031_50310402_18_dialog_content = "Certo. Sem problemas.",
  ui_story_5031_50310402_19_dialog_content = "\"Atenção, participantes! Agora estamos entrando em uma fase mais emocionante do nosso jogo envolvendo duas vezes mais projeções de Eclipsite!\"",
  ui_story_5031_50310402_20_dialog_content = "Finalmente! Tempo de bônus!",
  ui_story_5031_50310402_21_dialog_content = "Cubra-me, Ciel! Tempo de bônus é onde os campeões fazem ou quebram!",
  ui_story_5031_50310402_22_dialog_content = "G-Entendido, oficial Gronru.",
  ui_story_5031_50310402_23_dialog_content = "Ah, você está correndo muito rápido para mim—",
  ui_story_5031_50310402_24_dialog_content = "Ei! Quem é aquele?",
  ui_story_5031_50310402_25_dialog_content = "O que temos aqui? Uma pobre garota Illumina sozinha.",
  ui_story_5031_50310402_26_dialog_content = "E-Ei! Fique longe de mim!",
  ui_story_5031_50310402_27_dialog_content = "Precisamos desse prêmio. As coisas boas não são baratas.",
  ui_story_5031_50310402_28_dialog_content = "Desculpe, senhorita, mas vou confiscar sua pistola de água. Agora faça-nos um favor e salte para o oceano, sim?",
  ui_story_5031_50310402_29_dialog_content = "Espere - belo equipamento! Podemos conseguir um bom preço por ele em Umbraton, não acha?",
  ui_story_5031_50310402_30_dialog_content = "Sim! E sempre conseguimos o que queremos, senhorita. Não torne isso difícil.",
  ui_story_5031_50310402_31_dialog_content = "Dê-nos o seu valor!",
  ui_story_5031_50310402_32_dialog_content = "H-Mãos fora!",
  ui_story_5031_50310402_33_dialog_content = "Congelem, vocês dois!",
  ui_story_5031_50310402_34_dialog_content = "Não me diga que é o MC!",
  ui_story_5031_50310402_35_dialog_content = "O mesmo! O roubo é estritamente contra as regras do torneio. Receio não poder deixá-lo ir!",
  ui_story_5031_50310402_36_dialog_content = "Quem você pensa que é? Você acha que temos medo de você porque você é o MC?",
  ui_story_5031_50310402_37_dialog_content = "Não vou tolerar esse tipo de comportamento grosseiro, está me ouvindo?",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310402_39_dialog_content = "D-Cara!",
  ui_story_5031_50310402_40_dialog_content = "Você também!",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310402_42_dialog_content = "Ai!",
  ui_story_5031_50310402_43_dialog_content = "V-Muito impressionante... Ao mar assim.",
  ui_story_5031_50310402_44_dialog_content = "Você não está ferido, está? Isso foi loucura – pensar que eles poderiam usar este evento como uma extorsão!",
  ui_story_5031_50310402_45_dialog_content = "Uh, eu tenho que ajudar o oficial Gronru. Obrigada!",
  ui_story_5031_50310402_46_dialog_content = "Minha pistola de água... Onde está?",
  ui_story_5031_50310402_47_dialog_content = "Oh. Me desculpe por isso. Aqui, pegue isso.",
  ui_story_5031_50310402_48_dialog_content = "Eu adicionei algo às regras sobre \"pessoas que perdem suas armas de água podem pegar uma nova com o MC\". Então não se preocupe com isso.",
  ui_story_5031_50310402_49_dialog_content = "Oh, OK! Obrigada.",
  ui_story_5031_50310402_50_dialog_content = "Ei...",
  ui_story_5031_50310402_51_dialog_content = "Hã?",
  ui_story_5031_50310402_52_dialog_content = "Eu sou Ciel. Obrigado, senhorita Rainbow.",
  ui_story_5031_50310402_53_dialog_content = "Ciel? Vou me lembrar do seu nome.",
  ui_story_5031_50310402_54_dialog_content = "Minha nossa. Como é uma dama elegante Carleen fazendo em um evento como este?",
  ui_story_5031_50310402_55_dialog_content = "Ela deveria saber melhor com sua educação nobre. Ela está fazendo com que todos nós... fiquemos mal!",
  ui_story_5031_50310402_56_dialog_content = "...",
  ui_story_5031_50310402_57_dialog_content = "Ei! Estou falando sozinho aqui?",
  ui_story_5031_50310402_58_dialog_content = "Temos que ficar de olho e proteger Carleen.",
  ui_story_5031_50310402_59_dialog_content = "Tut, eu também posso ser.",
  ui_story_5031_50310402_60_dialog_content = "Ei, venha aqui! Há montes de Eclipsites aqui que você pode derrubar!",
  ui_story_5031_50310402_61_dialog_content = "Ah!",
  ui_story_5031_50310402_62_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5031_50310402_63_dialog_content = "Eu sinto muito, senhor... Eu acidentalmente peguei sua pistola de água.",
  ui_story_5031_50310402_64_dialog_content = "Deixe-me ajudá-lo a pegá-lo.",
  ui_story_5031_50310402_65_dialog_content = "Está bem. Não se preocupe com isso. Seu amigo está esperando ali. Divirta-se.",
  ui_story_5031_50310402_66_dialog_content = "Obrigada. Que nobre gentil você é!",
  ui_story_5031_50310402_67_dialog_content = "...",
  ui_story_5031_50310402_68_dialog_content = "... Repugnante.",
  ui_story_5031_50310402_69_dialog_content = "Água! Traga-me um pouco de água! Preciso lavar as mãos!",
  ui_story_5031_50310402_70_dialog_content = "... Dramático.",
  ui_story_5031_50310402_71_dialog_content = "Graah!",
  ui_story_5031_50310402_72_dialog_content = "PlayerName, Jeno com certeza adicionou muitos Eclipsites.",
  ui_story_5031_50310402_73_dialog_content = "E esses caras da Rediesel não estão nos dando folga.",
  ui_story_5031_50310402_74_dialog_content = "Eles preferem arriscar a eliminação por falta de pontos para focar em nós!",
  ui_story_5031_50310402_75_dialog_content = "Acho que isso apenas diz que eles nos veem como a concorrência.",
  ui_story_5031_50310402_76_dialog_content = "E é por isso que eles querem nos eliminar desde o início.",
  ui_story_5031_50310402_77_dialog_content = "Eu tenho um pouco de gambito... mas pode funcionar: eu posso ser a isca como alguém que não tem acesso a Lumina.",
  ui_story_5031_50310402_78_dialog_content = "Eu farei o meu melhor para atrair um monte de Eclipsites enquanto você usa o desvio para sair de baixo Jona e o polegar de Azure.",
  ui_story_5031_50310402_79_dialog_content = "Isso é muito arriscado, PlayerName! Podemos apenas tentar romper novamente. Eu teria mais cuidado com isso!",
  ui_story_5031_50310402_80_dialog_content = "Jona e Azure são bons demais. Eles poderão localizá-lo de longe, Carleen.",
  ui_story_5031_50310402_81_dialog_content = "Eu não desço tão fácil. Confie no meu poder.",
  ui_story_5031_50310402_82_dialog_content = "Eu confio, e agora é a hora de colocar sua fé em meu poder também.",
  ui_story_5031_50310402_83_dialog_content = "Carleen, acho que vale a pena tentar a sugestão de PlayerName.",
  ui_story_5031_50310402_84_dialog_content = "Acho que pode ser a melhor opção tática que temos.",
  ui_story_5031_50310402_85_dialog_content = "Tudo bem então. Mas cuidado, tá?",
  ui_story_5031_50310402_86_dialog_content = "Tenha certeza. Fia, você vai com Carleen e Vice.",
  ui_story_5031_50310402_87_dialog_content = "H-Huh? OK.",
  ui_story_5031_50310402_88_dialog_content = "Eclipses! Refeição chegando!",
  ui_story_5031_50310402_89_dialog_content = "500 Lumamber é tudo o que você precisa para obter este maior banquete que você já viu! Agora ou nunca! Ahhhh!",
  ui_story_5031_50310402_90_dialog_content = "Graah!",
  ui_story_5031_50310402_91_dialog_content = "Grrrou!",
  ui_story_5031_50310402_92_dialog_content = "Huh? Esse é o PlayerName? O que diabos ele está fazendo?",
  ui_story_5031_50310402_93_dialog_content = "Celestita Inteligente. Ele está atraindo os Eclipsitas para bloquear nossa linha de visão, eu acho.",
  ui_story_5031_50310402_94_dialog_content = "Então ele é um tolo que vai receber uma punição de tolo bem na sua bunda por me subestimar...",
  ui_story_5031_50310402_95_dialog_content = "Oi senhoras.",
  ui_story_5031_50310402_96_dialog_content = "O quê?",
  ui_story_5031_50310402_97_dialog_content = "Receio que considero o alegre bando de Carleen um pouco sob minha proteção...",
  ui_story_5031_50310402_98_dialog_content = "Eu tenho raiva suficiente das minhas mãos manchadas para dar a volta por aí... Vocês se atrevem a atacar o nobre? Pegue seus caroços!!",
  ui_story_5031_50310402_99_dialog_content = "Fique atrás de mim, Vice, Fia!",
  ui_story_5031_50310402_100_dialog_content = "Eu vou acabar com todos vocês Eclipsitas sozinho!",
  ui_story_5031_50310402_101_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5031_50310402_102_dialog_content = "Ah...",
  ui_story_5031_50310402_103_dialog_content = "Graah!!",
  ui_story_5031_50310402_104_dialog_content = "Graah!",
  ui_story_5031_50310402_105_dialog_content = "Graah!",
  ui_story_5031_50310402_106_dialog_content = "Eles são fracos, mas há muitos. Eles nos cercaram.",
  ui_story_5031_50310402_107_dialog_content = "Este não é o momento de ceder, Carleen. Temos que voltar com PlayerName.",
  ui_story_5031_50310402_108_dialog_content = "Se ao menos as regras permitissem o Moon Cocoon... Humph. Tomem isso, seus Eclipses!",
  ui_story_5031_50310402_108X1_dialog_content = "Se eu tivesse um novo poder como Vice pegou...!",
  ui_story_5031_50310402_108X2_dialog_content = "Calma, Carleen.",
  ui_story_5031_50310402_108X3_dialog_content = "Apenas deixe de lado sua consciência como Vice disse...",
  ui_story_5031_50310402_108X4_dialog_content = "Solte... Respire.",
  ui_story_5031_50310402_108X5_dialog_content = "Carleen.",
  ui_story_5031_50310402_108X6_dialog_content = "Pai…",
  ui_story_5031_50310402_108X7_dialog_content = "Você e eu sabemos que os Eclipsitas não podem ser exterminados.",
  ui_story_5031_50310402_108X8_dialog_content = "Ações imprudentes só levam à morte de soldados que acreditaram em você.",
  ui_story_5031_50310402_108X9_dialog_content = "Sem grande poder, você não pode defender nenhum ente querido.",
  ui_story_5031_50310402_108X10_dialog_content = "Você não é forte o suficiente... Deve encontrar uma maneira... de ser mais forte.",
  ui_story_5031_50310402_108X11_dialog_content = "Estou muito desapontado...",
  ui_story_5031_50310402_108X12_dialog_content = "Não... Isso não é verdade, padre!",
  ui_story_5031_50310402_108X13_dialog_content = "Carleen!",
  ui_story_5031_50310402_108X14_dialog_content = "Graah!",
  ui_story_5031_50310402_108X15_dialog_content = "Cai fora!!",
  ui_story_5031_50310402_109_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310402_110_dialog_content = "Y-Você não pode usar punhos! Não vamos ganhar pontos.",
  ui_story_5031_50310402_111_dialog_content = "Acalmar, Carleen! Temos que encontrar PlayerName primeiro!",
  ui_story_5031_50310402_112_dialog_content = "... Eu sinto Muito. Você tem razão.",
  ui_story_5031_50310402_113_dialog_content = "<color=#e8d9bb>Toque Toque!</color>",
  ui_story_5031_50310402_114_dialog_content = "\"A partida acabou! Todos os participantes restantes, por favor, subam ao pódio do juiz para pontuar.\"",
  ui_story_5031_50310402_115_dialog_content = "Bom trabalho, Carleen. Passamos para a próxima rodada!",
  ui_story_5031_50310402_116_dialog_content = "Bem, muito disso foi graças ao PlayerName por nos tirar do círculo do Rediesel Wrench.",
  ui_story_5031_50310402_117_dialog_content = "Em nenhum risco pequeno para si mesmo. Eu não permitiria isso em uma batalha real.",
  ui_story_5031_50310402_118_dialog_content = "Aha, o celestita realmente acha que salvou todo mundo!",
  ui_story_5031_50310402_119_dialog_content = "Huh? Azure? O que você quer dizer?",
  ui_story_5031_50310402_120_dialog_content = "Um cara Lumo pegou uma briga do nada. Ele nos distraiu mal.",
  ui_story_5031_50310402_121_dialog_content = "Você pode agradecer a sua estrela da sorte por ele ter feito isso... Sem ele, você estaria frito.",
  ui_story_5031_50310402_122_dialog_content = "Mas foi muito mais divertido derrubá-lo do que jogar esse jogo bobo de criança com pistolas de água.",
  ui_story_5031_50310402_123_dialog_content = "Intitulou-se um nobre, não é como nenhum nobre que já vi, e nos manteve bem ocupados.",
  ui_story_5031_50310402_124_dialog_content = "Uma pena que aquele cara quieto o arrastou. Poderíamos ter lutado muito e duramente.",
  ui_story_5031_50310402_125_dialog_content = "B-chefe...",
  ui_story_5031_50310402_126_dialog_content = "Você se atreve a mostrar seu rosto novamente?",
  ui_story_5031_50310402_127_dialog_content = "Não vamos contra mulheres e crianças. Você esqueceu?!",
  ui_story_5031_50310402_128_dialog_content = "Eu sinto muito. Eu não sei o que deu em mim.",
  ui_story_5031_50310402_129_dialog_content = "Comece com flexões longe do convés principal. Eu trato com você depois da minha bebida.",
  ui_story_5031_50310402_130_dialog_content = "S-Sim, chefe!",
  ui_story_5031_50310402_131_dialog_content = "Sempre chovendo no meu desfile...",
  ui_story_5031_50310402_132_dialog_content = "Não sabia que a Rediesel Wrench tinha esse lado.",
  ui_story_5031_50310402_133_dialog_content = "Vou tomar isso como um elogio. Tudo bem, princesa, eu vou beber com Azure. Vê você.",
  ui_story_5031_50310402_134_dialog_content = "Tchau tchau! Estamos recebendo a bebida grátis por lá. Ei Caelestite, você é bem-vindo para vir.",
  ui_story_5031_50310402_135_dialog_content = "Ufa... De alguma forma acabamos com um oponente a menos para nos preocuparmos.",
  ui_story_5031_50310402_136_dialog_content = "Eu penso Gronru e sua amiga também conseguiu. Eles realmente pontuaram bastante alto.",
  ui_story_5031_50310402_137_dialog_content = "Eu não esperava que todos levariam isso tão a sério. Olhe para Jona e Azure— eliminado na primeira rodada!",
  ui_story_5031_50310402_138_dialog_content = "Tenho certeza que a próxima rodada só vai ser... mais intensa, comovente e antagônica...",
  ui_story_5031_50310402_139_dialog_content = "Ronronar.",
  ui_story_5031_50310402_140_dialog_content = "Isso foi bem audível!",
  ui_story_5031_50310402_141_dialog_content = "Apenas construindo em sua atmosfera ansiosa!",
  ui_story_5031_50310402_142_dialog_content = "Saudações, Laird.",
  ui_story_5031_50310402_143_dialog_content = "Saudações. Você era...",
  ui_story_5031_50310402_144_dialog_content = "Isso mesmo. Eu sou Subli.",
  ui_story_5031_50310402_145_dialog_content = "Jeno me fez trazer isso como um presente.",
  ui_story_5031_50310402_146_dialog_content = "E isso é...?",
  ui_story_5031_50310402_147_dialog_content = "Um cobertor. Ele estava preocupado que você pudesse pegar um resfriado com a brisa do mar.",
  ui_story_5031_50310402_148_dialog_content = "... Eu vejo. Transmita meus agradecimentos.",
  ui_story_5031_50310402_149_dialog_content = "E obrigado também, Subli.",
  ui_story_5031_50310402_150_dialog_content = "Hee, não mencione isso.",
  ui_story_5031_50310402_151_dialog_content = "...",
  ui_story_5031_50310501_1_dialog_content = "Eu os saúdo, bravos guerreiros, que passaram pela primeira rodada!",
  ui_story_5031_50310501_2_dialog_content = "Não há dúvida de que todos vocês provaram sua coragem nesta jornada para o tesouro final.",
  ui_story_5031_50310501_3_dialog_content = "Nossas regras para a próxima rodada também são extremamente simples.",
  ui_story_5031_50310501_4_dialog_content = "Tenho certeza de que todos vocês tiveram o benefício de jogar um jogo muito semelhante quando crianças.",
  ui_story_5031_50310501_5_dialog_content = "Saia, oh besta covarde que se contorce nas horas do crepúsculo! Oh guardião de estranhos artefatos e feitiçarias!",
  ui_story_5031_50310501_6_dialog_content = "<color=#e8d9bb>Baque...!</color>",
  ui_story_5031_50310501_7_dialog_content = "Olha, este é o nosso Guardião do Segredo nesta rodada.",
  ui_story_5031_50310501_8_dialog_content = "Aham. Agora, vou passar por cima de algumas das regras.",
  ui_story_5031_50310501_9_dialog_content = "Quando este Eclipse único fica verde...",
  ui_story_5031_50310501_10_dialog_content = "Você precisa chegar a ele o mais rápido possível, passando por todos os outros Eclipsites bloqueando você.",
  ui_story_5031_50310501_11_dialog_content = "Basta cruzar esta linha em seus pés para se qualificar para a próxima rodada.",
  ui_story_5031_50310501_12_dialog_content = "Por favor, tenha cuidado quando ficar vermelho!",
  ui_story_5031_50310501_13_dialog_content = "Nenhum auroriano ou eclipsita pode se mover. Se você fizer isso, você será jogado ao mar pelo Eclipsite mais próximo, e então você estará fora.",
  ui_story_5031_50310501_14_dialog_content = "Quem não chegar à linha de chegada até o final também está fora.",
  ui_story_5031_50310501_15_dialog_content = "E você pode se sentir à vontade para usar Luminatics apropriados. Sem restrições agora.",
  ui_story_5031_50310501_16_dialog_content = "Exatamente. Então vamos lá! Mostre-nos o que você tem! Desafie minha criatura para o prêmio!",
  ui_story_5031_50310501_17_dialog_content = "PlayerName.",
  ui_story_5031_50310501_18_dialog_content = "Sim. Agora posso finalmente usar meus pontos fortes.",
  ui_story_5031_50310501_19_dialog_content = "Não se preocupe. Vou ajudar todos a chegar à linha de chegada a tempo!",
  ui_story_5031_50310502_1_dialog_content = "Ei! Até eu poderia tirar um Eclipse desses!",
  ui_story_5031_50310502_2_dialog_content = "Assistam e aprendam, seus Eclipsitas imundos!",
  ui_story_5031_50310502_3_dialog_content = "Ei! O grande está prestes a mudar de cor. Melhor parar!",
  ui_story_5031_50310502_4_dialog_content = "Me dê um segundo! Eu posso assumir a liderança!",
  ui_story_5031_50310502_5_dialog_content = "Idiotas. Você está prestes a ser eliminado, não sabia?",
  ui_story_5031_50310502_6_dialog_content = "A propósito, eu tenho que agradecer a você por ganhar pontos na última rodada enquanto eu estava envolvido com aqueles dois bandidos.",
  ui_story_5031_50310502_7_dialog_content = "Eu nunca soube que eles eram tão durões... Esse foi um bom aquecimento.",
  ui_story_5031_50310502_8_dialog_content = "Se você não tivesse me afastado... eu poderia ter feito deles um exemplo!",
  ui_story_5031_50310502_9_dialog_content = "...",
  ui_story_5031_50310502_10_dialog_content = "Tut. Estou tentando elogiá-lo, meu homem! Seus Luminatics fecharam sua boca?",
  ui_story_5031_50310502_11_dialog_content = "<color=#e8d9bb>Toque Toque!</color>",
  ui_story_5031_50310502_12_dialog_content = "Mudou de cor!",
  ui_story_5031_50310502_13_dialog_content = "Graah!",
  ui_story_5031_50310502_14_dialog_content = "D-Não venha!",
  ui_story_5031_50310502_15_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5031_50310502_16_dialog_content = "<color=#e8d9bb>Ploop!!</color>",
  ui_story_5031_50310502_17_dialog_content = "Mais eles vão! Plebeus por nome, plebeus por natureza...",
  ui_story_5031_50310502_18_dialog_content = "Não devemos nos aventurar muito longe da princesa. Proteja-a de perto.",
  ui_story_5031_50310502_19_dialog_content = "Não podemos deixá-la mergulhar no mar como aquelas pobres almas tolas.",
  ui_story_5031_50310502_20_dialog_content = "Obrigado pelo cobertor, Jeno.",
  ui_story_5031_50310502_21_dialog_content = "De nada. Mantenha-se aquecido, mantenha-se bem. Parece que uma brisa forte o derrubaria.",
  ui_story_5031_50310502_22_dialog_content = "Ele Ele. Um jogo estranho para um adulto da sua idade, certo?",
  ui_story_5031_50310502_23_dialog_content = "De que maneira? É muito infantil?",
  ui_story_5031_50310502_24_dialog_content = "De jeito nenhum. Estou um pouco surpreso.",
  ui_story_5031_50310502_25_dialog_content = "Você ainda gosta deste jogo mesmo depois de todos esses anos, até trazê-lo de volta para esta rodada...",
  ui_story_5031_50310502_26_dialog_content = "Porque eu sou uma pessoa bastante nostálgica.",
  ui_story_5031_50310502_27_dialog_content = "Eu também sou amaldiçoado com uma memória longa. Por exemplo, algo tão insignificante quanto um compromisso perdido há muitos anos – pelo qual esperei um dia inteiro.",
  ui_story_5031_50310502_28_dialog_content = "... Peço desculpas por não ter me despedido todos esses anos atrás.",
  ui_story_5031_50310502_29_dialog_content = "Tudo bem.",
  ui_story_5031_50310502_30_dialog_content = "...?",
  ui_story_5031_50310502_31_dialog_content = "Eu só queria ouvir você dizer isso.",
  ui_story_5031_50310502_32_dialog_content = "Eu imagino...",
  ui_story_5031_50310502_33_dialog_content = "Imagine todas as dificuldades envolvidas em subir de filho de dono de restaurante para laird de Harbour City.",
  ui_story_5031_50310502_34_dialog_content = "Mas ainda tenho a forte impressão de que você não mudou nada em tantos outros aspectos importantes. Espero que não esteja errado.",
  ui_story_5031_50310502_35_dialog_content = "De que maneiras importantes?",
  ui_story_5031_50310502_36_dialog_content = "Como os exercícios aeróbicos que você fez em Harbour City. Muito bobo, mas... muito você.",
  ui_story_5031_50310502_37_dialog_content = "Hahaha! Bobo, mas eficaz para ajudar todos a manter a forma.",
  ui_story_5031_50310502_38_dialog_content = "E você? Eu procurei por você por um longo tempo depois de retornar a Lumopolis. Ninguém sabia seu paradeiro.",
  ui_story_5031_50310502_39_dialog_content = "Eu?",
  ui_story_5031_50310502_40_dialog_content = "Eu procurei por você por um longo tempo depois de retornar a Harbour City. Ninguém sabia onde você tinha ido.",
  ui_story_5031_50310502_41_dialog_content = "Alguns até me disseram que você e sua família não estavam mais conosco...",
  ui_story_5031_50310502_42_dialog_content = "Um resumo justo.",
  ui_story_5031_50310502_43_dialog_content = "A Providência nos deu uma fuga para a Esmeralda e, como refugiados fugindo da Crise de Darkover, pegamos nosso bote salva-vidas a todo custo.",
  ui_story_5031_50310502_44_dialog_content = "Como o destino quis, eu acabei sendo salvo por Lady Victoria da Verdadeira Ordem.",
  ui_story_5031_50310502_45_dialog_content = "Ela também me dotou da habilidade de manipular a Origem.",
  ui_story_5031_50310502_46_dialog_content = "Foi somente após meu retorno à Esmeralda que soube que meus pais haviam falecido.",
  ui_story_5031_50310502_47_dialog_content = "E, claro, eu culpei o mestre de cerimônias anterior por sua morte. Eu o desafiei para um duelo em minha ira.",
  ui_story_5031_50310502_48_dialog_content = "A verdade demorou a chegar, tempo suficiente para que o velho mestre de cerimônias perdoasse essa indiscrição.",
  ui_story_5031_50310502_49_dialog_content = "E então éramos apenas eu, a Esmeralda e outros membros do circo em nossa jornada pelo alto mar.",
  ui_story_5031_50310502_50_dialog_content = "Desculpe... Eles eram boas pessoas.",
  ui_story_5031_50310502_51_dialog_content = "Você não precisa se desculpar. Não foi sua culpa.",
  ui_story_5031_50310502_52_dialog_content = "Posso estar aproveitando a Verdadeira Ordem para avançar minha carreira como mago...",
  ui_story_5031_50310502_53_dialog_content = "Mas, verdade seja dita, pouco me importo com a Ordem e suas doutrinas.",
  ui_story_5031_50310502_54_dialog_content = "De qualquer forma, a Ordem tem tantas seitas... Receio estar provavelmente no tipo mais \"desviado\".",
  ui_story_5031_50310502_55_dialog_content = "No entanto, devo honrar a promessa que fiz a Lady Victoria por sua bondade.",
  ui_story_5031_50310502_56_dialog_content = "Eu nunca quero trair uma promessa...",
  ui_story_5031_50310502_57_dialog_content = "Uma promessa... *tosse*",
  ui_story_5031_50310502_58_dialog_content = "Isso é... você está tossindo sangue?",
  ui_story_5031_50310502_59_dialog_content = "Estou bem. Um pouco sobrecarregado com a política... e também este maldito frio...",
  ui_story_5031_50310502_60_dialog_content = "Você me considera um tolo?",
  ui_story_5031_50310502_61_dialog_content = "Haha! Longe disso. Estou muito saudável, obrigado.",
  ui_story_5031_50310502_62_dialog_content = "Ou você quer usar seus poderes de adivinhação para ver meu futuro? Tenho certeza de que ainda me restam mais 200 anos, pelo menos.",
  ui_story_5031_50310502_63_dialog_content = "Adivinhação? Por favor. Você pode me dizer a verdade!",
  ui_story_5031_50310502_64_dialog_content = "*Gasping* Bem, como um ex-residente de Harbour City, você deve estar familiarizado com os chamados \"Heróis Lendários\"?",
  ui_story_5031_50310502_65_dialog_content = "É claro. Uma história de ninar para crianças pequenas.",
  ui_story_5031_50310502_66_dialog_content = "... Mas essa história de ninar é real.",
  ui_story_5031_50310502_67_dialog_content = "...",
  ui_story_5031_50310502_68_dialog_content = "Para simplificar, eles selaram os Eclipsitas com algum tipo de pacto de sangue.",
  ui_story_5031_50310502_69_dialog_content = "Os Eclipsites afetados caíram em profunda hibernação, enquanto Harbour City foi efetivamente protegida da aproximação.",
  ui_story_5031_50310502_70_dialog_content = "Mas isso teve um custo - não apenas para eles, mas também para seus descendentes.",
  ui_story_5031_50310502_71_dialog_content = "E esta é a verdadeira fonte da condição conhecida como Síndrome de Modali.",
  ui_story_5031_50310502_72_dialog_content = "O que? É por isso que você tem essa cicatriz no rosto? Síndrome de Modali?",
  ui_story_5031_50310502_73_dialog_content = "*Tosse* De fato. Mas não se preocupe. Eu estou... ugh... lidando muito bem.",
  ui_story_5031_50310502_74_dialog_content = "Se foi selado com um pacto, então existe alguma maneira de desfazê-lo?",
  ui_story_5031_50310502_75_dialog_content = "Talvez. É isso que venho procurando nesses longos anos... uma solução.",
  ui_story_5031_50310502_76_dialog_content = "E o que você encontrou?",
  ui_story_5031_50310502_77_dialog_content = "Desculpe, ainda não tenho nada adequado para compartilhar. E há segredos e interesses envolvidos que não podem ser contados de forma simples ou leviana.",
  ui_story_5031_50310502_78_dialog_content = "...",
  ui_story_5031_50310502_79_dialog_content = "Olhar! Essa menina é uma potência! Ela está correndo à frente!",
  ui_story_5031_50310502_80_dialog_content = "O parceiro dela nem está usando Luminatics! Como é que ela ainda assume a liderança?",
  ui_story_5031_50310502_81_dialog_content = "Quem não pode usar Luminatics? Ele é um celestita?",
  ui_story_5031_50310502_82_dialog_content = "O que? Vamos ver o celestita!",
  ui_story_5031_50310502_83_dialog_content = "Ringmaster, posso incomodá-lo por um segundo? Um novo lote de suprimentos. Só preciso que você assine.",
  ui_story_5031_50310502_84_dialog_content = "Claro. Eu já vou.",
  ui_story_5031_50310502_85_dialog_content = "Temo que você tenha que julgar sozinho até eu voltar.",
  ui_story_5031_50310502_86_dialog_content = "Vá em frente, Jeno.",
  ui_story_5031_50310602_1_dialog_content = "\"Corrida da 2ª rodada - comece!\"",
  ui_story_5031_50310602_2_dialog_content = "<color=#e8d9bb>Toque Toque!</color>",
  ui_story_5031_50310602_3_dialog_content = "PlayerName! Fique perto de nós!",
  ui_story_5031_50310602_4_dialog_content = "Fique por perto no PlayerName, Vice e Fia! Não deixe Eclipsites chegar até ele.",
  ui_story_5031_50310602_5_dialog_content = "Sim!",
  ui_story_5031_50310602_6_dialog_content = "Não sabia que tínhamos tão pouco tempo para nos mudarmos. Desculpe, não posso ajudar mais.",
  ui_story_5031_50310602_7_dialog_content = "Acho que alguns Aurorianos já correram com seus Luminatics.",
  ui_story_5031_50310602_8_dialog_content = "Deixa para lá. Só precisamos focar.",
  ui_story_5031_50310602_9_dialog_content = "PlayerName, preciso que você me dê um caminho a seguir.",
  ui_story_5031_50310602_10_dialog_content = "Sim!",
  ui_story_5031_50310602_11_dialog_content = "Ah...",
  ui_story_5031_50310602_12_dialog_content = "Isso me irrita em tantos níveis. Eu sei que as regras dizem para manter distância de Sua Alteza, mas não posso permitir isso.",
  ui_story_5031_50310602_13_dialog_content = "Ei, você não é... aquele Juiz? Eu lembro.",
  ui_story_5031_50310602_14_dialog_content = "Na verdade, sou o juiz Matthieu, Vossa Alteza, e esta silenciosa lata de feijão ao meu lado é meu associado, Loewe.",
  ui_story_5031_50310602_15_dialog_content = "eu percebo pobre Pittman esteve sob sua graça, mas o que eu gostaria de dizer é—",
  ui_story_5031_50310602_16_dialog_content = "Sua Alteza... você merece melhor.",
  ui_story_5031_50310602_17_dialog_content = "Um guerreiro poderoso não deve ser unido pelo quadril com alguém incapaz de Luminatics rudimentares.",
  ui_story_5031_50310602_18_dialog_content = "Você já teria se qualificado sem o impedimento desse celestita, mesmo que ele supostamente esteja ajudando.",
  ui_story_5031_50310602_19_dialog_content = "Vejo no celestita a mesma dependência infeliz de todos os plebeus.",
  ui_story_5031_50310602_20_dialog_content = "O-O quê?!",
  ui_story_5031_50310602_21_dialog_content = "Não ligue para ele.",
  ui_story_5031_50310602_22_dialog_content = "O quê?",
  ui_story_5031_50310602_23_dialog_content = "Ele é um pouco torcido por dentro.",
  ui_story_5031_50310602_24_dialog_content = "Ei! O que você está dizendo?!",
  ui_story_5031_50310602_25_dialog_content = "Me diga mais! eu quero ouvir mais.",
  ui_story_5031_50310602_26_dialog_content = "Ele geralmente finge ser descontraído.",
  ui_story_5031_50310602_27_dialog_content = "Mas ele, na verdade, odeia plebeus.",
  ui_story_5031_50310602_28_dialog_content = "Mas ele construiu uma enorme neurose contra os plebeus...",
  ui_story_5031_50310602_29_dialog_content = "O que é engraçado, considerando seu próprio passado...",
  ui_story_5031_50310602_30_dialog_content = "Ei! Nem mais uma palavra! Eu proíbo! Retorne ao seu silêncio!",
  ui_story_5031_50310602_31_dialog_content = "Você vai ouvir e obedecer! Pare!",
  ui_story_5031_50310602_32_dialog_content = "... Cale-se!",
  ui_story_5031_50310602_33_dialog_content = "Tut.",
  ui_story_5031_50310602_34_dialog_content = "Achei que todos os nobres de Lumopolis desprezavam os plebeus em diferentes graus.",
  ui_story_5031_50310602_35_dialog_content = "Não é o mesmo.",
  ui_story_5031_50310602_X35_dialog_content = "Ele lava a mão pelo menos dez vezes se alguém tocar sua mão por acidente.",
  ui_story_5031_50310602_X36_dialog_content = "Ele grita quando a poeira cai sobre ele.",
  ui_story_5031_50310602_36_dialog_content = "Ah... May bem como viver dentro de um caso e acabar com o mundo exterior.",
  ui_story_5031_50310602_37_dialog_content = "Sim, ele é obcecado por limpeza a um nível louco.",
  ui_story_5031_50310602_38_dialog_content = "Eu sinto muito por ouvir isso...",
  ui_story_5031_50310602_39_dialog_content = "Eu não preciso de pena de uma moça retrógrada como você!",
  ui_story_5031_50310602_40_dialog_content = "Ele relaxa no trabalho.",
  ui_story_5031_50310602_41_dialog_content = "Preguiçoso no trabalho, você diz? Você não está pintando um quadro impressionante.",
  ui_story_5031_50310602_42_dialog_content = "E aproveita os sentimentos de seus antigos colegas de classe.",
  ui_story_5031_50310602_X42_dialog_content = "Empurra as coisas para Pittma...",
  ui_story_5031_50310602_43_dialog_content = "<color=#e8d9bb>Toque Toque!</color>",
  ui_story_5031_50310602_44_dialog_content = "Está mudando de cor! Segure seus cavalos, todos!",
  ui_story_5031_50310602_45_dialog_content = "Essa não!",
  ui_story_5031_50310602_46_dialog_content = "Não consigo parar de correr! Ajude-me!",
  ui_story_5031_50310602_47_dialog_content = "G-Afaste-se de mim, plebeu sujo!",
  ui_story_5031_50310602_48_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5031_50310602_49_dialog_content = "Eu sinto muito, senhor.",
  ui_story_5031_50310602_50_dialog_content = "Cai fora! Um jeito!",
  ui_story_5031_50310602_51_dialog_content = "As minhas roupas! Eu preciso ir para um vestiário!",
  ui_story_5031_50310602_52_dialog_content = "Vou voltar para um banho, Loewe!",
  ui_story_5031_50310602_53_dialog_content = "Ele é um comedor exigente.",
  ui_story_5031_50310602_54_dialog_content = "Ele diz que sua língua é tão sensível ao calor.",
  ui_story_5031_50310602_55_dialog_content = "Gritando coisas como: \"Ah! Está tão quente!\"",
  ui_story_5031_50310602_56_dialog_content = "E me faz dar uma olhada nisso!",
  ui_story_5031_50310602_57_dialog_content = "Eu não quero olhar para isso de jeito nenhum.",
  ui_story_5031_50310602_58_dialog_content = "Três foram eliminados!",
  ui_story_5031_50310602_59_dialog_content = "Falo com você mais tarde!",
  ui_story_5031_50310602_60_dialog_content = "Eu tenho uma sensação tão diferente da impressão da aparência. Esta maneira curta e concisa de falar é impressionante.",
  ui_story_5031_50310602_X60_dialog_content = "Sim, esta parece ser uma pessoa interessante.",
  ui_story_5031_50310602_61_dialog_content = "Eu sinto Muito, Carleen.",
  ui_story_5031_50310602_62_dialog_content = "Para que? Não ouça nada que Matthieu disse.",
  ui_story_5031_50310602_63_dialog_content = "Você está se esforçando tanto, mas eu não sou muito bom em uma luta. Às vezes acho que estou te decepcionando.",
  ui_story_5031_50310602_64_dialog_content = "Você acha que estou tentando demais? É por isso que você está dizendo isso?",
  ui_story_5031_50310602_65_dialog_content = "Sim. Acho que você foi o principal competidor neste carnaval... carregando nosso time nos ombros.",
  ui_story_5031_50310602_66_dialog_content = "Você acha...?",
  ui_story_5031_50310602_67_dialog_content = "Nunca te considerei um fardo. Na verdade, você é nossa arma secreta com todas as coisas que você pode fazer!",
  ui_story_5031_50310602_68_dialog_content = "Claro, PlayerName. Você sempre foi um companheiro de equipe muito importante.",
  ui_story_5031_50310602_69_dialog_content = "Graças a Deus. PlayerName, você não pode se deixar influenciar pelo que algum esquisitão aleatório diz.",
  ui_story_5031_50310602_70_dialog_content = "Pessoal...",
  ui_story_5031_50310602_71_dialog_content = "<color=#e8d9bb>Toque Toque!</color>",
  ui_story_5031_50310602_72_dialog_content = "Está verde agora. Prepare-se!",
  ui_story_5031_50310602_73_dialog_content = "OK. Todos, sigam em frente!",
  ui_story_5031_50310701_1_dialog_content = "Estamos quase lá, PlayerName.",
  ui_story_5031_50310701_2_dialog_content = "Só mais alguns passos para a próxima rodada...",
  ui_story_5031_50310701_3_dialog_content = "<color=#e8d9bb>Toque Toque!</color>",
  ui_story_5031_50310701_4_dialog_content = "Todos, movam-se!",
  ui_story_5031_50310701_5_dialog_content = "Espere, pare!",
  ui_story_5031_50310701_6_dialog_content = "Ele está de volta à cor original agora!",
  ui_story_5031_50310701_7_dialog_content = "<color=#e8d9bb>Toque Toque!</color>",
  ui_story_5031_50310701_8_dialog_content = "O que aconteceu? Está ficando mais rápido?",
  ui_story_5031_50310701_9_dialog_content = "Ai!",
  ui_story_5031_50310701_10_dialog_content = "Caramba. Está girando muito rápido agora!",
  ui_story_5031_50310701_11_dialog_content = "Eles estão testando os tempos de reação – caso contrário, por que torná-lo tão imprevisível?",
  ui_story_5031_50310701_12_dialog_content = "Temos que andar com cuidado agora.",
  ui_story_5031_50310701_13_dialog_content = "Outros quatro concorrentes são eliminados!",
  ui_story_5031_50310701_14_dialog_content = "Você vê aquela garota ali, Carleen? Acho que algo está errado com ela.",
  ui_story_5031_50310701_15_dialog_content = "Ela não parece muito feliz. Eu posso sentir seu poder Lumina ficando mais fraco a cada segundo.",
  ui_story_5031_50310701_16_dialog_content = "Tadinha...",
  ui_story_5031_50310701_17_dialog_content = "Oh não. Ela desmoronou!",
  ui_story_5031_50310701_18_dialog_content = "Isso não significa que ela vai ser jogada na água?",
  ui_story_5031_50310701_19_dialog_content = "Parece que ela está com dor com os olhos fechados.",
  ui_story_5031_50310701_20_dialog_content = "Eles não podem jogá-la no mar se ela tiver uma condição médica!",
  ui_story_5031_50310701_21_dialog_content = "PlayerName, PlayerName, temos que pensar em algo.",
  ui_story_5031_50310701_22_dialog_content = "Ah...",
  ui_story_5031_50310701_23_dialog_content = "Não podemos esperar mais!",
  ui_story_5031_50310701_24_dialog_content = "Carleen!",
  ui_story_5031_50310702_1_dialog_content = "Tempo esgotado!!",
  ui_story_5031_50310702_2_dialog_content = "Qualquer que seja o problema, Alteza?",
  ui_story_5031_50310702_3_dialog_content = "Esta senhora não está bem.",
  ui_story_5031_50310702_4_dialog_content = "Vou dar uma olhada. Conheço alguns remédios.",
  ui_story_5031_50310702_5_dialog_content = "Você está bem, mocinha? Você pode me ouvir?",
  ui_story_5031_50310702_6_dialog_content = "Tadinha...",
  ui_story_5031_50310702_7_dialog_content = "Conheço a condição... Síndrome de Modali.",
  ui_story_5031_50310702_8_dialog_content = "Rápido, tome esta pílula.",
  ui_story_5031_50310702_9_dialog_content = "Posso incomodá-lo para trazer esse cobertor, Jeno?",
  ui_story_5031_50310702_10_dialog_content = "Claro.",
  ui_story_5031_50310702_11_dialog_content = "Arf, arf...",
  ui_story_5031_50310702_12_dialog_content = "Laird Elvis... Obrigado. Estou me sentindo muito melhor.",
  ui_story_5031_50310702_13_dialog_content = "Não se esforce demais. A temperatura do seu corpo está baixa. Você ficará mais confortável em um cobertor.",
  ui_story_5031_50310702_14_dialog_content = "Sim... Obrigado, senhor, você nos ensinou os exercícios aeróbicos, e eu sempre bebi água morna.",
  ui_story_5031_50310702_15_dialog_content = "Sim, muito bem, Ranka. Estou orgulhoso de você.",
  ui_story_5031_50310702_16_dialog_content = "O cobertor, Elvis.",
  ui_story_5031_50310702_17_dialog_content = "Ah. Obrigada.",
  ui_story_5031_50310702_18_dialog_content = "Patou!",
  ui_story_5031_50310702_19_dialog_content = "Aqui estou, senhor.",
  ui_story_5031_50310702_20_dialog_content = "Faça com que os guardas a levem de volta para sua família e mostrem a eles a urgência de uma visita ao hospital.",
  ui_story_5031_50310702_21_dialog_content = "Deixe comigo, senhor!",
  ui_story_5031_50310702_22_dialog_content = "Você vê como ela é jovem, Jeno?",
  ui_story_5031_50310702_23_dialog_content = "...",
  ui_story_5031_50310702_24_dialog_content = "Laird Elvis, você é um laird fiel e bondoso de Harbour City.",
  ui_story_5031_50310702_25_dialog_content = "Eu vi mais nobreza de você hoje do que de uma vida inteira de muitos chamados nobres.",
  ui_story_5031_50310702_26_dialog_content = "Harbour City é realmente afortunado por ter um laird como você.",
  ui_story_5031_50310702_27_dialog_content = "Sheesh. Ela é apenas mais uma plebeia. Acho que perdeu a perspectiva, Alteza.",
  ui_story_5031_50310702_28_dialog_content = "Tão desagradável ser... semi-assaltado por aquele plebeu eliminado.",
  ui_story_5031_50310702_29_dialog_content = "Quase fui lançado ao mar. Mas consegui me reerguer.",
  ui_story_5031_50310702_30_dialog_content = "Quando na terra podemos voltar para um banho e trocar de roupa?",
  ui_story_5031_50310702_31_dialog_content = "Silêncio.",
  ui_story_5031_50310702_32_dialog_content = "Obrigado pelas suas amáveis palavras, Alteza.",
  ui_story_5031_50310702_33_dialog_content = "Mas não posso ajudar muito mais do que isso.",
  ui_story_5031_50310702_34_dialog_content = "Desculpe, mas o dever urgente chama. Até tarde.",
  ui_story_5031_50310702_35_dialog_content = "Certamente.",
  ui_story_5031_50310702_36_dialog_content = "...",
  ui_story_5031_50310702_37_dialog_content = "Você mandou me chamar, senhor?",
  ui_story_5031_50310702_38_dialog_content = "Estamos ficando sem tempo, Patou.",
  ui_story_5031_50310702_39_dialog_content = "o <color=#FFB400>Pedra do Vento</color> fica mais fraco. Eu posso sentir isso.",
  ui_story_5031_50310702_40_dialog_content = "É por isso que eu, e depois a garota, caímos nessa doença.",
  ui_story_5031_50310702_41_dialog_content = "Temo que o selo não dure muito mais.",
  ui_story_5031_50310702_42_dialog_content = "Por que não procurar ajuda de Lumopolis, senhor? E aquela senhora de bom coração, princesa Carleen?",
  ui_story_5031_50310702_43_dialog_content = "Ela pode nos colocar em contato com o Senhor Schwartz.",
  ui_story_5031_50310702_44_dialog_content = "Eu confio nesse Senhor Schwartz tem o discernimento para nos ajudar nesta questão.",
  ui_story_5031_50310702_45_dialog_content = "Mas minha razão me diz para não confiar no Conselho dos Anciões.",
  ui_story_5031_50310702_46_dialog_content = "O que é mais provável? Que enviarão tropas para defender Harbour City? Ou nos pedir para desocupar a terra que herdamos por gerações?",
  ui_story_5031_50310702_47_dialog_content = "Pense no custo pago por nossos ancestrais para proteger o segredo do Windstone... Está bem guardado até hoje.",
  ui_story_5031_50310702_48_dialog_content = "Se sua existência for comentada no exterior, talvez também tenhamos que lidar com aqueles que querem tomá-la.",
  ui_story_5031_50310702_49_dialog_content = "Então, sem o Windstone, Harbour City está certamente perdida.",
  ui_story_5031_50310702_50_dialog_content = "Não entregarei à destruição aquilo pelo qual nossos antepassados deram suas vidas e que gerações construíram com suor e trabalho.",
  ui_story_5031_50310702_51_dialog_content = "Tudo o que faço é para a segurança de Harbour City. A realidade é que estamos sozinhos.",
  ui_story_5031_50310702_52_dialog_content = "Sim senhor. Eu entendo.",
  ui_story_5031_50310702_53_dialog_content = "De bom grado oferecemos nossas vidas a fogo e espada em defesa de Harbour City e da Casa Modali.",
  ui_story_5031_50310702_54_dialog_content = "E não há como voltar atrás.",
  ui_story_5031_50310702_55_dialog_content = "A derrota significará o fim de Harbour City e seus moradores. Ninguém está vindo para nos salvar.",
  ui_story_5031_50310702_56_dialog_content = "Devemos aprender a nos salvar, Patou.",
  ui_story_5031_50310702_57_dialog_content = "Princesa Carleen, você tem certeza de manter sua identidade oculta?",
  ui_story_5031_50310702_58_dialog_content = "Sim. Não quero que nada se interponha entre mim e nossas férias relaxantes. Obrigado pela compreensão, Laird Elvis.",
  ui_story_5031_50310702_59_dialog_content = "Muito bem.",
  ui_story_5031_50310702_60_dialog_content = "Ouçam-me, todos.",
  ui_story_5031_50310702_61_dialog_content = "A senhora que acabou de desmaiar de doença teria sido jogada ao mar por Eclipsites de acordo com nossas regras.",
  ui_story_5031_50310702_62_dialog_content = "No entanto, esta corajosa senhora e seus companheiros arriscaram a desqualificação para salvá-la de uma situação perigosa!",
  ui_story_5031_50310702_63_dialog_content = "Ela poderia ter caído inconsciente na água.",
  ui_story_5031_50310702_64_dialog_content = "Eles podem ter quebrado as regras, mas nós recompensamos o tipo de coração aqui em Harbor City!",
  ui_story_5031_50310702_65_dialog_content = "... E como esse é o nosso costume, espero que você se junte a mim para dar as boas-vindas à equipe de volta à competição!",
  ui_story_5031_50310702_66_dialog_content = "Viva! Viva!",
  ui_story_5031_50310702_67_dialog_content = "Você é incrível, Laird Elvis!",
  ui_story_5031_50310702_68_dialog_content = "Obrigado, todos! Tenho a honra de ser seu governador.",
  ui_story_5031_50310702_69_dialog_content = "Obrigado, Laird Elvis!",
  ui_story_5031_50310702_70_dialog_content = "Não mencione isso. Tenho certeza que todos vocês teriam feito o mesmo.",
  ui_story_5031_50310702_71_dialog_content = "Você e seus companheiros podem retornar à partida.",
  ui_story_5031_50310702_X71_dialog_content = "Então vamos continuar!",
  ui_story_5031_50310702_X72_dialog_content = "Aff, aff...! Vocês estão correndo muito rápido. Chegamos até a linha de chegada de alguma forma.",
  ui_story_5031_50310702_X73_dialog_content = "Apresse-se, PlayerName! Está mudando de cor novamente!",
  ui_story_5031_50310702_X74_dialog_content = "Seriamente? Não, não posso mais.",
  ui_story_5031_50310702_72_dialog_content = "Corra aqui, PlayerName. Nós vamos pegar você!",
  ui_story_5031_50310702_73_dialog_content = "Sim!",
  ui_story_5031_50310702_74_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5031_50310702_75_dialog_content = "Essa foi por pouco.",
  ui_story_5031_50310702_76_dialog_content = "Você é muito pesado, PlayerName.",
  ui_story_5031_50310702_77_dialog_content = "Conseguimos!",
  ui_story_5031_50310702_78_dialog_content = "Estamos na próxima rodada!",
  ui_story_5031_50310702_79_dialog_content = "Mas muitos outros concorrentes fortes também conseguiram.",
  ui_story_5031_50310702_80_dialog_content = "Essa pessoa fazendo uma cena... é aquele oficial Gronru?",
  ui_story_5031_50310702_81_dialog_content = "Ei! Apresse-se, Ciel!",
  ui_story_5031_50310702_82_dialog_content = "Vamos lá, use o seu ultimate!",
  ui_story_5031_50310702_83_dialog_content = "Ou seremos eliminados!",
  ui_story_5031_50310702_84_dialog_content = "C-Ce, mas <color=#FFB400>Estige</color> está parado...",
  ui_story_5031_50310702_85_dialog_content = "Certo. \"Atualização do status do mecanismo de perna - Mark II.\"",
  ui_story_5031_50310702_86_dialog_content = "\"Aumentar a liberação de energia em 50%.\"",
  ui_story_5031_50310702_87_dialog_content = "Vamos!",
  ui_story_5031_50310702_88_dialog_content = "Uau! Ciel acabou de passar direto!",
  ui_story_5031_50310702_89_dialog_content = "Ahhh! Fora do caminho, todos! Perdi o controle de Styx!",
  ui_story_5031_50310702_90_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50310702_91_dialog_content = "V-Muito impressionante. Até deixou um buraco no prédio.",
  ui_story_5031_50310702_92_dialog_content = "E uma marca bastante longa no convés.",
  ui_story_5031_50310702_93_dialog_content = "Uau, isso é simplesmente incrível. Onde ela foi?",
  ui_story_5031_50310702_94_dialog_content = "Tudo bem, Ciel?",
  ui_story_5031_50310702_95_dialog_content = "Ai, ai! Eu não acho que estou ferido.",
  ui_story_5031_50310702_96_dialog_content = "Você pode não estar ferido, mas não posso dizer o mesmo da nossa amada Esmeralda.",
  ui_story_5031_50310702_97_dialog_content = "Oh. Eu sinto muito!",
  ui_story_5031_50310702_98_dialog_content = "Eu não queria! Eu não terminei de depurar o Styx - não, a culpa é minha por ser fraco...",
  ui_story_5031_50310702_99_dialog_content = "Está tudo bem. Não estou interessado em culpa. Vamos apenas pensar no que fazer a seguir.",
  ui_story_5031_50310702_100_dialog_content = "O ideal seria contratar alguém para consertá-lo.",
  ui_story_5031_50310702_101_dialog_content = "Mas não acho que Ciel seja filho do dinheiro.",
  ui_story_5031_50310702_102_dialog_content = "Você tem razão. Me desculpe por isso...",
  ui_story_5031_50310702_103_dialog_content = "Pare de se desculpar. Vamos. Está tudo bem!",
  ui_story_5031_50310702_104_dialog_content = "Isto me lembra! Você pode desafiar nossa próxima rodada - um concurso de surf!",
  ui_story_5031_50310702_105_dialog_content = "Laird Elvis está patrocinando a próxima rodada com um prêmio extra para o vencedor.",
  ui_story_5031_50310702_106_dialog_content = "R-Sério!?",
  ui_story_5031_50310702_107_dialog_content = "De fato! E tenho certeza... são cinco milhões de Nightium!",
  ui_story_5031_50310702_108_dialog_content = "Isso é suficiente para cobrir os custos de reparo.",
  ui_story_5031_50310702_109_dialog_content = "Maravilhoso! Estou dentro!",
  ui_story_5031_50310702_110_dialog_content = "Ei, não vamos nos antecipar.",
  ui_story_5031_50310702_111_dialog_content = "Eu e as irmãs Merylt também estamos nos juntando.",
  ui_story_5031_50310702_112_dialog_content = "E pretendo vencer, Ciel!",
  ui_story_5031_50310702_113_dialog_content = "Se você perder... oh, qual é o nome mesmo? Styx, certo?",
  ui_story_5031_50310702_114_dialog_content = "Será meu.",
  ui_story_5031_50310702_115_dialog_content = "... Não posso.",
  ui_story_5031_50310702_116_dialog_content = "Ei. Eu só quero pegar emprestado para estudá-lo. Eu não vou roubá-lo de você ou qualquer coisa assim.",
  ui_story_5031_50310702_117_dialog_content = "Devolvo depois.",
  ui_story_5031_50310702_118_dialog_content = "Desculpe.",
  ui_story_5031_50310702_119_dialog_content = "A coisa é... eu simplesmente não posso fazer isso...",
  ui_story_5031_50310801_1_dialog_content = "Ei a todos! Espero que a brisa fresca do verão e as frutas de graça tenham animado todos vocês?",
  ui_story_5031_50310801_2_dialog_content = "Você parece bem descansado e pronto para entrar na próxima rodada da competição!",
  ui_story_5031_50310801_3_dialog_content = "Sim!",
  ui_story_5031_50310801_4_dialog_content = "Oh, você parece muito animado! E parece que você não pode esperar mais.",
  ui_story_5031_50310801_5_dialog_content = "Então, desta vez, podemos enxugar um pouco do suor que acumulamos.",
  ui_story_5031_50310801_6_dialog_content = "É hora de um mergulho fresco no grande banho de mar sob este sol quente!",
  ui_story_5031_50310801_7_dialog_content = "É o momento pelo qual todos vocês estavam esperando - um <size=45>concurso de surf</size>!",
  ui_story_5031_50310801_8_dialog_content = "Uau!!",
  ui_story_5031_50310801_9_dialog_content = "E porque é tradição ter campeonatos de surf em Harbour City, a equipa vencedora...",
  ui_story_5031_50310801_10_dialog_content = "... Eles também receberão uma recompensa especial de Laird Elvis de <color=#FFB400>cinco milhões de Nightium</color>!",
  ui_story_5031_50310801_11_dialog_content = "F-Cinco milhões?",
  ui_story_5031_50310801_12_dialog_content = "Cinco milhões!?",
  ui_story_5031_50310801_13_dialog_content = "PlayerName, Vice! Não seja ganancioso!",
  ui_story_5031_50310801_14_dialog_content = "Não se esqueça porque estamos aqui!",
  ui_story_5031_50310801_15_dialog_content = "Sim... Mas talvez possamos ganhar algum dinheiro enquanto ajudamos Fia a pegar aquela fera maravilhosa.",
  ui_story_5031_50310801_16_dialog_content = "Harbour City é muito rico, não é?",
  ui_story_5031_50310801_17_dialog_content = "De fato é. Eles estiveram em um boom nos últimos anos.",
  ui_story_5031_50310801_18_dialog_content = "Não é todo dia que você vê um laird jogar um grande prêmio para seu povo.",
  ui_story_5031_50310801_19_dialog_content = "Não é à toa que Harbour City está indo bem se é isso que Laird Elvis está fazendo.",
  ui_story_5031_50310801_20_dialog_content = "Carleen realmente tem feito o seu melhor, não é?",
  ui_story_5031_50310801_21_dialog_content = "Suponho que você tenha pensado em todos os problemas econômicos durante essas férias?",
  ui_story_5031_50310801_22_dialog_content = "Ah, me desculpe se eu matar o clima para vocês...",
  ui_story_5031_50310801_23_dialog_content = "Não não. Não é isso que quero dizer.",
  ui_story_5031_50310801_24_dialog_content = "Estou um pouco preocupado que você esteja ficando cansado.",
  ui_story_5031_50310801_25_dialog_content = "Sim, Carleen! Não vale o estresse. Vamos nos soltar!",
  ui_story_5031_50310801_26_dialog_content = "Veja como a Fia está se divertindo com aquele abacaxi.",
  ui_story_5031_50310801_27_dialog_content = "Tenho certeza que ela está bem e verdadeiramente distraída de seu grande esquema.",
  ui_story_5031_50310801_28_dialog_content = "Hum! É realmente doce!",
  ui_story_5031_50310801_29_dialog_content = "É ótimo, você sabe, eles têm frutas grátis!",
  ui_story_5031_50310801_30_dialog_content = "Sim. É de fato.",
  ui_story_5031_50310801_31_dialog_content = "Tenho muito a aprender com a Fia.",
  ui_story_5031_50310801_32_dialog_content = "<size=33>E não só ela, mas também Vice e PlayerName também...</size>",
  ui_story_5031_50310801_33_dialog_content = "Você e eu sabemos que os Eclipsitas não podem ser exterminados.",
  ui_story_5031_50310801_34_dialog_content = "Um governante deve exercer mais contenção – não se precipitar no meio da ação para detê-los você mesmo.",
  ui_story_5031_50310801_35_dialog_content = "Você não é o único que sofrerá nessa troca — e aqueles que o seguem?",
  ui_story_5031_50310801_36_dialog_content = "...",
  ui_story_5031_50310801_37_dialog_content = "Eu quero que você realmente considere por que eu permiti que você acompanhasse PlayerName e os outros.",
  ui_story_5031_50310801_38_dialog_content = "Eu...",
  ui_story_5031_50310801_39_dialog_content = "Você precisa de mais tempo para crescer em seu papel nobre e privilegiado na vida.",
  ui_story_5031_50310801_40_dialog_content = "... Sim, Pai.",
  ui_story_5031_50310801_41_dialog_content = "Carleen? Carleen!",
  ui_story_5031_50310801_42_dialog_content = "Huh? Perdão, o que você disse?",
  ui_story_5031_50310801_43_dialog_content = "Eu só estava dizendo que talvez devêssemos nos trocar? Vamos passar muito tempo na água com certeza.",
  ui_story_5031_50310801_44_dialog_content = "Não pode manchar suas roupas novas!",
  ui_story_5031_50310801_45_dialog_content = "Ah. Muito bem.",
  ui_story_5031_50310801_46_dialog_content = "Espere — no que devo me transformar?",
  ui_story_5031_50310801_47_dialog_content = "Ei! Isso seria naturalmente—",
  ui_story_5031_50310801_48_dialog_content = "Roupa de banho!",
  ui_story_5031_50310801_49_dialog_content = "Uau! Você parece bem, Carleen e Vice!",
  ui_story_5031_50310801_50_dialog_content = "Obrigado, Fia.",
  ui_story_5031_50310801_51_dialog_content = "E-como você trouxe meu maiô também?",
  ui_story_5031_50310801_52_dialog_content = "Quem não leva um maiô para a praia?",
  ui_story_5031_50310801_53_dialog_content = "Esses são nossos primeiros esportes aquáticos, então não pensei em tirá-los até agora.",
  ui_story_5031_50310801_54_dialog_content = "Eu gostaria de ter um maiô, também!",
  ui_story_5031_50310801_55_dialog_content = "Iremos direto para um outlet de moda Harbour City depois de pedir um para você!",
  ui_story_5031_50310801_56_dialog_content = "Sério? Valeu, Vice!",
  ui_story_5031_50310801_57_dialog_content = "Uau. Primeira vez que encomendei roupas de banho personalizadas para mim. Incrível!",
  ui_story_5031_50310801_58_dialog_content = "Eu também notei alguns utensílios muito bons antes. Talvez possamos comprá-los também!",
  ui_story_5031_50310801_59_dialog_content = "Ótimo!",
  ui_story_5031_50310801_60_dialog_content = "Ah, uma coisinha...",
  ui_story_5031_50310801_61_dialog_content = "Aham, eu...",
  ui_story_5031_50310801_62_dialog_content = "Huh? O que é isso, PlayerName?",
  ui_story_5031_50310801_63_dialog_content = "Desculpe por interromper você no meio de uma grande conversa...",
  ui_story_5031_50310801_64_dialog_content = "Mas... eu não posso surfar.",
  ui_story_5031_50310801_65_dialog_content = "<size=45>O quê?!</size>",
  ui_story_5031_50310801_66_dialog_content = "Então isso significa que eu não vou pegar meu maiô?",
  ui_story_5031_50310801_67_dialog_content = "É com isso que você está preocupado? Você se esqueceu do nosso verdadeiro propósito aqui - sua besta maravilhosa?",
  ui_story_5031_50310801_68_dialog_content = "Meu maiô, assim como o Cloudwhale... Boo-hoo...",
  ui_story_5031_50310801_69_dialog_content = "... Eles estão todos fora de alcance! Waaaah!",
  ui_story_5031_50310801_70_dialog_content = "Sinto muito, Fia. Não chore!",
  ui_story_5031_50310801_71_dialog_content = "Vou pensar em uma maneira, mesmo que não consigamos o primeiro lugar...",
  ui_story_5031_50310801_72_dialog_content = "Tenho certeza de que podemos encontrar dinheiro suficiente para algumas roupas de banho!",
  ui_story_5031_50310801_73_dialog_content = "...É mesmo?",
  ui_story_5031_50310801_74_dialog_content = "Sim! Carleen e Vice pode atestar para mim, não pode?",
  ui_story_5031_50310801_75_dialog_content = "T-Isso seria ótimo!",
  ui_story_5031_50310801_76_dialog_content = "Desculpe, eu não deveria ter começado a fantasiar sobre ganhar o prêmio antes de perguntar claramente sobre a situação.",
  ui_story_5031_50310801_77_dialog_content = "Não é sua culpa, Vice. Eu sou tão descoordenada. Eu não posso nem surfar!",
  ui_story_5031_50310801_78_dialog_content = "Oh, não, você não entendeu, PlayerName.",
  ui_story_5031_50310801_79_dialog_content = "Nem todo mundo é feito para surfar.",
  ui_story_5031_50310801_80_dialog_content = "Aconteceu de eu ter estudado isso antes.",
  ui_story_5031_50310801_X80_dialog_content = "Eu também. Quando visitei Harbour City na minha infância, acabei de assistir à competição de surf daquele ano.",
  ui_story_5031_50310801_X81_dialog_content = "Foi por isso que me interessei por ele e me tornei professor.",
  ui_story_5031_50310801_81_dialog_content = "Oh? Então, onde você aprendeu a surfar, Fia?",
  ui_story_5031_50310801_82_dialog_content = "Huh? Nunca aprendi a surfar.",
  ui_story_5031_50310801_83_dialog_content = "O quê?!",
  ui_story_5031_50310801_84_dialog_content = "Então por que você estava chorando? Se você nunca fez isso antes e não sabe como!",
  ui_story_5031_50310801_85_dialog_content = "Como você pode gritar comigo assim, celestita! Você não vai encontrar uma namorada com uma atitude dessas.",
  ui_story_5031_50310801_86_dialog_content = "Uma g-namorada?",
  ui_story_5031_50310801_87_dialog_content = "O que você está falando? Ei, volte!",
  ui_story_5031_50310801_88_dialog_content = "Uau! Todo mundo está indo para a água! Devemos ir agora!",
  ui_story_5031_50310801_89_dialog_content = "... Você é rápido!",
  ui_story_5031_50310801_90_dialog_content = "...",
  ui_story_5031_50310801_91_dialog_content = "...",
  ui_story_5031_50310801_92_dialog_content = "(Como ficou tão estranho de repente?)",
  ui_story_5031_50310801_93_dialog_content = "Ahem, então, vamos lá agora também, não é?",
  ui_story_5031_50310801_94_dialog_content = "Sim. Eu penso que sim.",
  ui_story_5031_50310801_95_dialog_content = "OK. Vamos lá.",
  ui_story_5031_50310801_96_dialog_content = "(O que tem neles?)",
  ui_story_5031_50310801_97_dialog_content = "Certo. Coloque as duas mãos paralelas ao redor da parte inferior do peito e junte os pés.",
  ui_story_5031_50310801_98_dialog_content = "Em seguida, use a força em seus braços para apoiar seu corpo.",
  ui_story_5031_50310801_99_dialog_content = "L-Assim?",
  ui_story_5031_50310801_100_dialog_content = "Isso mesmo. Olhe para a frente. Você está indo bem.",
  ui_story_5031_50310801_101_dialog_content = "Quando a onda aparecer, essa é a sua deixa para ficar de pé. Mantenha os pés na mesma largura dos ombros e endireite as costas.",
  ui_story_5031_50310801_102_dialog_content = "Aqui está uma onda!",
  ui_story_5031_50310801_103_dialog_content = "Sente a sua prancha de surf a ganhar velocidade debaixo da onda? Está acontecendo!",
  ui_story_5031_50310801_104_dialog_content = "T-tudo bem!",
  ui_story_5031_50310801_105_dialog_content = "De pé... Uau!",
  ui_story_5031_50310801_106_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5031_50310801_107_dialog_content = "PlayerName!",
  ui_story_5031_50310801_108_dialog_content = "*Cof*",
  ui_story_5031_50310801_109_dialog_content = "Estou bem. Eu ainda estou vivo...",
  ui_story_5031_50310801_110_dialog_content = "Vamos, PlayerName. Não seja tão fraco.",
  ui_story_5031_50310801_111_dialog_content = "Até eu sei ficar em pé em uma prancha de surf.",
  ui_story_5031_50310801_112_dialog_content = "Você não está de pé! Você está claramente agachado!",
  ui_story_5031_50310801_113_dialog_content = "Ainda sou melhor que você!",
  ui_story_5031_50310801_114_dialog_content = "E com a ideia de Carleen, tudo que eu preciso aprender é agachar!",
  ui_story_5031_50310801_115_dialog_content = "Não se esqueça que eu sou o único que pode pedir para o peixe vir ajudar a empurrar minha prancha de surf!",
  ui_story_5031_50310801_116_dialog_content = "Você tem que ser...",
  ui_story_5031_50310801_117_dialog_content = "A hora chegou!",
  ui_story_5031_50310801_118_dialog_content = "Uau! É ótimo ver tanta gente lá fora praticando nas ondas. Bom trabalho!",
  ui_story_5031_50310801_119_dialog_content = "Parece que a promessa de 5 milhões de Nightium é extremamente atraente!",
  ui_story_5031_50310801_120_dialog_content = "Haha!",
  ui_story_5031_50310801_121_dialog_content = "Ei! Estou brincando!",
  ui_story_5031_50310801_122_dialog_content = "Então vamos começar com as regras!",
  ui_story_5031_50310801_123_dialog_content = "Como antes, quatro pessoas para uma equipe. Você vai se revezar pegando as ondas.",
  ui_story_5031_50310801_124_dialog_content = "Se você não tiver quatro pessoas em sua equipe, poderá entrar com menos.",
  ui_story_5031_50310801_125_dialog_content = "Você pode entrar com apenas duas pessoas, porque apenas os dois melhores desempenhos da sua equipe serão pontuados!",
  ui_story_5031_50310801_126_dialog_content = "Como antes, você ganha pontos por eliminar ilusões de Eclipsite. Mas você não será eliminado por cair na água.",
  ui_story_5031_50310801_127_dialog_content = "Além de Eclipsites, metade de seus pontos virão de sua técnica de surf.",
  ui_story_5031_50310801_128_dialog_content = "Então sugiro organizar a ordem em que você vai. Será muito importante!",
  ui_story_5031_50310801_129_dialog_content = "Oh não! Acabei de revelar um segredo importante para vencer. Acho que vai tornar o concurso muito mais intenso!",
  ui_story_5031_50310801_130_dialog_content = "Hahahahaha!",
  ui_story_5031_50310801_131_dialog_content = "De qualquer forma, divirtam-se, pessoal!",
  ui_story_5031_50310801_132_dialog_content = "Estamos prestes a começar a primeira rodada - em um momento.",
  ui_story_5031_50310801_133_dialog_content = "Todas as equipes, por favor, se alinham? E podemos ter o primeiro jogador de cada equipe pelo local de partida?",
  ui_story_5031_50310801_134_dialog_content = "Quero contar a todos vocês um pequeno segredo...",
  ui_story_5031_50310801_135_dialog_content = "Nosso primeiro surfista hoje vai ser... eu!",
  ui_story_5031_50310801_136_dialog_content = "Sim!",
  ui_story_5031_50310801_137_dialog_content = "Você pode surfar com certeza, Rainbow!",
  ui_story_5031_50310801_138_dialog_content = "Rainbow está realmente ganhando a multidão.",
  ui_story_5031_50310801_139_dialog_content = "Ela deve ser incrível nisso. Ela tem muita confiança.",
  ui_story_5031_50310801_140_dialog_content = "Ah bem. De qualquer forma, as regras dizem que apenas os dois melhores pontuadores vão contar, então pode ser bom para nós.",
  ui_story_5031_50310801_141_dialog_content = "É por isso que a ordem em que você entra é realmente importante.",
  ui_story_5031_50310801_142_dialog_content = "Então, se eles têm Rainbow começando para sua equipe, então devemos...",
  ui_story_5031_50310801_143_dialog_content = "Hmph! Não é óbvio que eu deveria ir primeiro? Eu sou o melhor!",
  ui_story_5031_50310801_144_dialog_content = "... Tu? Ao melhor?",
  ui_story_5031_50310801_145_dialog_content = "O que você está implicando?",
  ui_story_5031_50310801_146_dialog_content = "Não se esqueça que eu sou o único que conseguiu seguir as instruções de Carleen naquele momento!",
  ui_story_5031_50310801_147_dialog_content = "É uma coisa certa! Eu vou ganhar facilmente.",
  ui_story_5031_50310801_148_dialog_content = "Você pode ficar aqui e esperar pelo meu retorno triunfante, PlayerName!",
  ui_story_5031_50310801_149_dialog_content = "... Será realmente tão fácil?",
  ui_story_5031_50310801_150_dialog_content = "Algo sobre sua arrogância está me deixando ainda mais preocupado.",
  ui_story_5031_50310801_151_dialog_content = "Ahem, eu vou precisar ser apresentadora, já que Rainbow se envolveu.",
  ui_story_5031_50310801_152_dialog_content = "Uh... Devo dizer que todos vocês parecem muito pequenos deste ponto de vista, subindo e descendo nas ondas...",
  ui_story_5031_50310801_153_dialog_content = "Por menor que você seja, você domina as leis naturais do movimento, permitindo que você surfe.",
  ui_story_5031_50310801_154_dialog_content = "É nada menos que uma forma de arte de suprema inteligência e senso estético...",
  ui_story_5031_50310801_155_dialog_content = "Adeus, todos! Monte os ritmos dessas ondas e conquiste...",
  ui_story_5031_50310801_156_dialog_content = "... O suficiente! Vamos começar! Começar!",
  ui_story_5031_50310801_157_dialog_content = "Nós estamos esperando!",
  ui_story_5031_50310801_158_dialog_content = "Tsk. Eu simplesmente não consigo entender tolos medíocres.",
  ui_story_5031_50310801_159_dialog_content = "Já que vocês são todos tão impacientes, então vamos começar. Vai!",
  ui_story_5031_50310801_160_dialog_content = "...",
  ui_story_5031_50310801_161_dialog_content = "Huh? É isso?",
  ui_story_5031_50310801_162_dialog_content = "Queremos outro emcee!",
  ui_story_5031_50310801_163_dialog_content = "Haha! Pobre Jeno.",
  ui_story_5031_50310801_164_dialog_content = "Nesse caso, é melhor eu ir!",
  ui_story_5031_50310801_165_dialog_content = "Vamos, Ciel! Começou! Rápido!",
  ui_story_5031_50310801_166_dialog_content = "Já começou? Não havia algum tipo de sinal?",
  ui_story_5031_50310801_167_dialog_content = "O-Oh, querida. \"Atualização do status do mecanismo de perna - Modo Spray\"!",
  ui_story_5031_50310801_168_dialog_content = "Eles estão surfando em um mech?",
  ui_story_5031_50310801_169_dialog_content = "As ondas simplesmente varreram aqueles competidores para o mar!",
  ui_story_5031_50310801_170_dialog_content = "O que devemos fazer sobre isso?",
  ui_story_5031_50310801_171_dialog_content = "Está tudo bem. Fia está bem longe agora... e parece estar indo bem.",
  ui_story_5031_50310801_172_dialog_content = "Oooh! Vai embora, Rainbow!!",
  ui_story_5031_50310801_173_dialog_content = "Uau! Ela se transforma como um profissional!",
  ui_story_5031_50310801_174_dialog_content = "Aquela garota no mech também não é tão ruim. Ela é rápida!",
  ui_story_5031_50310801_175_dialog_content = "Mas não parece tão bom em uma prancha quanto o Rainbow.",
  ui_story_5031_50310801_176_dialog_content = "Hmph. O concurso está longe de ser tão simples quanto você imagina.",
  ui_story_5031_50310801_177_dialog_content = "Rugido! Criaturas amaldiçoadas das profundezas!",
  ui_story_5031_50310801_178_dialog_content = "Grrr!",
  ui_story_5031_50310801_179_dialog_content = "Eles estão aqui!",
  ui_story_5031_50310801_180_dialog_content = "Ei! Rainbow está prestes a se transformar novamente!",
  ui_story_5031_50310801_181_dialog_content = "Ooh. Cuidado, Rainbow!",
  ui_story_5031_50310801_182_dialog_content = "Huh? Há Eclipses saindo das ondas!",
  ui_story_5031_50310801_183_dialog_content = "Isso vai ser um pouco difícil...",
  ui_story_5031_50310801_184_dialog_content = "R-Rainbow?",
  ui_story_5031_50310801_185_dialog_content = "Aaaah!",
  ui_story_5031_50310801_186_dialog_content = "Já aguentei vocês por muito tempo, miseráveis Eclipsitas!",
  ui_story_5031_50310801_187_dialog_content = "<size=45>Morrer!</size>",
  ui_story_5031_50310801_188_dialog_content = "Você não parece muito feliz. Você está pensando naquela garota Ranka?",
  ui_story_5031_50310802_X1_dialog_content = "Você não parece muito feliz. Você está pensando naquela garota Ranka?",
  ui_story_5031_50310802_1_dialog_content = "Ah, sim...",
  ui_story_5031_50310802_2_dialog_content = "Deixe-me pegar algumas frutas. Você precisa se manter hidratado.",
  ui_story_5031_50310802_3_dialog_content = "Obrigado, Jeno.",
  ui_story_5031_50310802_4_dialog_content = "Esse remédio que você acabou de dar a ela é a \"solução\" que você estava falando?",
  ui_story_5031_50310802_5_dialog_content = "De jeito nenhum. É algo que inventei depois de estudar os textos antigos. É apenas para alívio temporário da dor.",
  ui_story_5031_50310802_6_dialog_content = "E mesmo assim você inventou?",
  ui_story_5031_50310802_7_dialog_content = "Era uma vez, você queria ser um chef. Mas você se tornou um farmacêutico?",
  ui_story_5031_50310802_8_dialog_content = "Ei! Harbour City não precisa de mais chefs, mas precisamos de alguém que entenda muito bem a Síndrome de Modali.",
  ui_story_5031_50310802_9_dialog_content = "Então, em outras palavras, você sacrificou seu sonho para fazer algo grande com sua vida?",
  ui_story_5031_50310802_10_dialog_content = "Eu nunca quis me tornar grande. Eu só não quero ficar parado enquanto os outros estão com dor.",
  ui_story_5031_50310802_11_dialog_content = "E eu não sou muito de um farmacêutico. Acabei de copiar o que li nos pergaminhos antigos. Foi fácil.",
  ui_story_5031_50310802_12_dialog_content = "Me sentirei livre para perseguir meus sonhos assim que descobrir a Síndrome de Modali.",
  ui_story_5031_50310802_13_dialog_content = "E o que você faria então?",
  ui_story_5031_50310802_14_dialog_content = "Eu poderia tentar abrir uma cadeia de salões de arte de alta classe com restaurantes anexos.",
  ui_story_5031_50310802_15_dialog_content = "Você ainda se lembra daquela promessa de tantos anos atrás?",
  ui_story_5031_50310802_16_dialog_content = "Faz tanto tempo... Achei que você tinha esquecido.",
  ui_story_5031_50310802_17_dialog_content = "Tenho uma excelente memória. Lembro-me até de pequenas coisas, como aquele retrato que você deveria pintar para mim.",
  ui_story_5031_50310802_18_dialog_content = "Mantive um espaço vazio na galeria de arte de Harbour City.",
  ui_story_5031_50310802_19_dialog_content = "...",
  ui_story_5031_50310802_20_dialog_content = "Então, há algo que eu possa fazer para ajudar?",
  ui_story_5031_50310802_21_dialog_content = "Como assim?",
  ui_story_5031_50310802_22_dialog_content = "Existe algo que eu possa fazer para ajudá-lo com esta \"Síndrome de Modali\"?",
  ui_story_5031_50310802_23_dialog_content = "...",
  ui_story_5031_50310802_24_dialog_content = "Na verdade...",
  ui_story_5031_50310802_25_dialog_content = "Uau! Rainbow é incrível!",
  ui_story_5031_50310802_26_dialog_content = "Uma mistura perfeita de poder e beleza!",
  ui_story_5031_50310802_27_dialog_content = "... O que você estava dizendo?",
  ui_story_5031_50310802_28_dialog_content = "Está tudo bem. Vamos aproveitar o evento primeiro.",
  ui_story_5031_50310802_29_dialog_content = "Eu deveria tentar ser um bom juiz. Não gostaria de deixar os concorrentes para baixo.",
  ui_story_5031_50310802_30_dialog_content = "Rainbow é muito forte - e assustador também...",
  ui_story_5031_50310802_31_dialog_content = "V-você está certo.",
  ui_story_5031_50310802_32_dialog_content = "Não diga isso sobre Rainbow, broto de feijão!",
  ui_story_5031_50310802_33_dialog_content = "Sim. Mesmo que Merylt se importe com você!",
  ui_story_5031_50310802_34_dialog_content = "Oh, sinto muito. Eu quis dizer isso no bom sentido!",
  ui_story_5031_50310802_35_dialog_content = "Estou tão impressionado com sua exibição destemida de espírito...",
  ui_story_5031_50310802_36_dialog_content = "Não vá causar problemas, Subli.",
  ui_story_5031_50310802_37_dialog_content = "Rainbow realmente odeia Eclipsites. É por isso que ela está fazendo isso.",
  ui_story_5031_50310802_38_dialog_content = "Ela odeia Eclipses?",
  ui_story_5031_50310802_39_dialog_content = "Sim...",
  ui_story_5031_50310802_40_dialog_content = "A vila de Rainbow foi destruída pelos Eclipsites.",
  ui_story_5031_50310802_41_dialog_content = "Foi assim que ela perdeu seus amigos e familiares.",
  ui_story_5031_50310802_42_dialog_content = "É por isso que Rainbow fica brava sempre que vê Eclipses – até mesmo ilusões.",
  ui_story_5031_50310802_43_dialog_content = "Ela é uma pessoa muito doce e gentil. É apenas com Eclipsites.",
  ui_story_5031_50310802_44_dialog_content = "Sim. Eu amo Rainbow!",
  ui_story_5031_50310802_45_dialog_content = "Eu também. Eu gosto muito mais dela do que do nosso mestre de cerimônias, ele sempre parece feroz.",
  ui_story_5031_50310802_46_dialog_content = "Eu acho... nosso mestre de cerimônias é legal...",
  ui_story_5031_50310802_47_dialog_content = "Só você diria algo assim!",
  ui_story_5031_50310802_48_dialog_content = "Entao e por isso...",
  ui_story_5031_50310802_49_dialog_content = "Olhando para a atitude ensolarada de Rainbow, é difícil acreditar que ela tenha um passado tão trágico.",
  ui_story_5031_50310802_50_dialog_content = "Às vezes, as garotas mais felizes e doces são aquelas com passados mais dolorosos e trágicos.",
  ui_story_5031_50310802_51_dialog_content = "Eu a respeito.",
  ui_story_5031_50310802_52_dialog_content = "Certo. Não posso deixar de sentir que tenho sorte de não ser o primeiro a sair por aí...",
  ui_story_5031_50310802_53_dialog_content = "Ei... O que está acontecendo com Fia?",
  ui_story_5031_50310802_54_dialog_content = "Pare de vir à minha prancha de todos os lugares ao mesmo tempo!",
  ui_story_5031_50310802_55_dialog_content = "Escolha uma direção!",
  ui_story_5031_50310802_56_dialog_content = "Caramba. Caminho errado! Não está lá! Uau!",
  ui_story_5031_50310802_57_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5031_50310802_58_dialog_content = "Haha! Como aquela garota conseguiu um giro de 360 graus?",
  ui_story_5031_50310802_59_dialog_content = "Agora ela está dando um mergulho. Ela não vai ganhar muitos pontos por estilo.",
  ui_story_5031_50310802_60_dialog_content = "*Cof*",
  ui_story_5031_50310802_61_dialog_content = "Peixe estúpido!",
  ui_story_5031_50310802_62_dialog_content = "PlayerName vai rir de mim com certeza, boo-hoo...",
  ui_story_5031_50310802_63_dialog_content = "Fia deve estar se preocupando comigo rindo dela agora.",
  ui_story_5031_50310802_64_dialog_content = "Mas... ah!",
  ui_story_5031_50310802_65_dialog_content = "Devo dizer que é muito engraçado, hahaha!",
  ui_story_5031_50310802_66_dialog_content = "Não ria tanto, PlayerName.",
  ui_story_5031_50310802_67_dialog_content = "É minha culpa. Não esperava que Fia tivesse problemas de coordenação com os peixes.",
  ui_story_5031_50310802_68_dialog_content = "Era um pouco irreal esperar que ela pudesse ganhar com a comunicação dos peixes.",
  ui_story_5031_50310802_69_dialog_content = "Não não. Fia disse que seria moleza!",
  ui_story_5031_50310802_70_dialog_content = "Você não pode continuar se culpando por tudo, Carleen. É apenas um jogo de qualquer maneira. Quem se importa?",
  ui_story_5031_50310802_71_dialog_content = "... Sim.",
  ui_story_5031_50310802_72_dialog_content = "Deixe-me fazer alguns comentários — aposto que você pode dizer o que está acontecendo se ainda tiver seus preciosos olhos.",
  ui_story_5031_50310802_73_dialog_content = "O surfista mais destacado no concurso agora é o nosso próprio Rainbow of the Circus, assim como Ciel of Illumina.",
  ui_story_5031_50310802_74_dialog_content = "Os dois estão quase iguais para Eclipsites destruídos e muito à frente quando o assunto é estilo.",
  ui_story_5031_50310802_75_dialog_content = "Mas dada a resposta do nosso público, Rainbow parece ter uma técnica ligeiramente superior.",
  ui_story_5031_50310802_76_dialog_content = "Então eu desejo ao resto de vocês, dezoito competidores, completamente normais como vocês são, boa sorte.",
  ui_story_5031_50310802_77_dialog_content = "... E uma luta valente contra as ondas e as vicissitudes da vida.",
  ui_story_5031_50310802_78_dialog_content = "...",
  ui_story_5031_50310802_79_dialog_content = "Apenas espere, Jeno!",
  ui_story_5031_50310802_80_dialog_content = "Para baixo no mar com você!",
  ui_story_5031_50310802_81_dialog_content = "Grrr!",
  ui_story_5031_50310802_82_dialog_content = "Ufa, mesmo que você seja uma ilusão, não posso evitar!",
  ui_story_5031_50310802_83_dialog_content = "Eu me sinto muito melhor depois de destruir todos vocês!",
  ui_story_5031_50310802_84_dialog_content = "Você é tão... poderoso...",
  ui_story_5031_50310802_85_dialog_content = "Huh? De volta para você, garota!",
  ui_story_5031_50310802_86_dialog_content = "Você é um bom par para mim que cresci à beira-mar!",
  ui_story_5031_50310802_87_dialog_content = "Na verdade, acabei de ganhar as marcas matando Eclipsites.",
  ui_story_5031_50310802_88_dialog_content = "Eu não pontuei muito em termos de minhas habilidades de surf.",
  ui_story_5031_50310802_89_dialog_content = "Acabei de aproveitar uma brecha nas regras...",
  ui_story_5031_50310802_90_dialog_content = "Você é estranho, Ciel.",
  ui_story_5031_50310802_91_dialog_content = "E-Estranho?",
  ui_story_5031_50310802_92_dialog_content = "Sim. Estou te dando elogios, mas você não só não os aceita, como também parece chateado.",
  ui_story_5031_50310802_93_dialog_content = "O que há de errado em pontuar matando Eclipsites? Como isso é abusar das regras?",
  ui_story_5031_50310802_94_dialog_content = "...",
  ui_story_5031_50310802_95_dialog_content = "Ciel, você é bom. Você deveria ter mais confiança em si mesmo.",
  ui_story_5031_50310802_96_dialog_content = "Continuar a duvidar de si mesmo é uma maneira segura de estragar as coisas.",
  ui_story_5031_50310802_97_dialog_content = "Eu...",
  ui_story_5031_50310802_98_dialog_content = "Graagh!",
  ui_story_5031_50310802_99_dialog_content = "Mais Eclipses!? Você não vai escapar!",
  ui_story_5031_50310802_100_dialog_content = "Estou bem?",
  ui_story_5031_50310802_101_dialog_content = "Ei... Ei.",
  ui_story_5031_50310802_102_dialog_content = "Bem, de jeito nenhum eu vou decepcionar Rainbow, então!",
  ui_story_5031_50310802_103_dialog_content = "\"Atualização do status do mecanismo de braço - Tipo II\"!",
  ui_story_5031_50310802_104_dialog_content = "\"Aumentar a liberação de energia em 60%\"!",
  ui_story_5031_50310802_105_dialog_content = "<color=#e8d9bb>Rumores—</color>",
  ui_story_5031_50310802_106_dialog_content = "C-Ciel!?",
  ui_story_5031_50310802_107_dialog_content = "Ela aumentou a produção de energia novamente?",
  ui_story_5031_50310802_108_dialog_content = "Mas Styx é...",
  ui_story_5031_50310802_109_dialog_content = "Ei! Aquela garota mecha liberou uma energia tão poderosa no mar!",
  ui_story_5031_50310802_110_dialog_content = "O navio está balançando para frente e para trás! Nós vamos afundar...",
  ui_story_5031_50310802_111_dialog_content = "Ela voou para o céu! Ela está tentando ganhar mais pontos com um salto?",
  ui_story_5031_50310802_112_dialog_content = "Não, espere... Isso é...",
  ui_story_5031_50310802_113_dialog_content = "Eclipses! Ela derrubou os Eclipsitas do mar!",
  ui_story_5031_50310802_114_dialog_content = "Ah, isso...",
  ui_story_5031_50310802_115_dialog_content = "Um poder tão incrível!",
  ui_story_5031_50310802_116_dialog_content = "Como não sou tão habilidoso, terei que contar com os 50% restantes.",
  ui_story_5031_50310802_117_dialog_content = "Styx, ataque de varredura!",
  ui_story_5031_50310802_118_dialog_content = "Mas o mecha tem uma ótima saída e pode lançar ataques de área eficazes.",
  ui_story_5031_50310802_119_dialog_content = "Certo, seu mecha é mais pesado, então não pode realizar atos ágeis.",
  ui_story_5031_50310802_120_dialog_content = "Ciel aproveitou isso para matar instantaneamente um grande número de Eclipsites, virando a mesa ganhando muitos pontos!",
  ui_story_5031_50310802_121_dialog_content = "Tentando sair de uma situação desesperadora, apesar de suas desvantagens. É inspirador.",
  ui_story_5031_50310802_122_dialog_content = "Então, o laird lhe daria uma pontuação?",
  ui_story_5031_50310802_123_dialog_content = "Claro, mestre de cerimônias.",
  ui_story_5031_50310802_124_dialog_content = "E-isso é...",
  ui_story_5031_50310802_125_dialog_content = "<color=#e8d9bb>Clique... Claque...</color>",
  ui_story_5031_50310802_126_dialog_content = "Hã?",
  ui_story_5031_50310802_127_dialog_content = "Oh não! Styx não pode manter uma produção de energia tão alta...",
  ui_story_5031_50310802_128_dialog_content = "Ahhhh! Eu estou caindo!",
  ui_story_5031_50310802_129_dialog_content = "Ciel!",
  ui_story_5031_50310802_130_dialog_content = "Rá!",
  ui_story_5031_50310802_131_dialog_content = "Huh? Rainbow?",
  ui_story_5031_50310802_132_dialog_content = "Hum...",
  ui_story_5031_50310802_133_dialog_content = "Já pode abrir os olhos. Eu entendi você.",
  ui_story_5031_50310802_134_dialog_content = "O quê?",
  ui_story_5031_50310802_135_dialog_content = "R-Rainbow?",
  ui_story_5031_50310802_136_dialog_content = "Isso foi imprudente. Mudar para uma saída de energia tão alta quando seu mecha não foi calibrado para isso.",
  ui_story_5031_50310802_137_dialog_content = "Eu sinto muito.",
  ui_story_5031_50310802_138_dialog_content = "Styx experimentou uma explosão e o dano não foi totalmente reparado.",
  ui_story_5031_50310802_139_dialog_content = "Desculpe sobrecarregar você...",
  ui_story_5031_50310802_140_dialog_content = "É assim mesmo? Que pena!",
  ui_story_5031_50310802_141_dialog_content = "Estou tão ansioso para suas capacidades, uma vez que está totalmente reparado!",
  ui_story_5031_50310802_142_dialog_content = "...",
  ui_story_5031_50310802_143_dialog_content = "Uhm... Rainbow?",
  ui_story_5031_50310802_144_dialog_content = "Hum? O que é isso?",
  ui_story_5031_50310802_145_dialog_content = "Por que você me salvou? Se eu cair no mar, vou perder muitos pontos.",
  ui_story_5031_50310802_146_dialog_content = "Huh? Nós iremos...",
  ui_story_5031_50310802_147_dialog_content = "Provavelmente é por causa disso, comparado a 5 milhões de Nightium...",
  ui_story_5031_50310802_148_dialog_content = "Estou mais interessado em você.",
  ui_story_5031_50310901_1_dialog_content = "Acabou a primeira rodada! Agora, os competidores da segunda rodada iriam para seus pontos de partida designados?",
  ui_story_5031_50310901_2_dialog_content = "Enquanto isso, as pontuações finais da primeira rodada serão calculadas.",
  ui_story_5031_50310901_3_dialog_content = "Está tudo bem, Fia. Ainda temos nossa chance.",
  ui_story_5031_50310901_4_dialog_content = "Sim. Não se sinta mal. Nunca esperávamos que você obtivesse uma pontuação alta.",
  ui_story_5031_50310901_5_dialog_content = "Aaaah!",
  ui_story_5031_50310901_6_dialog_content = "Stupid PlayerName!",
  ui_story_5031_50310901_7_dialog_content = "Huh? O que eu fiz?",
  ui_story_5031_50310901_8_dialog_content = "Eu estava tentando te confortar.",
  ui_story_5031_50310901_9_dialog_content = "Apenas pare com isso primeiro, PlayerName.",
  ui_story_5031_50310901_10_dialog_content = "... Eu acredito que há um mal-entendido.",
  ui_story_5031_50310901_11_dialog_content = "Preparem-se para a segunda rodada, pessoal.",
  ui_story_5031_50310901_12_dialog_content = "Ouvi Rainbow dizer que enviarão Merylt em seguida.",
  ui_story_5031_50310901_13_dialog_content = "Hum? Tudo bem, Fia?",
  ui_story_5031_50310901_14_dialog_content = "*Soluço* Carleen! PlayerName, ele...",
  ui_story_5031_50310901_15_dialog_content = "Espere um minuto! Eu não fiz nada!",
  ui_story_5031_50310901_16_dialog_content = "Fia, esqueça ele. Vamos nos concentrar na próxima rodada.",
  ui_story_5031_50310901_17_dialog_content = "Você quer o prêmio mon⁠—quero dizer, o maiô... E nós temos um Cloudwhale para salvar, certo?",
  ui_story_5031_50310901_18_dialog_content = "Boo-hoo, sim...",
  ui_story_5031_50310901_19_dialog_content = "Então seque suas lágrimas. Vamos discutir nosso arranjo para a próxima rodada.",
  ui_story_5031_50310901_20_dialog_content = "Então... Proponho que PlayerName seja o próximo!",
  ui_story_5031_50310901_21_dialog_content = "Hã?!",
  ui_story_5031_50310901_22_dialog_content = "Hmph! Você estava rindo quando eu caí na água, não estava?",
  ui_story_5031_50310901_23_dialog_content = "Agora é minha vez de rir de você!",
  ui_story_5031_50310901_24_dialog_content = "Como você sabia que eu estava rindo? - Não, espere. Isso não faz sentido!",
  ui_story_5031_50310901_25_dialog_content = "Achei que ganhar o jogo era mais importante!",
  ui_story_5031_50310901_26_dialog_content = "Só precisamos de duas pontuações vencedoras, então nem preciso continuar, certo?",
  ui_story_5031_50310901_27_dialog_content = "Você esqueceu, PlayerName? Você e Fia são contados como um.",
  ui_story_5031_50310901_28_dialog_content = "A pontuação de você e Fia está resumida.",
  ui_story_5031_50310901_29_dialog_content = "Certo... Isso aconteceu...",
  ui_story_5031_50310901_30_dialog_content = "Nós não sabemos quem Vice e eu vou enfrentar quando for a nossa vez.",
  ui_story_5031_50310901_31_dialog_content = "Então, só por segurança, é melhor que você participe.",
  ui_story_5031_50310901_32_dialog_content = "Então, na verdade, faz sentido enviar PlayerName em seguida.",
  ui_story_5031_50310901_33_dialog_content = "Verdadeiro. Merylt deve ser o mais suave dos trigêmeos.",
  ui_story_5031_50310901_34_dialog_content = "E eu não me sinto oficial Gronru é bom no surf",
  ui_story_5031_50310901_35_dialog_content = "Então, se for o caso...",
  ui_story_5031_50310901_36_dialog_content = "Se for o caso...",
  ui_story_5031_50310901_37_dialog_content = "Eu sei, eu sei... Eu vou. Apenas pare de me encarar.",
  ui_story_5031_50310901_38_dialog_content = "Heheh! Boa sorte, PlayerName.",
  ui_story_5031_50310901_39_dialog_content = "Sem pressão, ok? Apenas lembre-se do que lhe ensinamos.",
  ui_story_5031_50310901_40_dialog_content = "Está tudo bem, mesmo que você não possa fazê-lo.",
  ui_story_5031_50310901_41_dialog_content = "Consegui, consegui.",
  ui_story_5031_50310901_42_dialog_content = "Hmph! É melhor você não ser o elo mais fraco, PlayerName!",
  ui_story_5031_50310901_43_dialog_content = "Você não ganhou uma boa pontuação!",
  ui_story_5031_50310901_44_dialog_content = "Enquanto anunciamos a pontuação, todos os competidores chegarão às suas posições?",
  ui_story_5031_50310901_45_dialog_content = "O vencedor da última rodada é... Rainbow!",
  ui_story_5031_50310901_46_dialog_content = "Isso não é surpresa. Ela é nosso ás.",
  ui_story_5031_50310901_47_dialog_content = "Rainbow-!",
  ui_story_5031_50310901_48_dialog_content = "No entanto, há algo que vai derrubar suas meias!",
  ui_story_5031_50310901_49_dialog_content = "Temos outro concorrente com a mesma pontuação na mesma classificação, que é... Ciel!",
  ui_story_5031_50310901_50_dialog_content = "Essa é a garota mecha!",
  ui_story_5031_50310901_51_dialog_content = "Incrível! Ela alcançou a pontuação de Rainbow!?",
  ui_story_5031_50310901_52_dialog_content = "Que incrível, Ciel!",
  ui_story_5031_50310901_53_dialog_content = "Obrigado, oficial Gronru!",
  ui_story_5031_50310901_54_dialog_content = "Policial Gronru? Por quê você está aqui!?",
  ui_story_5031_50310901_55_dialog_content = "Você deveria estar na sua posição!",
  ui_story_5031_50310901_56_dialog_content = "Bem, é porque...",
  ui_story_5031_50310901_57_dialog_content = "Eu sei que você quer colocar Merylt, PlayerName e eu um contra o outro...",
  ui_story_5031_50310901_58_dialog_content = "Esperando tirar vantagem da situação, não é?",
  ui_story_5031_50310901_59_dialog_content = "...",
  ui_story_5031_50310901_60_dialog_content = "Hum, bem...",
  ui_story_5031_50310901_61_dialog_content = "Bem, adivinhe? Eu não vou tornar as coisas tão fáceis para você!",
  ui_story_5031_50310901_62_dialog_content = "Hmm... Não fique nervoso.",
  ui_story_5031_50310901_63_dialog_content = "Há menos pessoas nesta rodada. Tudo que eu preciso fazer é me segurar.",
  ui_story_5031_50310901_64_dialog_content = "PlayerName, uh...",
  ui_story_5031_50310901_65_dialog_content = "O que aconteceu, Merylt?",
  ui_story_5031_50310901_66_dialog_content = "Uhm, sua placa... Ela não está presa a você.",
  ui_story_5031_50310901_67_dialog_content = "É muito perigoso...",
  ui_story_5031_50310901_68_dialog_content = "Oh! Eu esqueci completamente disso!",
  ui_story_5031_50310901_69_dialog_content = "Muito obrigado, Merylt!",
  ui_story_5031_50310901_70_dialog_content = "Hum...!",
  ui_story_5031_50310901_71_dialog_content = "Oh, ela acabou de mergulhar na água!",
  ui_story_5031_50310901_72_dialog_content = "Eu disse algo errado de novo?",
  ui_story_5031_50310901_73_dialog_content = "Bem, é hora.",
  ui_story_5031_50310901_74_dialog_content = "Vamos começar a segunda rodada.",
  ui_story_5031_50310901_75_dialog_content = "Hahahaha... Assim mesmo, de novo?",
  ui_story_5031_50310901_76_dialog_content = "Esse é o estilo do diretor de circo?",
  ui_story_5031_50310901_77_dialog_content = "Oh, não há mecha nesta rodada. Que decepcionante.",
  ui_story_5031_50310901_78_dialog_content = "Huh? Olhar! Essa é a menina dos trigêmeos do circo...",
  ui_story_5031_50310901_79_dialog_content = "Seus movimentos são ainda mais graciosos que os de Rainbow!",
  ui_story_5031_50310901_80_dialog_content = "É claro! Merylt é um dos membros do circo com o melhor equilíbrio e controle!",
  ui_story_5031_50310901_81_dialog_content = "Ela dominou o trapézio voador e os anéis de ginástica. O surf deve ser um pedaço de bolo para ela!",
  ui_story_5031_50310901_82_dialog_content = "Você realmente sabe tudo o que há para saber sobre os membros do circo.",
  ui_story_5031_50310901_83_dialog_content = "Bem, eles não são apenas meus funcionários.",
  ui_story_5031_50310901_84_dialog_content = "Eles são minha família.",
  ui_story_5031_50310901_85_dialog_content = "...",
  ui_story_5031_50310901_86_dialog_content = "Isso realmente me lembra o velho você.",
  ui_story_5031_50310901_87_dialog_content = "É assim mesmo? O pirralho inútil que sempre dependeu de sua família e você?",
  ui_story_5031_50310901_88_dialog_content = "Não. Aquele garotinho inocente que choraria por um passarinho que caiu do ninho.",
  ui_story_5031_50310901_89_dialog_content = "Você até quebrou o braço ao tentar colocá-lo de volta e usou um gesso por seis meses.",
  ui_story_5031_50310901_90_dialog_content = "E você ainda está tentando cuidar de todos ao seu redor.",
  ui_story_5031_50310901_91_dialog_content = "Ah, chega de todas essas coisas embaraçosas sobre mim.",
  ui_story_5031_50310901_92_dialog_content = "Apenas aproveite o jogo.",
  ui_story_5031_50310901_93_dialog_content = "Ha... Tudo bem, tudo bem.",
  ui_story_5031_50310902_1_dialog_content = "Como esperado, o competidor com maior pontuação ainda é um membro do nosso circo...",
  ui_story_5031_50310902_2_dialog_content = "Merylt!",
  ui_story_5031_50310902_3_dialog_content = "Ohhhhhh!",
  ui_story_5031_50310902_4_dialog_content = "Este resultado brilhante é o fruto de seu trabalho árduo sem fim e suor sob as estrelas.",
  ui_story_5031_50310902_5_dialog_content = "Espero que o sucesso dela inspire e desperte algo em todos vocês preguiçosos!",
  ui_story_5031_50310902_X5_dialog_content = "...",
  ui_story_5031_50310902_X6_dialog_content = "Hmph, tão envergonhado que você está sem palavras? Tudo bem, nem todo mundo quer fazer algo com sua vida.",
  ui_story_5031_50310902_X7_dialog_content = "Concorrentes da terceira rodada, preparem-se!",
  ui_story_5031_50310902_X8_dialog_content = "Concorrentes da terceira rodada, por favor, preparem-se.",
  ui_story_5031_50310902_6_dialog_content = "Concorrentes da terceira rodada, preparem-se!",
  ui_story_5031_50310902_7_dialog_content = "Huh? PlayerName, você ganha zero pontos? Sem chance.",
  ui_story_5031_50310902_8_dialog_content = "De certa forma, isso está além do que uma pessoa normal pode fazer.",
  ui_story_5031_50310902_9_dialog_content = "Sem Carleen e Vice, realmente não sabemos o que fazer com o Cloudwhale.",
  ui_story_5031_50310902_10_dialog_content = "*Soluço* Já chega...",
  ui_story_5031_50310902_11_dialog_content = "Como celestita, sinto muito.",
  ui_story_5031_50310902_12_dialog_content = "Oh, pare de culpar PlayerName, Fia.",
  ui_story_5031_50310902_13_dialog_content = "Não é realista pensar que um novato pode aprender a surfar em um dia.",
  ui_story_5031_50310902_14_dialog_content = "Nós vamos apanhar. Não se preocupe.",
  ui_story_5031_50310902_15_dialog_content = "Você é realmente confiável, Carleen, Vice!",
  ui_story_5031_50310902_16_dialog_content = "Suspire, tente mais e faça o seu melhor, PlayerName.",
  ui_story_5031_50310902_17_dialog_content = "Não fique chateado. Vou parar de te provocar. Quando eu dominar como surfar, Carleen e eu farei o nosso melhor para ensiná-lo!",
  ui_story_5031_50310902_18_dialog_content = "Ah. Acho que deveria ser grato.",
  ui_story_5031_50310902_19_dialog_content = "É melhor você ser!",
  ui_story_5031_50310902_20_dialog_content = "U-Um, PlayerName...",
  ui_story_5031_50310902_21_dialog_content = "Huh? Merylt? O que posso fazer para você?",
  ui_story_5031_50310902_22_dialog_content = "Hum...",
  ui_story_5031_50310902_23_dialog_content = "Ah, deixe-me dizer!",
  ui_story_5031_50310902_24_dialog_content = "PlayerName, Merylt quer se desculpar por quase te machucar!",
  ui_story_5031_50310902_25_dialog_content = "Oh aquilo! Não se preocupe, Merylt. Você não me machucou.",
  ui_story_5031_50310902_26_dialog_content = "Eu só respirei um pouco de água porque eu mesma fiquei com medo.",
  ui_story_5031_50310902_27_dialog_content = "Em... Hum...",
  ui_story_5031_50310902_28_dialog_content = "Você é tão gentil, PlayerName! Ao contrário do chefe!",
  ui_story_5031_50310902_29_dialog_content = "Tanta gentileza, não é à toa que Merylt se apaixonou por você – Uhmm!?",
  ui_story_5031_50310902_30_dialog_content = "F-Frimet!",
  ui_story_5031_50310902_31_dialog_content = "Você deve ir se preparar, n-agora!",
  ui_story_5031_50310902_32_dialog_content = "Milímetros! Mmm!",
  ui_story_5031_50310902_33_dialog_content = "Ah, espere por mim!",
  ui_story_5031_50310902_34_dialog_content = "Ah?",
  ui_story_5031_50310902_35_dialog_content = "Você é bastante popular, PlayerName.",
  ui_story_5031_50310902_36_dialog_content = "...",
  ui_story_5031_50310902_37_dialog_content = "Huh? O que você está falando?",
  ui_story_5031_50310902_38_dialog_content = "Nada!",
  ui_story_5031_50310902_39_dialog_content = "É melhor eu ir me preparar. Vai começar a qualquer momento.",
  ui_story_5031_50310902_40_dialog_content = "Sim vamos lá.",
  ui_story_5031_50310902_41_dialog_content = "Agindo todo misterioso...",
  ui_story_5031_50310902_42_dialog_content = "Vamos para a praia então, Fia—",
  ui_story_5031_50310902_43_dialog_content = "Huh? Fia?",
  ui_story_5031_50310902_44_dialog_content = "Sério? O que está acontecendo com todos eles?",
  ui_story_5031_50310902_45_dialog_content = "Agora que estamos na terceira rodada, todos já devem conhecer as regras. Vamos começar, então.",
  ui_story_5031_50310902_46_dialog_content = "Torrente Rápida!",
  ui_story_5031_50310902_47_dialog_content = "Isso é uma ofensa poderosa.",
  ui_story_5031_50310902_48_dialog_content = "Parece que eu preciso levar isso a sério agora. Hora de mostrar meu treinamento especial!",
  ui_story_5031_50310902_49_dialog_content = "*Tosse*",
  ui_story_5031_50310902_50_dialog_content = "Elvis! Onde está o seu remédio?",
  ui_story_5031_50310902_51_dialog_content = "Dentro... o bolso interno do meu casaco.",
  ui_story_5031_50310902_52_dialog_content = "Não se esqueça de desligar o alto-falante... tosse...",
  ui_story_5031_50310902_53_dialog_content = "Não se preocupe. Eu desliguei.",
  ui_story_5031_50310902_54_dialog_content = "Tem certeza que está no seu bolso? Eu não posso encontrá-lo.",
  ui_story_5031_50310902_55_dialog_content = "Tosse, tosse...",
  ui_story_5031_50310902_56_dialog_content = "Desculpe... Você tem um lenço?",
  ui_story_5031_50310902_57_dialog_content = "Claro. Um segundo.",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>Barulho-</color>",
  ui_story_5031_50310902_59_dialog_content = "Tsk, muitas coisas.",
  ui_story_5031_50310902_60_dialog_content = "Você pode apenas ser bom em um momento como este?",
  ui_story_5031_50310902_61_dialog_content = "...",
  ui_story_5031_50310902_62_dialog_content = "Aqui.",
  ui_story_5031_50310902_63_dialog_content = "Obrigado... Tosse, tosse...",
  ui_story_5031_50310902_64_dialog_content = "Esta é uma rodada emocionante! Bastante briga!",
  ui_story_5031_50310902_65_dialog_content = "Sim! Mais um Eclipse caído!",
  ui_story_5031_50310902_66_dialog_content = "Essa menina com um arco é incrível!",
  ui_story_5031_50310902_67_dialog_content = "...",
  ui_story_5031_50310902_68_dialog_content = "Desculpe, você pode me levar para algum lugar com menos pessoas para que eu possa descansar um pouco?",
  ui_story_5031_50310902_69_dialog_content = "De nada.",
  ui_story_5031_50310902_70_dialog_content = "Ei, você, aí!",
  ui_story_5031_50310902_71_dialog_content = "Sim você.",
  ui_story_5031_50310902_72_dialog_content = "Sim chefe?",
  ui_story_5031_50310902_73_dialog_content = "Mantenha a pontuação e assuma um pouco para mim. Temos um negócio para discutir.",
  ui_story_5031_50310902_74_dialog_content = "Nele!",
  ui_story_5031_50310902_75_dialog_content = "Não me olhe assim. Estou bem agora.",
  ui_story_5031_50310902_76_dialog_content = "Multar? Tossir sangue em cima de mim não é BEM.",
  ui_story_5031_50310902_77_dialog_content = "Desculpe por suas roupas.",
  ui_story_5031_50310902_78_dialog_content = "Você sabe que não foi isso que eu quis dizer.",
  ui_story_5031_50310902_79_dialog_content = "Não se preocupe. Significa apenas que tenho mais sangue do que preciso... É um bom sinal, não é?",
  ui_story_5031_50310902_80_dialog_content = "Pare com o absurdo.",
  ui_story_5031_50310902_81_dialog_content = "Você realmente não pode me dizer qual é o seu plano?",
  ui_story_5031_50310902_82_dialog_content = "Vou me certificar de fazer isso para você, se você confiar em mim.",
  ui_story_5031_50310902_83_dialog_content = "...",
  ui_story_5031_50310902_84_dialog_content = "O que é esse olhar no seu rosto?",
  ui_story_5031_50310902_85_dialog_content = "Oh, é que você me lembrou do nosso passado novamente.",
  ui_story_5031_50310902_86_dialog_content = "Outra coisa embaraçosa que eu tinha feito?",
  ui_story_5031_50310902_87_dialog_content = "Bem, você sempre foi menor e mais magro do que eu, mas ainda assim, você tentou o seu melhor para ajudar os outros, me ajude.",
  ui_story_5031_50310902_88_dialog_content = "E esse é exatamente o olhar em seus olhos agora.",
  ui_story_5031_50310902_89_dialog_content = "O tempo pode ter deixado sua marca em nós, mas não muda quem somos.",
  ui_story_5031_50310902_90_dialog_content = "Sim... Algumas coisas mudam, mas algumas permanecem as mesmas.",
  ui_story_5031_50310902_91_dialog_content = "Assim como você ainda é mais baixo do que eu.",
  ui_story_5031_50310902_92_dialog_content = "Tsk. Mas agora, posso levar dez de vocês.",
  ui_story_5031_50310902_93_dialog_content = "Sim... Você não é mais o Jeno que precisava da minha proteção.",
  ui_story_5031_50310902_94_dialog_content = "Não que eu esteja em condições de protegê-la agora.",
  ui_story_5031_50310902_95_dialog_content = "Então é minha vez.",
  ui_story_5031_50310902_96_dialog_content = "Ha... Não é tão fácil, e você não pode simplesmente falar sobre isso.",
  ui_story_5031_50310902_97_dialog_content = "Estou falando sério, Elvis.",
  ui_story_5031_50310902_98_dialog_content = "Diga-me qual é o seu plano, e eu encontrarei uma maneira de fazê-lo acontecer.",
  ui_story_5031_50310902_99_dialog_content = "E se envolver a organização atrás de você?",
  ui_story_5031_50310902_100_dialog_content = "...?",
  ui_story_5031_50310902_101_dialog_content = "E se, apenas e se. Requer seu navio e algo de sua profundidade?",
  ui_story_5031_50310902_102_dialog_content = "Você ainda vai ajudar?",
  ui_story_5031_50310902_103_dialog_content = "Como você sabia...?",
  ui_story_5031_50310902_104_dialog_content = "Isso não é importante, Jeno.",
  ui_story_5031_50310902_105_dialog_content = "O importante é que não somos mais crianças e não podemos mais voltar àquele tempo simples.",
  ui_story_5031_50310902_106_dialog_content = "Todas as nossas decisões, promessas e palavras carregam muito mais peso e fardo.",
  ui_story_5031_50310902_107_dialog_content = "Então, deixe-me perguntar novamente. Se for esse o caso, você ainda vai me ajudar?",
  ui_story_5031_50310902_108_dialog_content = "...",
  ui_story_5031_50310902_109_dialog_content = "Eu... uma vez fiz uma promessa.",
  ui_story_5031_50310902_110_dialog_content = "Prometi proteger a nave e proteger aquela coisa.",
  ui_story_5031_50310902_111_dialog_content = "Entendo... Desculpe tê-lo colocado nesta posição.",
  ui_story_5031_50310902_112_dialog_content = "É melhor para nós voltarmos ao jogo. Parece que o trabalho é mais do que o seu substituto temporário pode lidar.",
  ui_story_5031_50310902_113_dialog_content = "Elvis, eu...",
  ui_story_5031_50310902_114_dialog_content = "Jeno.",
  ui_story_5031_50310902_115_dialog_content = "...",
  ui_story_5031_50310902_116_dialog_content = "Está bem. Eu entendo.",
  ui_story_5031_50310902_117_dialog_content = "Não importa o que aconteça, eu só quero que você saiba...",
  ui_story_5031_50310902_118_dialog_content = "Senti sua falta nos últimos doze anos.",
  ui_story_5031_50310902_119_dialog_content = "...!",
  ui_story_5031_50311001_1_dialog_content = "Sua Alteza.",
  ui_story_5031_50311001_2_dialog_content = "Matthieu? O que é isso?",
  ui_story_5031_50311001_3_dialog_content = "Você vai continuar com essa farsa?",
  ui_story_5031_50311001_4_dialog_content = "Estar na mesma água com os plebeus... É nojento.",
  ui_story_5031_50311001_5_dialog_content = "Sim, estou.",
  ui_story_5031_50311001_6_dialog_content = "Se você acha insuportável, pode ficar na praia ou no navio. Melhor ainda, você deve voltar para Lumopolis.",
  ui_story_5031_50311001_7_dialog_content = "Tsk, uma atitude tão enfurecedora...",
  ui_story_5031_50311001_8_dialog_content = "Matthieu.",
  ui_story_5031_50311001_9_dialog_content = "Hmph... Que tarefa. Por que eu deveria proteger uma princesa tão diva?",
  ui_story_5031_50311001_10_dialog_content = "...",
  ui_story_5031_50311001_11_dialog_content = "Matthieu, não sou uma diva, e esta princesa não precisa da sua proteção.",
  ui_story_5031_50311001_12_dialog_content = "E se você está apenas irritado com o fato de não saber nadar, não se preocupe, eu vou ficar bem.",
  ui_story_5031_50311001_13_dialog_content = "Pfft...",
  ui_story_5031_50311001_14_dialog_content = "O que... do que você está falando?!",
  ui_story_5031_50311001_15_dialog_content = "Eu não posso nadar!? Não há nenhuma maneira que eu não possa fazer algo que um plebeu humilde pode!",
  ui_story_5031_50311001_16_dialog_content = "E, Loewe, ouvi você rindo de mim! Como você ousa!",
  ui_story_5031_50311001_17_dialog_content = "Bem, você realmente não sabe nadar.",
  ui_story_5031_50311001_18_dialog_content = "Ahhhh! Você...!",
  ui_story_5031_50311001_19_dialog_content = "Eu tinha o suficiente! Sua princesa mal-humorada, marque minhas palavras, você vai se arrepender de se misturar com os plebeus!",
  ui_story_5031_50311001_20_dialog_content = "Eu vou me trocar!",
  ui_story_5031_50311001_21_dialog_content = "...",
  ui_story_5031_50311001_22_dialog_content = "Por que eles estão aqui mesmo...?",
  ui_story_5031_50311001_23_dialog_content = "Ele provavelmente queria me impedir de entrar no jogo porque ele não sabia nadar.",
  ui_story_5031_50311001_24_dialog_content = "Eu realmente não entendo porque Irridon até o enviou.",
  ui_story_5031_50311001_25_dialog_content = "Vice! Você voltou!",
  ui_story_5031_50311001_26_dialog_content = "Bem vindo de volta, Vice.",
  ui_story_5031_50311001_27_dialog_content = "Você foi tão incrível, Vice! Você definitivamente obterá uma pontuação alta!",
  ui_story_5031_50311001_28_dialog_content = "O Cloudwhale é tão bom quanto o nosso! E eu não tenho que ouvir meu mestre falar demais!",
  ui_story_5031_50311001_29_dialog_content = "Você me dá muito crédito, Fia.",
  ui_story_5031_50311001_30_dialog_content = "Os outros competidores eram adversários dignos.",
  ui_story_5031_50311001_31_dialog_content = "não achei oficial Gronru seria tão boa em surfar... Eu a subestimei.",
  ui_story_5031_50311001_32_dialog_content = "Está bem. Ainda temos mais uma rodada, mas a pontuação deles está fixada agora.",
  ui_story_5031_50311001_33_dialog_content = "Agora, é a vez de Carleen!",
  ui_story_5031_50311001_34_dialog_content = "Matthieu e Loewe estavam aqui? Eles também estão aqui para participar do jogo?",
  ui_story_5031_50311001_35_dialog_content = "Não se importe com eles.",
  ui_story_5031_50311001_36_dialog_content = "Venha para pensar sobre isso, não ouvimos a voz do nosso anfitrião há muito tempo.",
  ui_story_5031_50311001_37_dialog_content = "Você tem razão. Eu me pergunto o que ele e Elvis estão fazendo.",
  ui_story_5031_50311001_38_dialog_content = "De qualquer forma, é melhor você se preparar, Carleen.",
  ui_story_5031_50311001_39_dialog_content = "Boa sorte, Carleen!",
  ui_story_5031_50311001_40_dialog_content = "Vai, Carleen!",
  ui_story_5031_50311001_41_dialog_content = "Deixa comigo.",
  ui_story_5031_50311001_42_dialog_content = "...",
  ui_story_5031_50311001_43_dialog_content = "Jeno, senhor?",
  ui_story_5031_50311001_44_dialog_content = "O quê?",
  ui_story_5031_50311001_45_dialog_content = "<size=33>Ahh! O que há com a mudança repentina de atitude do chefe...?</size>",
  ui_story_5031_50311001_46_dialog_content = "Uhm... As pontuações da última rodada estão aqui. Você não vai anunciar?",
  ui_story_5031_50311001_47_dialog_content = "...",
  ui_story_5031_50311001_48_dialog_content = "Uhm... Ou, pelo menos, diga a palavra para começar a próxima rodada...",
  ui_story_5031_50311001_49_dialog_content = "Os competidores estão todos prontos e esperando...",
  ui_story_5031_50311001_50_dialog_content = "Começar.",
  ui_story_5031_50311001_51_dialog_content = "...",
  ui_story_5031_50311001_52_dialog_content = "Tudo bem... estou me acostumando com ele.",
  ui_story_5031_50311001_53_dialog_content = "Gelescer!",
  ui_story_5031_50311001_54_dialog_content = "Oh! Reação rápida!",
  ui_story_5031_50311001_55_dialog_content = "Ela usou Lumina para congelar as ondas!",
  ui_story_5031_50311001_56_dialog_content = "E acelerou enquanto executava o movimento com perfeição!",
  ui_story_5031_50311001_57_dialog_content = "Isto é incrível! Estou tão animado!",
  ui_story_5031_50311001_58_dialog_content = "Vai!",
  ui_story_5031_50311001_59_dialog_content = "Aaargh!",
  ui_story_5031_50311001_60_dialog_content = "Huh? Congelando tantos Eclipses ao mesmo tempo!?",
  ui_story_5031_50311001_61_dialog_content = "Uau!",
  ui_story_5031_50311001_62_dialog_content = "Essa garota também salvou Ranka, não foi?",
  ui_story_5031_50311001_63_dialog_content = "Ela é incrível. Ela não é apenas elegante, ela também é mortal contra todos aqueles Eclipsites!",
  ui_story_5031_50311001_64_dialog_content = "Não apenas isso, ela até congelou a superfície do mar, fazendo dele o seu caminho! Quanta precisão!",
  ui_story_5031_50311001_65_dialog_content = "Espere, é o nome dela Carleen?",
  ui_story_5031_50311001_66_dialog_content = "Agora eu lembro! Ela é a princesa, não é?",
  ui_story_5031_50311001_67_dialog_content = "Incrível, simplesmente incrível!",
  ui_story_5031_50311001_68_dialog_content = "Ela realmente fez meu coração bater forte! Eu tenho que acompanhar!",
  ui_story_5031_50311001_69_dialog_content = "Ufa...",
  ui_story_5031_50311001_70_dialog_content = "Isso é 62.",
  ui_story_5031_50311001_71_dialog_content = "Gronru acertou 70 e Ciel acertou... 93.",
  ui_story_5031_50311001_72_dialog_content = "Tsk. Ter um mecha com certeza é vantajoso para isso.",
  ui_story_5031_50311001_73_dialog_content = "Se Vice tenho 69... Hum...",
  ui_story_5031_50311001_74_dialog_content = "Eu preciso derrubar pelo menos mais 32, e marcar mais lances também.",
  ui_story_5031_50311001_75_dialog_content = "Quanto ao circo...",
  ui_story_5031_50311001_76_dialog_content = "Olá princesa Carleen. Você está fazendo uma pausa aqui?",
  ui_story_5031_50311001_77_dialog_content = "Sublime?",
  ui_story_5031_50311001_78_dialog_content = "Você se lembra do meu nome! Eu estou tão feliz!",
  ui_story_5031_50311001_79_dialog_content = "Apenas me ligue Carleen.",
  ui_story_5031_50311001_80_dialog_content = "Tudo bem, Carleen.",
  ui_story_5031_50311001_81_dialog_content = "Eu gosto muito de você, mas tenho notícias infelizes para você.",
  ui_story_5031_50311001_82_dialog_content = "O que foi?",
  ui_story_5031_50311001_83_dialog_content = "Nossa estratégia é enviar Rainbow e Merylt primeiro para marcar o máximo de pontos que puderem.",
  ui_story_5031_50311001_84_dialog_content = "Quanto a Frimet e eu...",
  ui_story_5031_50311001_85_dialog_content = "Estamos aqui para interferir com os outros competidores!",
  ui_story_5031_50311001_86_dialog_content = "Argh!",
  ui_story_5031_50311001_87_dialog_content = "Não admira que Frimet continuasse mexendo com Vice!",
  ui_story_5031_50311001_88_dialog_content = "Sim... Então não me odeie, por favor. Não é nada pessoal.",
  ui_story_5031_50311001_89_dialog_content = "Tsk! Como ousa um mero plebeu atacar a princesa Carleen!",
  ui_story_5031_50311001_90_dialog_content = "Loewe, eu quero que ela seja derrubada, agora mesmo!",
  ui_story_5031_50311001_91_dialog_content = "...",
  ui_story_5031_50311001_92_dialog_content = "Que ágil... Ela com certeza cresceu no circo.",
  ui_story_5031_50311001_93_dialog_content = "Estou em desvantagem aqui em uma placa tão estreita...",
  ui_story_5031_50311001_94_dialog_content = "Oh! Carleen, você é incrível!",
  ui_story_5031_50311001_95_dialog_content = "Você pode manter o equilíbrio enquanto defende meus ataques!",
  ui_story_5031_50311001_96_dialog_content = "Você é tão graciosa, eu realmente te admiro!",
  ui_story_5031_50311001_97_dialog_content = "Uhm... Na verdade, não posso machucá-la.",
  ui_story_5031_50311001_98_dialog_content = "Eu só tenho que tentar colocar alguma distância entre nós.",
  ui_story_5031_50311001_99_dialog_content = "Huh? Onde você está indo, Carleen?",
  ui_story_5031_50311001_100_dialog_content = "Você não vai brincar comigo um pouco mais? Ainda não me diverti o suficiente!",
  ui_story_5031_50311001_101_dialog_content = "Agora é a hora!",
  ui_story_5031_50311001_102_dialog_content = "Gelescer!",
  ui_story_5031_50311001_103_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5031_50311001_104_dialog_content = "Ah!",
  ui_story_5031_50311001_105_dialog_content = "Eu sinto Muito. É melhor você ficar aqui.",
  ui_story_5031_50311001_106_dialog_content = "Ai... Hã?",
  ui_story_5031_50311001_107_dialog_content = "Eu pensei que era um caso perdido!",
  ui_story_5031_50311001_108_dialog_content = "Então ela me congelou no lugar aqui!",
  ui_story_5031_50311001_109_dialog_content = "Não consigo me mexer, mas não estou ferido de forma alguma, e minha cabeça não está no gelo...",
  ui_story_5031_50311001_110_dialog_content = "Oh, tanto controle e precisão! Agora eu gosto Carleen ainda mais!",
  ui_story_5031_50311001_111_dialog_content = "Aquele garoto... Ela é tão estranha.",
  ui_story_5031_50311001_112_dialog_content = "Pelo menos ela não é mais uma ameaça. Tudo que eu preciso fazer agora é focar em ganhar pontos.",
  ui_story_5031_50311001_113_dialog_content = "Perdi muito tempo naquela época. Eu tenho que fazer as pazes para o bem de todos.",
  ui_story_5031_50311002_1_dialog_content = "Montem, todos!",
  ui_story_5031_50311002_2_dialog_content = "Como você gostou do concurso de surf?",
  ui_story_5031_50311002_3_dialog_content = "Nós amamos isso!",
  ui_story_5031_50311002_4_dialog_content = "Heheh, eu também me diverti muito!",
  ui_story_5031_50311002_5_dialog_content = "Todos vocês tiveram um momento memorável aqui. É para sempre para você manter!",
  ui_story_5031_50311002_6_dialog_content = "Agora, é hora de anunciar a pontuação!",
  ui_story_5031_50311002_7_dialog_content = "Gole-",
  ui_story_5031_50311002_8_dialog_content = "Fia, seu som de deglutição foi alto.",
  ui_story_5031_50311002_9_dialog_content = "Não estou nem um pouco ansioso!",
  ui_story_5031_50311002_10_dialog_content = "Não se preocupe. Carleen fez um ótimo trabalho. Nós ficaremos bem.",
  ui_story_5031_50311002_11_dialog_content = "Eu só alcancei a pontuação de Gronru em matar os Eclipsites...",
  ui_story_5031_50311002_12_dialog_content = "Quanto ao placar dos meus movimentos... Teremos que ver.",
  ui_story_5031_50311002_13_dialog_content = "Rainbow e sua equipe... ainda podem estar à nossa frente.",
  ui_story_5031_50311002_14_dialog_content = "Tudo bem! Eu não vou te deixar esperando!",
  ui_story_5031_50311002_15_dialog_content = "O vencedor do concurso de surf é...",
  ui_story_5031_50311002_16_dialog_content = "Sinceramente! A Esmeralda!",
  ui_story_5031_50311002_17_dialog_content = "Os cálculos detalhados e a pontuação serão afixados no quadro de avisos. Por favor, verifique se você está em dúvida!",
  ui_story_5031_50311002_18_dialog_content = "Eu prometo que é a pontuação legítima de todo o público aqui! Sem favores!",
  ui_story_5031_50311002_19_dialog_content = "Uau!",
  ui_story_5031_50311002_20_dialog_content = "Rainbow, você merece!",
  ui_story_5031_50311002_21_dialog_content = "Obrigado por seu apoio à Esmeralda!",
  ui_story_5031_50311002_22_dialog_content = "E agradecemos ao laird pelos 5 milhões de Nightium!",
  ui_story_5031_50311002_23_dialog_content = "Hahahaha!",
  ui_story_5031_50311002_24_dialog_content = "Tão triste!",
  ui_story_5031_50311002_25_dialog_content = "Nightium... 5 milhões de Nightium...",
  ui_story_5031_50311002_26_dialog_content = "Boo-hoo, meu maiô...!",
  ui_story_5031_50311002_27_dialog_content = "Está bem. O Emerald não é um time de carnaval, então ainda temos uma chance no Cloudwhale.",
  ui_story_5031_50311002_28_dialog_content = "Quanto ao maiô... Ainda podemos comprá-lo sem o prêmio em dinheiro.",
  ui_story_5031_50311002_29_dialog_content = "Sério? Você realmente vai me comprar um maiô, PlayerName?",
  ui_story_5031_50311002_30_dialog_content = "Claro, se você parar de irritar as pessoas e fofocar e for apenas uma boa garota.",
  ui_story_5031_50311002_31_dialog_content = "O que!? Eu sou uma dama! De onde veio essa sua impressão?",
  ui_story_5031_50311002_32_dialog_content = "Então quer dizer que você não pode fazer isso? Ah, não importa então.",
  ui_story_5031_50311002_33_dialog_content = "Ahhh! Mas você prometeu! Você não pode voltar atrás em uma promessa!",
  ui_story_5031_50311002_34_dialog_content = "...",
  ui_story_5031_50311002_35_dialog_content = "Em seguida, nossa equipe vice-campeã!",
  ui_story_5031_50311002_36_dialog_content = "Silêncio! Eles estão anunciando o vice-campeão agora!",
  ui_story_5031_50311002_37_dialog_content = "O vice-campeão é...",
  ui_story_5031_50311002_38_dialog_content = "Gronru e Ciel, da Illumina!",
  ui_story_5031_50311002_39_dialog_content = "Uau!",
  ui_story_5031_50311002_40_dialog_content = "O quê?!",
  ui_story_5031_50311002_41_dialog_content = "<size=45>O quê?!</size>",
  ui_story_5031_50311002_42_dialog_content = "<size=55>Hã?</size>",
  ui_story_5031_50311002_43_dialog_content = "Seu... Gronru e Ciel?",
  ui_story_5031_50311002_44_dialog_content = "E-então... Isso não significa...",
  ui_story_5031_50311002_45_dialog_content = "Não seríamos nós a levar o prémio para casa...?",
  ui_story_5031_50311002_46_dialog_content = "T-O Cloudwhale vai ser de outra pessoa!?",
  ui_story_5031_50311002_47_dialog_content = "Ahhhh! O mestre vai me repreender até a morte!",
  ui_story_5031_50311002_48_dialog_content = "...",
  ui_story_5031_50311002_49_dialog_content = "Carleen? Onde você está indo?",
  ui_story_5031_50311002_50_dialog_content = "Carleen!",
  ui_story_5031_50311002_51_dialog_content = "Espere, Carleen. Onde você está indo?",
  ui_story_5031_50311002_52_dialog_content = "Carro⁠—",
  ui_story_5031_50311002_53_dialog_content = "Desculpe, PlayerName e Vice, mas eu gostaria de ficar sozinho por um tempo.",
  ui_story_5031_50311002_54_dialog_content = "W-Nós podemos ir.",
  ui_story_5031_50311002_55_dialog_content = "Mas estamos preocupados com você. Você poderia pelo menos...",
  ui_story_5031_50311002_56_dialog_content = "Pelo menos nos diga... O que aconteceu?",
  ui_story_5031_50311002_56X1_dialog_content = "Sim. Fizemos algo errado?",
  ui_story_5031_50311002_56X2_dialog_content = "Não, não... Não tem nada a ver com você.",
  ui_story_5031_50311002_57_dialog_content = "Eu só... sinto que sou um perdedor.",
  ui_story_5031_50311002_58_dialog_content = "Fiz tudo, mas ainda não consegui ganhar para meus amigos... e não consegui o que ela queria.",
  ui_story_5031_50311002_59_dialog_content = "Mas não é sua culpa.",
  ui_story_5031_50311002_60_dialog_content = "Verdade seja dita, eu deveria ser o responsável...",
  ui_story_5031_50311002_61_dialog_content = "Todo mundo deu o seu melhor, mas eu estraguei tudo porque não aprendi a surfar.",
  ui_story_5031_50311002_62_dialog_content = "Isso é diferente...",
  ui_story_5031_50311002_63_dialog_content = "Como é diferente? Parece o mesmo.",
  ui_story_5031_50311002_64_dialog_content = "Obrigado por dizer isso, mas a culpa é minha, não sua, e isso é um fato.",
  ui_story_5031_50311002_65_dialog_content = "Este é um esporte de equipe. Ninguém deve levar toda a culpa.",
  ui_story_5031_50311002_66_dialog_content = "Sou eu que preciso pedir desculpas e agradecer.",
  ui_story_5031_50311002_67_dialog_content = "Sem vocês, não conseguiríamos chegar até aqui.",
  ui_story_5031_50311002_68_dialog_content = "...",
  ui_story_5031_50311002_69_dialog_content = "Da mesma forma, você acha que podemos chegar tão longe sem Vice?",
  ui_story_5031_50311002_70_dialog_content = "Não...",
  ui_story_5031_50311002_71_dialog_content = "Veja, então você entende. É o que sentimos por você.",
  ui_story_5031_50311002_72_dialog_content = "Quanto ao prêmio, a baleia, ou o que quer que seja, só temos que pensar de outra maneira.",
  ui_story_5031_50311002_73_dialog_content = "Não é o fim do mundo se não vencermos.",
  ui_story_5031_50311002_74_dialog_content = "Sim, Carleen. No mínimo, podemos ver Jeno, Oficial Gronru, ou Rainbow.",
  ui_story_5031_50311002_75_dialog_content = "Podemos contar a eles sobre Cloudwhale. Tenho certeza que eles estarão dispostos a ajudar.",
  ui_story_5031_50311002_75X1_dialog_content = "Vice está certo. Nada disso é um problema que não possa ser resolvido.",
  ui_story_5031_50311002_76_dialog_content = "Então, pare de ficar tão chateado, Carleen.",
  ui_story_5031_50311002_77_dialog_content = "Vamos descobrir algo juntos.",
  ui_story_5031_50311002_78_dialog_content = "...",
  ui_story_5031_50311002_79_dialog_content = "Tá bom.",
  ui_story_5031_50311002_80_dialog_content = "Você tem razão. Obrigada.",
  ui_story_5031_50311002_81_dialog_content = "Eu deveria aprender com você. Talvez seja isso que meu pai queria...",
  ui_story_5031_50311002_82_dialog_content = "Senhor Schwartz? O que você quer dizer?",
  ui_story_5031_50311002_83_dialog_content = "Na verdade, antes desta viagem, tivemos uma... conversa.",
  ui_story_5031_50311002_83X1_dialog_content = "Conversação?",
  ui_story_5031_50311002_83X2_dialog_content = "Sim. Papai gostaria que eu contemplasse o propósito de viajar com você.",
  ui_story_5031_50311002_83X3_dialog_content = "Acho que entendi o que ele quis dizer. Há muitas coisas que posso aprender com você.",
  ui_story_5031_50311002_83X4_dialog_content = "Não é à toa que você esteve perdido em seu próprio mundo o dia todo, Carleen.",
  ui_story_5031_50311002_83X5_dialog_content = "Mas mesmo depois de quebrar meu cérebro, muitas coisas ainda estão além de mim.",
  ui_story_5031_50311002_83X6_dialog_content = "Como o avanço que você falou, Vice. Na verdade, eu tentei hoje.",
  ui_story_5031_50311002_83X7_dialog_content = "Eh? Você tentou?",
  ui_story_5031_50311002_83X8_dialog_content = "Sim, e eu segui o que você sugeriu, a liberação da consciência.",
  ui_story_5031_50311002_83X9_dialog_content = "Mas eu ficava lembrando da conversa com meu pai... e assim não conseguia me concentrar.",
  ui_story_5031_50311002_83X10_dialog_content = "Então eu falhei.",
  ui_story_5031_50311002_83X11_dialog_content = "Eu vejo. Isso é realmente muito comum, no entanto.",
  ui_story_5031_50311002_83X12_dialog_content = "É muito difícil se libertar de quaisquer emoções para que você possa estar totalmente focado.",
  ui_story_5031_50311002_83X13_dialog_content = "Para mim, me livrei de todos os outros pensamentos porque me agarrei a esse brilho.",
  ui_story_5031_50311002_83X14_dialog_content = "Brilho? Lembro que você mencionou. O que foi isso?",
  ui_story_5031_50311002_83X15_dialog_content = "Hum... Pensei nas coisas divertidas que fiz com você e PlayerName.",
  ui_story_5031_50311002_83X16_dialog_content = "E antes que eu percebesse, havia silêncio dentro de mim.",
  ui_story_5031_50311002_83X17_dialog_content = "Mas isso é bastante profundo e difícil para mim descrever.",
  ui_story_5031_50311002_83X18_dialog_content = "Eu vejo. Então vou...",
  ui_story_5031_50311002_84_dialog_content = "PlayerName! Carleen! Vice!",
  ui_story_5031_50311002_85_dialog_content = "Por que você me deixou para trás? Nós estávamos procurando por você!",
  ui_story_5031_50311002_85X1_dialog_content = "Ops, não acredito que esquecemos de você! Estávamos com tanta pressa.",
  ui_story_5031_50311002_86_dialog_content = "Qual é o problema, Fia? Por que você está tão perturbado?",
  ui_story_5031_50311002_87_dialog_content = "Procurando por você, é claro!",
  ui_story_5031_50311002_88_dialog_content = "Ouça, ouça! Jeno veio nos dizer que...",
  ui_story_5031_50311002_89_dialog_content = "O ranking da competição de surf serve apenas para decidir a sequência da próxima competição! Ainda temos mais um concurso!",
  ui_story_5031_50311002_90_dialog_content = "Estamos nos apresentando com o circo como membros!",
  ui_story_5031_50311002_91_dialog_content = "Isso significa que ainda temos uma chance!",
  ui_story_5031_50311101_1_dialog_content = "Espere, então o que exatamente é⁠—",
  ui_story_5031_50311101_2_dialog_content = "Boo-hoo—<size=45>Uaaau!!</size>",
  ui_story_5031_50311101_3_dialog_content = "<size=45>Nosso... grande objetivo...</size>",
  ui_story_5031_50311101_4_dialog_content = "A Baleia Nuvem... Nesse ritmo, vamos perder a Baleia Nuvem! <size=45>Waaaagh!</size>",
  ui_story_5031_50311101_5_dialog_content = "(Nossa... A batalha final mais importante está chegando...)",
  ui_story_5031_50311101_6_dialog_content = "(Mas as feras maravilhosas estão fazendo birra e simplesmente não ouvem Fia.)",
  ui_story_5031_50311101_7_dialog_content = "(Nós seremos eliminados assim. É melhor eu falar com Fia para tentar mais!)",
  ui_story_5031_50311101_8_option_content = "Fia, não fique chateada!",
  ui_story_5031_50311101_9_dialog_content = "D-Isso significa que você tem uma ideia, PlayerName?",
  ui_story_5031_50311101_10_dialog_content = "Para ser honesto, não. Mas só temos menos de uma hora para ensaiar.",
  ui_story_5031_50311101_11_dialog_content = "O público virá para ver a performance depois disso.",
  ui_story_5031_50311101_12_dialog_content = "Estamos tão mortos! Waaaagh!",
  ui_story_5031_50311101_13_dialog_content = "Para para! Pare de chorar!",
  ui_story_5031_50311101_14_dialog_content = "Lembrar? Atravessamos todo o Astra para proteger feras maravilhosas contra todas as probabilidades.",
  ui_story_5031_50311101_15_dialog_content = "Conseguimos fazer ISSO! Não há como algo assim pode nos derrubar, certo?",
  ui_story_5031_50311101_16_dialog_content = "Se você se esforçasse mais para chegar até a Bica, poderíamos dar a eles uma ótima apresentação!",
  ui_story_5031_50311101_17_dialog_content = "Ei?",
  ui_story_5031_50311101_18_dialog_content = "Eu... estou derrotado.",
  ui_story_5031_50311101_19_dialog_content = "Quer dizer, nós entramos no concurso sem nem saber se o prêmio final era mesmo o Cloudwhale.",
  ui_story_5031_50311101_20_dialog_content = "(E você só percebeu isso agora!?)",
  ui_story_5031_50311101_21_dialog_content = "Ei! Esse olhar em seu rosto! Você está pensando algo ruim sobre mim, não é!?",
  ui_story_5031_50311101_22_dialog_content = "NÃO! Claro que não! Eu não ousaria!",
  ui_story_5031_50311101_23_dialog_content = "Que tal agora? Vamos fingir que vamos ao banheiro e ver se o prêmio é o Cloudwhale?",
  ui_story_5031_50311101_24_dialog_content = "Se for, então você estaria motivado para ensaiar com a Bica, certo?",
  ui_story_5031_50311101_25_dialog_content = "C-Podemos realmente fazer isso?",
  ui_story_5031_50311101_26_dialog_content = "Esse Jeno parece um cara temível. Seria ruim se o irrássemos.",
  ui_story_5031_50311101_27_dialog_content = "Oh, será apenas uma espiada rápida. Vai ficar tudo bem!",
  ui_story_5031_50311101_28_dialog_content = "Também tentarei usar minhas habilidades psíquicas para que ninguém descubra!",
  ui_story_5031_50311101_29_dialog_content = "Hmm, certo! Isso vai fazer!",
  ui_story_5031_50311101_30_dialog_content = "Eu confio em você, PlayerName. Minha besta maravilhosa \"super exótica\", a Caelestita!",
  ui_story_5031_50311101_31_dialog_content = "Vamos, pare de me chamar de besta maravilhosa já!",
  ui_story_5031_50311101_32_dialog_content = "Ah, não importa. Não temos muito tempo. Vamos mexer!",
  ui_story_5031_50311101_33_dialog_content = "<color=#e8d9bb>Em algum lugar no fundo do navio</color>",
  ui_story_5031_50311101_34_dialog_content = "Este é o lugar que o proprietário feroz não nos deixou entrar.",
  ui_story_5031_50311101_35_dialog_content = "É um labirinto! Todos os corredores parecem iguais e tantos caminhos bifurcados...",
  ui_story_5031_50311101_36_dialog_content = "Onde eles estão escondendo o Cloudwhale?",
  ui_story_5031_50311101_37_dialog_content = "Pare, Fia.",
  ui_story_5031_50311101_38_dialog_content = "Vamos nos esconder aqui um pouco. Sinto que alguém está vindo por aqui.",
  ui_story_5031_50311101_39_dialog_content = "*Bocejo* Já é a terceira rodada de patrulha.",
  ui_story_5031_50311101_40_dialog_content = "Não sei o que o chefe está pensando, mandando-nos patrulhar um lugar tão hermético quanto este.",
  ui_story_5031_50311101_41_dialog_content = "Por que haveria patrulhas em um circo? O dono do circo estaria escondendo alguma coisa?",
  ui_story_5031_50311101_42_dialog_content = "Sem você, eu definitivamente já seria pego e expulso, PlayerName.",
  ui_story_5031_50311101_43_dialog_content = "É tudo graças a você, PlayerName. Quando encontrarmos o Cloudwhale, com certeza vou recompensá-lo!",
  ui_story_5031_50311101_44_dialog_content = "Que tal um pacote de biscoitos de animais? Kylo adora. Você acha que vai gostar, PlayerName?",
  ui_story_5031_50311101_45_dialog_content = "Vamos pensar nisso depois de encontrarmos o prêmio.",
  ui_story_5031_50311101_46_dialog_content = "Hum...",
  ui_story_5031_50311101_47_dialog_content = "Resistir. Sinto duas pessoas à frente... Mas elas não estão se movendo.",
  ui_story_5031_50311101_48_dialog_content = "Vamos tentar passar por eles, então.",
  ui_story_5031_50311101_49_dialog_content = "Espere aí!",
  ui_story_5031_50311101_50_dialog_content = "Que foi agora?",
  ui_story_5031_50311101_51_dialog_content = "Essas duas pessoas se sentem... familiares, de alguma forma.",
  ui_story_5031_50311101_52_dialog_content = "Elvis e Patou?",
  ui_story_5031_50311101_53_dialog_content = "O laird e o guarda? Porque eles estão aqui?",
  ui_story_5031_50311101_54_dialog_content = "Como eu iria saber? Vamos esquecê-los primeiro e focar no nosso alvo.",
  ui_story_5031_50311101_55_dialog_content = "Vamos ficar quietos e não alertá-los da nossa presença.",
  ui_story_5031_50311101_56_dialog_content = "Me desculpe senhor. Procuramos na residência de Jeno e em todos os lugares relacionados, mas não encontramos nada que se pareça com uma chave.",
  ui_story_5031_50311101_57_dialog_content = "Está bem. Eu sei onde é.",
  ui_story_5031_50311101_58_dialog_content = "Ele mantém a chave com ele em todos os momentos.",
  ui_story_5031_50311101_59_dialog_content = "Agora vai ser difícil...",
  ui_story_5031_50311101_60_dialog_content = "Está bem. O plano ainda está em andamento. Temos que fazer funcionar esta noite.",
  ui_story_5031_50311101_61_dialog_content = "O plano? PlayerName, eles estão falando sobre algum plano⁠—",
  ui_story_5031_50311101_62_option_content = "Rápido!",
  ui_story_5031_50311101_63_dialog_content = "Você ouviu isso?",
  ui_story_5031_50311101_64_dialog_content = "Quem está aí? Saia, agora!",
  ui_story_5031_50311101_65_dialog_content = "(Oh não! Corra!)",
  ui_story_5031_50311101_66_dialog_content = "Huff, huff. Chegamos ao convés.",
  ui_story_5031_50311101_67_dialog_content = "Ufa!!! Você foi tão rude, PlayerName! Você quase me sufocou!",
  ui_story_5031_50311101_68_dialog_content = "Eu sinto Muito! Eu estava muito focado em fugir.",
  ui_story_5031_50311101_69_dialog_content = "Eles foram para lá!",
  ui_story_5031_50311101_70_dialog_content = "*Tosse* Vamos... encontrá-los.",
  ui_story_5031_50311101_71_dialog_content = "Oh! Eles ainda estão no nosso encalço. É melhor encontrarmos um lugar para nos escondermos!",
  ui_story_5031_50311101_72_dialog_content = "Ei, PlayerName e Pequena Fia!",
  ui_story_5031_50311101_73_dialog_content = "Eu não sou pequeno!",
  ui_story_5031_50311101_74_dialog_content = "Você já fez o ensaio?",
  ui_story_5031_50311101_75_dialog_content = "Huh? N-Não, ainda não. Mas precisávamos fazer alguma coisa, então, por favor, desculpe...",
  ui_story_5031_50311101_76_dialog_content = "Ele Ele! Eu tenho um ás na manga!",
  ui_story_5031_50311101_77_dialog_content = "Com a ajuda do Trono, certamente serei o vencedor desta vez!",
  ui_story_5031_50311101_78_dialog_content = "Por que não te dou uma prévia, meu rival derrotado!?",
  ui_story_5031_50311101_79_dialog_content = "(Oh, não, nós nos envolvemos com Gronru. Existe algum lugar para se esconder nas proximidades?)",
  ui_story_5031_50311101_80_dialog_content = "PlayerName, eles estão quase em cima de nós!",
  ui_story_5031_50311101_81_dialog_content = "Use suas habilidades psíquicas para fazer algo!",
  ui_story_5031_50311101_82_dialog_content = "Não funciona assim!",
  ui_story_5031_50311101_83_dialog_content = "Invencível-",
  ui_story_5031_50311101_84_dialog_content = "Mar azul-",
  ui_story_5031_50311101_85_dialog_content = "<size=45>Trono!!</size>",
  ui_story_5031_50311101_86_dialog_content = "A luz, é tão ofuscante!",
  ui_story_5031_50311101_87_dialog_content = "Ugh... O que há com essa luz!?",
  ui_story_5031_50311101_88_dialog_content = "Incrível, não é?",
  ui_story_5031_50311101_89_dialog_content = "Ele fornece iluminação para o meu trono!",
  ui_story_5031_50311101_90_dialog_content = "Dessa forma, posso surfar até nas noites mais escuras!",
  ui_story_5031_50311101_91_dialog_content = "Certo. T-Isso é legal?",
  ui_story_5031_50311101_92_dialog_content = "Que incrível!",
  ui_story_5031_50311101_93_dialog_content = "Chamou a atenção de tantas pessoas!?",
  ui_story_5031_50311101_94_dialog_content = "Isso foi incrível! Você pode fazer isso de novo?",
  ui_story_5031_50311101_95_dialog_content = "Novamente? É claro!",
  ui_story_5031_50311101_96_dialog_content = "Tsk. Há muitas pessoas aqui. Eles já devem ter fugido.",
  ui_story_5031_50311101_97_dialog_content = "Está bem. Eles podem ter escutado, mas isso não afeta nosso plano.",
  ui_story_5031_50311101_98_dialog_content = "Vamos voltar. Tudo vai de acordo com o plano.",
  ui_story_5031_50311101_99_dialog_content = "Como você manda.",
  ui_story_5031_50311101_100_dialog_content = "Eles foram embora. Que alivio.",
  ui_story_5031_50311101_101_dialog_content = "Muito obrigado, Gronru!",
  ui_story_5031_50311101_102_dialog_content = "Hein? Agradecer por quê? O que você está falando?",
  ui_story_5031_50311101_103_dialog_content = "Agradeceremos assim que tudo isso passar.",
  ui_story_5031_50311101_104_dialog_content = "Mas temos coisas para fazer. Mais tarde!",
  ui_story_5031_50311101_105_dialog_content = "Ei, por que você está com pressa, meu rival derrotado!?",
  ui_story_5031_50311101_106_dialog_content = "Bem, pelo menos eles parecem mais relaxados agora.",
  ui_story_5031_50311101_107_dialog_content = "Eles devem ter gostado do meu desempenho extraordinário!",
  ui_story_5031_50311101_108_dialog_content = "Depois de passar por todos os problemas, não só perdemos tempo, como ainda não descobrimos qual é o grande prêmio.",
  ui_story_5031_50311101_109_dialog_content = "Não há nada que possamos fazer. Era enorme e cheio de guardas dentro do navio.",
  ui_story_5031_50311101_110_dialog_content = "Não há como revistarmos a nave inteira só nós dois.",
  ui_story_5031_50311101_111_dialog_content = "Parece que vamos ter que fazer da maneira mais difícil e ser o vencedor!",
  ui_story_5031_50311101_112_dialog_content = "Mas... Estamos sem tempo...",
  ui_story_5031_50311101_113_dialog_content = "Minha Baleia Nuvem... Minha pobre Baleia Nuvem já deve estar...",
  ui_story_5031_50311101_114_dialog_content = "Por que você está chorando de novo!?",
  ui_story_5031_50311101_115_dialog_content = "PlayerName, Fia. Você ainda está ensaiando?",
  ui_story_5031_50311101_116_dialog_content = "Você disse algo rude para Fia para fazê-la chorar?",
  ui_story_5031_50311101_117_option_content = "Parou!",
  ui_story_5031_50311101_118_option_content = "Não sou eu!",
  ui_story_5031_50311101_119_dialog_content = "Bica simplesmente não colabora, então Fia está em pânico.",
  ui_story_5031_50311101_120_dialog_content = "Hiya!",
  ui_story_5031_50311101_121_dialog_content = "Eles... Eles não estão elogiando você!",
  ui_story_5031_50311101_122_dialog_content = "Ei?",
  ui_story_5031_50311101_123_dialog_content = "Estranho. Achei que eles tinham um bom relacionamento.",
  ui_story_5031_50311101_124_dialog_content = "Como é que a Bica de repente não colabora?",
  ui_story_5031_50311101_125_dialog_content = "Você não conversou com a Bica sobre isso?",
  ui_story_5031_50311101_126_dialog_content = "Eu falei, mas a Bica não ouve!",
  ui_story_5031_50311101_127_dialog_content = "O que você disse para a Bica?",
  ui_story_5031_50311101_128_dialog_content = "Eu disse a Bica para trabalhar comigo para ganhar aquele prêmio importante.",
  ui_story_5031_50311101_129_dialog_content = "Então, o que disse Bica?",
  ui_story_5031_50311101_130_dialog_content = "Bica não disse nada...",
  ui_story_5031_50311101_131_dialog_content = "Afinal, a Bica não concordou?!",
  ui_story_5031_50311101_132_dialog_content = "Mas a Bica já prometeu ser minha parceira temporária... Como não concordar?!",
  ui_story_5031_50311101_133_dialog_content = "Uaaau!!!",
  ui_story_5031_50311101_134_dialog_content = "Oh, não chore, Fia... Você é a única que pode se ajudar desta vez.",
  ui_story_5031_50311101_135_dialog_content = "Ajude-me?",
  ui_story_5031_50311101_136_dialog_content = "A Bica pode ter concordado em ser sua parceira, mas isso não significa que você pode mandar por aí.",
  ui_story_5031_50311101_137_dialog_content = "Você está nessa situação agora só porque não deu ouvidos à Bica.",
  ui_story_5031_50311101_138_dialog_content = "O que devo fazer então?",
  ui_story_5031_50311101_139_dialog_content = "Primeiro, peça desculpas à Bica.",
  ui_story_5031_50311101_140_dialog_content = "Não apenas desculpas. Você tem que pedir a ajuda da Bica nisso, e ter o consentimento da Bica!",
  ui_story_5031_50311101_141_dialog_content = "Será que a Bica me daria uma mão desta vez?",
  ui_story_5031_50311101_142_dialog_content = "Parece muito mais feroz que uma Bica selvagem...",
  ui_story_5031_50311101_143_dialog_content = "Isso depende da sua atitude.",
  ui_story_5031_50311101_144_dialog_content = "Você consegue, Fia.",
  ui_story_5031_50311101_145_dialog_content = "Sim. Não desista. Apenas faça seu melhor.",
  ui_story_5031_50311101_146_dialog_content = "Al-Tudo bem. Vou tentar.",
  ui_story_5031_50311101_147_dialog_content = "Bica, eu...",
  ui_story_5031_50311101_148_dialog_content = "Desculpe.",
  ui_story_5031_50311101_149_dialog_content = "Oi oi?",
  ui_story_5031_50311101_150_dialog_content = "(Bica coloca as patas ao lado das orelhas. Está pedindo para a Fia falar mais alto?)",
  ui_story_5031_50311101_151_dialog_content = "Eu...",
  ui_story_5031_50311101_152_dialog_content = "<size=45>Eu sinto Muito!</size>",
  ui_story_5031_50311101_153_dialog_content = "Foi minha culpa. Eu não deveria ter forçado você a ajudar no meu desempenho, ignorando sua vontade...",
  ui_story_5031_50311101_154_dialog_content = "Eu sinto muito. Não vai acontecer da próxima vez... Th-Não haverá uma próxima vez!",
  ui_story_5031_50311101_155_dialog_content = "Eu sempre vou perguntar sobre seus sentimentos com antecedência no futuro... Boo-hoo...",
  ui_story_5031_50311101_156_dialog_content = "Ei?",
  ui_story_5031_50311101_157_dialog_content = "E depois? Er, depois... que tal eu te pagar uma boa refeição?",
  ui_story_5031_50311101_158_dialog_content = "Hai-Hai-Hai?",
  ui_story_5031_50311101_159_dialog_content = "Huh? Você quer ter as uvas lendárias do Sr. Peng?",
  ui_story_5031_50311101_160_dialog_content = "Você disse que outra Bica lhe disse isso?",
  ui_story_5031_50311101_161_dialog_content = "Mas é tão caro...",
  ui_story_5031_50311101_162_dialog_content = "Oi oi?",
  ui_story_5031_50311101_163_dialog_content = "Não não! Eu não estou reclamando!",
  ui_story_5031_50311101_164_dialog_content = "Eu compro qualquer coisa para você, contanto que você me perdoe. Boo-hoo...",
  ui_story_5031_50311101_165_dialog_content = "(Oh, basta olhar para a expressão de Fia agora.)",
  ui_story_5031_50311101_166_dialog_content = "(Ela realmente deveria aproveitar essa chance para aprender a trabalhar com os outros.)",
  ui_story_5031_50311101_167_dialog_content = "Oi!",
  ui_story_5031_50311101_168_dialog_content = "(Bica parece feliz. Bica aceitou as desculpas de Fia?)",
  ui_story_5031_50311101_169_dialog_content = "Você me perdoa? Isso é maravilhoso!",
  ui_story_5031_50311101_170_dialog_content = "Então sobre o desempenho...",
  ui_story_5031_50311101_171_dialog_content = "Hiya!",
  ui_story_5031_50311101_172_dialog_content = "Hã?",
  ui_story_5031_50311101_173_dialog_content = "Fia, o que disse Bica?",
  ui_story_5031_50311101_174_dialog_content = "Ele disse... \"Isso depende de você.\"",
  ui_story_5031_50311101_175_dialog_content = "É tão vago?!",
  ui_story_5031_50311101_176_dialog_content = "Vai ficar tudo bem? Não deveria perguntar mais uma vez à Bica, só para ter certeza?",
  ui_story_5031_50311101_177_dialog_content = "Quer dizer, o resultado da batalha final depende disso...",
  ui_story_5031_50311101_178_dialog_content = "Mas eu...",
  ui_story_5031_50311101_179_dialog_content = "A batalha final está sobre nós! Concorrentes, está na hora!",
  ui_story_5031_50311101_180_dialog_content = "Já?!",
  ui_story_5031_50311101_181_dialog_content = "Já faz uma hora? Não há outra escolha...",
  ui_story_5031_50311101_182_dialog_content = "Temos que fazer isso!",
  ui_story_5031_50311101_183_dialog_content = "Deixe para mim!",
  ui_story_5031_50311101_184_dialog_content = "Vou tentar ganhar o máximo de pontos que puder.",
  ui_story_5031_50311101_185_dialog_content = "A Bica e eu também daremos o nosso melhor!",
  ui_story_5031_50311101_186_dialog_content = "Hiya!",
  ui_story_5031_50311201_1_dialog_content = "À medida que a noite se põe, a terceira rodada da competição está prestes a começar!",
  ui_story_5031_50311201_2_dialog_content = "Uau!!!",
  ui_story_5031_50311201_3_dialog_content = "Com base nos resultados das rodadas anteriores, duas equipes se enfrentarão no palco!",
  ui_story_5031_50311201_4_dialog_content = "Eles são... a equipe líder da Illumina!",
  ui_story_5031_50311201_5_dialog_content = "E uma equipe em ascensão liderada pela extrozoóloga novata Fia!",
  ui_story_5031_50311201_6_dialog_content = "Ohhhhhh!",
  ui_story_5031_50311201_7_dialog_content = "Isso é uma recepção calorosa do público. Excelente!",
  ui_story_5031_50311201_8_dialog_content = "Agora, antes que o jogo comece oficialmente, vamos curtir a apresentação de abertura do Ringmaster—Jeno e as três irmãs!",
  ui_story_5031_50311201_9_dialog_content = "Primeiro, Ringmaster Jeno!",
  ui_story_5031_50311201_10_dialog_content = "O Ritual da Previsão, uma habilidade procurada por inúmeros Aurorianos ao longo dos tempos.",
  ui_story_5031_50311201_11_dialog_content = "Comunicar-se com existências maiores, decifrar fragmentos do passado ou do futuro...",
  ui_story_5031_50311201_12_dialog_content = "E ser capaz de perceber a verdadeira história ou espiar o futuro.",
  ui_story_5031_50311201_13_dialog_content = "Esta noite, demonstrarei este antigo poder e responderei a todas as suas perguntas.",
  ui_story_5031_50311201_14_dialog_content = "Este baralho de Origin Card será meu auxílio.",
  ui_story_5031_50311201_15_dialog_content = "Oh! É isso! O lendário Ritual de Previsão!",
  ui_story_5031_50311201_16_dialog_content = "Ser capaz de convocar Eclipsites e prever o futuro. Que segredos o poder da Origem guarda?",
  ui_story_5031_50311201_17_dialog_content = "Em seguida, devo pedir a ajuda de um público sortudo.",
  ui_story_5031_50311201_18_dialog_content = "Quem é o convidado predestinado que vai cruzar meu caminho?",
  ui_story_5031_50311201_19_dialog_content = "Eu!!!",
  ui_story_5031_50311201_20_dialog_content = "Eu! Me pegue!",
  ui_story_5031_50311201_21_dialog_content = "Eu sinto isso. Eu sinto isso agora...",
  ui_story_5031_50311201_22_dialog_content = "A Carta de Origem aponta meu destino para... VOCÊ!",
  ui_story_5031_50311201_23_dialog_content = "A senhora à direita da primeira fila.",
  ui_story_5031_50311201_24_dialog_content = "Eu-Eu?",
  ui_story_5031_50311201_25_dialog_content = "Sim você. Por favor, venha aqui.",
  ui_story_5031_50311201_26_dialog_content = "Você pode me fazer qualquer pergunta, e eu responderei usando o Origin Card.",
  ui_story_5031_50311201_27_dialog_content = "Nada?",
  ui_story_5031_50311201_28_dialog_content = "Nada.",
  ui_story_5031_50311201_29_dialog_content = "Então... Você sabe de onde eu venho?",
  ui_story_5031_50311201_30_dialog_content = "Oh, Cartão de Origem, seja meus olhos e me dê a visão da verdade! Diga-me de onde esta senhora é!",
  ui_story_5031_50311201_31_dialog_content = "(As cartas dançam entre os dedos de Jeno, e então ele tira uma!)",
  ui_story_5031_50311201_32_dialog_content = "O Origin Card me deu a resposta. Você é de Petyaburg.",
  ui_story_5031_50311201_33_dialog_content = "Como você sabia?!",
  ui_story_5031_50311201_34_dialog_content = "O Cartão de Origem me deu a resposta. Não só isso, também me disse outra coisa—",
  ui_story_5031_50311201_35_dialog_content = "Você é uma família de um visconde, e uma família tão feliz que você tem.",
  ui_story_5031_50311201_36_dialog_content = "No entanto, por algum motivo, você não está sentado com seu parceiro, mas ainda compartilha um forte vínculo com ele.",
  ui_story_5031_50311201_37_dialog_content = "Isso é incrível...",
  ui_story_5031_50311201_38_dialog_content = "Os ingressos estavam vendendo como pão quente, e só conseguimos lugares separados.",
  ui_story_5031_50311201_39_dialog_content = "E, seu parceiro insistiu em dar o lugar da primeira fila para você.",
  ui_story_5031_50311201_40_dialog_content = "S-Sim...",
  ui_story_5031_50311201_41_dialog_content = "O Cartão Origem deseja a vocês uma vida feliz juntos! Você pode voltar para o seu lugar agora.",
  ui_story_5031_50311201_42_dialog_content = "Poxa! Isso é incrível!!!",
  ui_story_5031_50311201_43_dialog_content = "Escolha outro! Me pegue!",
  ui_story_5031_50311201_44_dialog_content = "O tempo é passageiro. Até mesmo o Cartão de Origem deve obedecer às leis do tempo.",
  ui_story_5031_50311201_45_dialog_content = "E por favor aproveite o desempenho seguinte. Estou ansioso para o próximo cruzamento de destinos.",
  ui_story_5031_50311201_46_dialog_content = "Que performance maravilhosa do Ringmaster Jeno!",
  ui_story_5031_50311201_47_dialog_content = "Agora, por favor, aproveite o emocionante trapézio voador de Merylt, Subli e Frimet!",
  ui_story_5031_50311201_48_dialog_content = "Certo... Aqui vamos nós!",
  ui_story_5031_50311201_49_dialog_content = "Vamos deixar eles de queixo caído!",
  ui_story_5031_50311201_50_dialog_content = "Beleza!",
  ui_story_5031_50311201_51_dialog_content = "Vamos nessa!",
  ui_story_5031_50311201_52_dialog_content = "(Merylt sobe a escada e estende a mão para os outros dois.)",
  ui_story_5031_50311201_53_dialog_content = "Ei!",
  ui_story_5031_50311201_54_dialog_content = "Frimet, não me deixe cair!",
  ui_story_5031_50311201_55_dialog_content = "Subli... Você é tão pesado...",
  ui_story_5031_50311201_56_dialog_content = "(Isso foi perto! Felizmente, Frimet pegou Subli!)",
  ui_story_5031_50311201_57_dialog_content = "Eu vou em seguida!",
  ui_story_5031_50311201_58_dialog_content = "(Hein? Eles vão...?)",
  ui_story_5031_50311201_59_dialog_content = "Ei!",
  ui_story_5031_50311201_60_dialog_content = "Ali!",
  ui_story_5031_50311201_61_dialog_content = "É... ainda mais pesado agora!",
  ui_story_5031_50311201_62_dialog_content = "Funcionou!",
  ui_story_5031_50311201_63_option_content = "Surpreendente!",
  ui_story_5031_50311201_64_dialog_content = "Ohhhhhh! Isso é incrível!",
  ui_story_5031_50311201_65_dialog_content = "Th-Obrigado a todos!",
  ui_story_5031_50311201_66_dialog_content = "Você está impressionado?",
  ui_story_5031_50311201_67_dialog_content = "Muito impressionado!",
  ui_story_5031_50311201_68_dialog_content = "Foi apenas uma simples performance...",
  ui_story_5031_50311201_69_dialog_content = "Mas aceitamos de bom grado os seus aplausos!",
  ui_story_5031_50311201_70_dialog_content = "Por favor, aguarde a competição!",
  ui_story_5031_50311201_71_dialog_content = "Agradecemos pelo seu maravilhoso desempenho!",
  ui_story_5031_50311201_72_dialog_content = "Agora é hora de anunciar... A última rodada começa – AGORA!",
  ui_story_5031_50311201_73_dialog_content = "O primeiro é o Team Illumina. Gronru e Ciel irão demonstrar seus movimentos especiais!",
  ui_story_5031_50311201_74_dialog_content = "Modifiquei meu mecha com base no feedback de Gronru, apenas para este momento...",
  ui_story_5031_50311201_75_dialog_content = "Tem que funcionar, por favor!",
  ui_story_5031_50311201_76_dialog_content = "Oh! Parece que Ciel tem algo incrível preparado!",
  ui_story_5031_50311201_77_dialog_content = "...",
  ui_story_5031_50311201_78_dialog_content = "Huh? Fia? Você está bem? Por que você está tremendo?",
  ui_story_5031_50311201_79_dialog_content = "Estou tão nervoso...",
  ui_story_5031_50311201_80_dialog_content = "Está nervosa?",
  ui_story_5031_50311201_81_dialog_content = "N-De jeito nenhum!",
  ui_story_5031_50311201_82_dialog_content = "Eu sou um extrozoólogo!, de jeito nenhum eu sou... AI!",
  ui_story_5031_50311201_83_dialog_content = "Está tão nervoso que mordeu a língua?",
  ui_story_5031_50311201_84_dialog_content = "Eu não estou nervoso!",
  ui_story_5031_50311201_85_dialog_content = "Fia, apenas limpe sua mente e respire fundo.",
  ui_story_5031_50311201_86_dialog_content = "*Inalar*",
  ui_story_5031_50311201_87_dialog_content = "*Expire*",
  ui_story_5031_50311201_88_dialog_content = "Me sinto melhor agora?",
  ui_story_5031_50311201_89_dialog_content = "Oh não... não melhor. Meu coração está batendo!",
  ui_story_5031_50311201_90_dialog_content = "Ciel e Gronru parece incrível mas nem sei se a Bica vai ajudar...",
  ui_story_5031_50311201_91_dialog_content = "Não há como vencermos!",
  ui_story_5031_50311201_92_dialog_content = "Não entrar em pânico. Não adianta pensar nisso agora.",
  ui_story_5031_50311201_93_dialog_content = "Apenas se concentre no que você precisa fazer. Apenas se concentre no desempenho em si.",
  ui_story_5031_50311201_94_dialog_content = "Mas e se a Bica ainda não colaborar?",
  ui_story_5031_50311201_95_dialog_content = "Bom...",
  ui_story_5031_50311201_96_option_content = "Você já ouviu um ditado?",
  ui_story_5031_50311201_97_dialog_content = "O que dizer?",
  ui_story_5031_50311201_98_dialog_content = "Elogios podem fazer mágica!",
  ui_story_5031_50311201_99_dialog_content = "O quê?!",
  ui_story_5031_50311201_100_dialog_content = "Mais ou menos o que eu quis dizer. De qualquer forma, tente deixar a Bica feliz para ajudar.",
  ui_story_5031_50311201_101_dialog_content = "Tudo o que importa é receber o grande prêmio, seja ou não o Cloudwhale. Todas as outras preocupações são secundárias!",
  ui_story_5031_50311201_102_dialog_content = "Vou tentar!",
  ui_story_5031_50311201_103_dialog_content = "Boa sorte. Vice, Carleen, e farei o possível para ganhar pontos.",
  ui_story_5031_50311201_104_dialog_content = "Nossa pontuação final seria nossa média.",
  ui_story_5031_50311201_105_dialog_content = "Então, a melhor maneira de vencer isso é que todos nós fazemos o nosso melhor!",
  ui_story_5031_50311201_106_dialog_content = "Ah, entendi...",
  ui_story_5031_50311201_107_dialog_content = "Olhar! Foi uma atuação incrível de Gronru e Ciel!",
  ui_story_5031_50311201_108_dialog_content = "O mecha de Ciel e o trono de Gronru estão dançando em uma luz deslumbrante!",
  ui_story_5031_50311201_109_dialog_content = "O mecha de Ciel era como se não tivesse peso, realizando danças de combate com habilidades extremas!",
  ui_story_5031_50311201_110_dialog_content = "Ela traçou um equilíbrio perfeito entre peso e beleza!",
  ui_story_5031_50311201_111_dialog_content = "Agora, é a vez do Team Fia subir ao palco!",
  ui_story_5031_50311201_112_dialog_content = "Que desempenho extraordinário ela nos reserva?",
  ui_story_5031_50311201_113_dialog_content = "Ufa... Está na hora. Vamos, Bica!",
  ui_story_5031_50311201_114_dialog_content = "Oi!",
  ui_story_5031_50311201_115_dialog_content = "(Boa sorte, Fia, Bica!)",
  ui_story_5031_50311201_116_dialog_content = "(Por favor, não deixe nada dar errado desta vez...)",
  ui_story_5031_50311201_117_dialog_content = "Tudo bem! Vamos fazer isso! Bica, vem aqui!",
  ui_story_5031_50311201_118_dialog_content = "Oi!",
  ui_story_5031_50311201_119_dialog_content = "Como eu disse, Bica. Pule e dê uma cambalhota, ok?",
  ui_story_5031_50311201_120_dialog_content = "Oi oi?",
  ui_story_5031_50311201_121_dialog_content = "(Bica está olhando para Fia com um sorriso malicioso?!)",
  ui_story_5031_50311201_122_dialog_content = "Por favor... colabore!",
  ui_story_5031_50311201_123_dialog_content = "Ei?",
  ui_story_5031_50311201_124_dialog_content = "(Bica está se fazendo de burra?!)",
  ui_story_5031_50311201_125_dialog_content = "O que houve?",
  ui_story_5031_50311201_126_dialog_content = "Nós não gastamos o dinheiro para ver você desperdiçar nosso tempo!",
  ui_story_5031_50311201_127_dialog_content = "*funga*",
  ui_story_5031_50311201_128_dialog_content = "P-Por favor!",
  ui_story_5031_50311201_129_dialog_content = "Oi!",
  ui_story_5031_50311201_129X1_dialog_content = "A Bica é a melhor! Deve ser fácil para você cuidar de um caso tão pequeno!",
  ui_story_5031_50311201_130_dialog_content = "Eu compro as uvas do Sr. Peng logo depois disso!",
  ui_story_5031_50311201_131_dialog_content = "Hiya!",
  ui_story_5031_50311201_132_dialog_content = "Isso funcionou?!",
  ui_story_5031_50311201_133_dialog_content = "Oi!",
  ui_story_5031_50311201_134_dialog_content = "Ei! Faça outro!",
  ui_story_5031_50311201_135_dialog_content = "Agora, eu vou jogar essa bola. Por favor, pegue!",
  ui_story_5031_50311201_136_dialog_content = "Hiya!",
  ui_story_5031_50311201_137_dialog_content = "Oi!",
  ui_story_5031_50311201_138_dialog_content = "Bem feito!",
  ui_story_5031_50311201_139_dialog_content = "(Ótimo, a Bica está disposta a me ajudar em troca das uvas!)",
  ui_story_5031_50311201_140_dialog_content = "Ei?",
  ui_story_5031_50311201_141_dialog_content = "Ei, espere! Isso não é comida!",
  ui_story_5031_50311201_142_dialog_content = "Hahahahaha!",
  ui_story_5031_50311201_143_dialog_content = "(Isso foi perto. Pelo menos o público pensou que era parte da performance.)",
  ui_story_5031_50311201_144_dialog_content = "Agora, vamos mostrar ao público seu truque secreto, Bica!",
  ui_story_5031_50311201_145_dialog_content = "Truque secreto? Que truque secreto?",
  ui_story_5031_50311201_146_dialog_content = "Vai fazer a Bica engolir uma pedra como da última vez com o caçador?",
  ui_story_5031_50311201_147_dialog_content = "Isso é perigoso!",
  ui_story_5031_50311201_148_dialog_content = "Eu não vou fazer nada disso!",
  ui_story_5031_50311201_149_dialog_content = "Eu preparei isso!",
  ui_story_5031_50311201_150_dialog_content = "Olha!",
  ui_story_5031_50311201_151_dialog_content = "Bolhas?",
  ui_story_5031_50311201_152_dialog_content = "Oh! Quantas bolhas lindas!",
  ui_story_5031_50311201_153_dialog_content = "Mas o que isso tem a ver com domar uma fera?",
  ui_story_5031_50311201_154_dialog_content = "Agora é com a Bica!",
  ui_story_5031_50311201_155_dialog_content = "Hiya!",
  ui_story_5031_50311201_156_dialog_content = "Hai—!",
  ui_story_5031_50311201_157_dialog_content = "(Certo! As bolhas são todas esferas. Exatamente o que a Bica gosta!)",
  ui_story_5031_50311201_158_dialog_content = "Oooh! Esse carinha ainda tem esse talento?!",
  ui_story_5031_50311201_159_dialog_content = "Oi!",
  ui_story_5031_50311201_160_dialog_content = "H-Hai!",
  ui_story_5031_50311201_161_dialog_content = "*Arroto*",
  ui_story_5031_50311201_162_dialog_content = "(Bica engoliu muito ar, e seu corpo ficou inchado!)",
  ui_story_5031_50311201_163_dialog_content = "Hahahahaha! Isso é tão adorável!",
  ui_story_5031_50311201_164_dialog_content = "Isso é tudo para o nosso desempenho!",
  ui_story_5031_50311201_165_dialog_content = "Por favor, aguarde o que meus companheiros de equipe preparam para você a seguir!",
  ui_story_5031_50311201_166_dialog_content = "Uau!!!",
  ui_story_5031_50311201_167_dialog_content = "Depois que a apresentação de Fia terminou, eu, Vice, e Carleen também subiu ao palco nessa ordem.",
  ui_story_5031_50311201_168_dialog_content = "Usei minhas habilidades psíquicas para ler mentes.",
  ui_story_5031_50311201_169_dialog_content = "Vice demonstrou sua impressionante pontaria...",
  ui_story_5031_50311201_170_dialog_content = "E eu só posso esperar que ela não coloque a maçã alvo no topo da minha cabeça, da próxima vez...",
  ui_story_5031_50311201_171_dialog_content = "Carleen era o cisne negro. Ela surpreendeu a todos com seu balé.",
  ui_story_5031_50311201_172_dialog_content = "E mais... Ela até pediu para Jeno colocar Eclipsites no palco como parte de seu show!",
  ui_story_5031_50311202_1_dialog_content = "Gelescer!",
  ui_story_5031_50311202_2_dialog_content = "eu aposto Carleen é o único que já combinou balé e combate!",
  ui_story_5031_50311202_3_dialog_content = "O que é INCRÍVEL!",
  ui_story_5031_50311202_4_dialog_content = "Uma grande salva de palmas para o balé de Carleen! Isso foi emocionante e espetacular!",
  ui_story_5031_50311202_5_dialog_content = "Agora, o momento que todos estão esperando...",
  ui_story_5031_50311202_6_dialog_content = "Hora dos resultados!",
  ui_story_5031_50311202_7_dialog_content = "Oi!",
  ui_story_5031_50311202_8_dialog_content = "Estou tão nervoso... não consigo... respirar...",
  ui_story_5031_50311202_9_dialog_content = "Espera, Fia!",
  ui_story_5031_50311202_10_dialog_content = "Pense na sua Baleia Nuvem!",
  ui_story_5031_50311202_11_dialog_content = "Baleia Nuvem, sim, minha Baleia Nuvem... Meu grande prêmio!",
  ui_story_5031_50311202_12_dialog_content = "O vencedor deste concurso é...",
  ui_story_5031_50311202_13_dialog_content = "Equipe Fia!",
  ui_story_5031_50311202_14_dialog_content = "Eu ganhei...?",
  ui_story_5031_50311202_15_dialog_content = "Oh sim! Eu venci!",
  ui_story_5031_50311202_16_dialog_content = "Oi!",
  ui_story_5031_50311202_17_dialog_content = "Apesar do desempenho menos que perfeito da Fia, o trabalho em equipe entre eles é realmente impressionante.",
  ui_story_5031_50311202_18_dialog_content = "E o balé de Miss Carleen era simplesmente estelar.",
  ui_story_5031_50311202_19_dialog_content = "Assim, a pontuação média do Team Fia é alta o suficiente para garantir o primeiro lugar!",
  ui_story_5031_50311202_20_dialog_content = "Parabéns, Fia!",
  ui_story_5031_50311202_21_dialog_content = "Eu nunca soube que uma garotinha como você poderia ser tão incrível, Fia!",
  ui_story_5031_50311202_22_dialog_content = "Você me derrotou, mas não vou perder para você da próxima vez!",
  ui_story_5031_50311202_23_dialog_content = "Parabéns, Fia! Você termina o desempenho e ganha uma vitória!",
  ui_story_5031_50311202_24_dialog_content = "Mas estou muito curioso. Qual é exatamente o grande prêmio?",
  ui_story_5031_50311202_25_dialog_content = "Poderia realmente ser o Cloudwhale que Fia estava procurando?",
  ui_story_5031_50311202_26_dialog_content = "Certo! Meu grande prêmio, o único tesouro das profundezas do mar!",
  ui_story_5031_50311202_27_dialog_content = "É claro. Eu tenho o prêmio comigo.",
  ui_story_5031_50311202_28_dialog_content = "Aqui está.",
  ui_story_5031_50311202_29_dialog_content = "Ei! Lo, lo, lo!",
  ui_story_5031_50311202_30_dialog_content = "O que?! E-não é isso... KYLLO?!",
  ui_story_5031_50311202_31_dialog_content = "Eu não te mandei para o mar para rastrear o Cloudwhale?",
  ui_story_5031_50311202_32_dialog_content = "Não é à toa que nunca tive notícias suas! Você esteve relaxando todo esse tempo!",
  ui_story_5031_50311202_33_dialog_content = "Eu capturei este animal do mar não muito tempo atrás.",
  ui_story_5031_50311202_34_dialog_content = "Parece delicioso, então pretendo transformá-lo em uma sopa de frutos do mar para o vencedor.",
  ui_story_5031_50311202_35_dialog_content = "Lo, lo, lo? Ei!",
  ui_story_5031_50311202_36_dialog_content = "Você não pode cozinhar Kyllo!",
  ui_story_5031_50311202_37_dialog_content = "É meu amigo!",
  ui_story_5031_50311202_38_dialog_content = "Um amigo? E eu pensei que era algum ingrediente alimentar raro e delicioso.",
  ui_story_5031_50311202_39_dialog_content = "Bem, você é o vencedor, e é o seu prêmio. Vou deixar para você.",
  ui_story_5031_50311202_40_dialog_content = "Lo, lo...",
  ui_story_5031_50311202_41_dialog_content = "Ufa, sua coisinha descuidada! Você sabe que quase morreu?",
  ui_story_5031_50311202_42_dialog_content = "Ei... Ei, ei!",
  ui_story_5031_50311202_43_dialog_content = "Huh? Você disse que foi pego em uma rede enquanto procurava o Cloudwhale no fundo do mar?",
  ui_story_5031_50311202_44_dialog_content = "E você ficou preso no navio por dias?",
  ui_story_5031_50311202_45_dialog_content = "Então... Você viu o Cloudwhale no navio?",
  ui_story_5031_50311202_46_dialog_content = "Lo? Ei, ei!",
  ui_story_5031_50311202_47_dialog_content = "Não? Que triste...",
  ui_story_5031_50311202_48_dialog_content = "Agora que o vencedor foi anunciado, por favor, todos venham para o baralho?",
  ui_story_5031_50311202_49_dialog_content = "O banquete e os fogos de artifício estão prestes a começar.",
  ui_story_5031_50311202_50_dialog_content = "Você disse fogos de artifício? Vamos nos apressar e conseguir um bom lugar!",
  ui_story_5031_50311202_51_dialog_content = "Nada de Baleia Nuvem... Por que o grande prêmio não é Baleia Nuvem?!",
  ui_story_5031_50311202_52_dialog_content = "Tanto trabalho para nada!",
  ui_story_5031_50311202_53_dialog_content = "Como pode ser uma baleia?",
  ui_story_5031_50311202_54_dialog_content = "A Esmeralda não será capaz de lidar com isso, mesmo que estejamos falando apenas de filhote de baleia.",
  ui_story_5031_50311202_55_dialog_content = "Estou certo em supor que você nunca viu uma baleia, mocinha?",
  ui_story_5031_50311202_56_dialog_content = "E-e se eu nunca vi um?!",
  ui_story_5031_50311202_57_dialog_content = "É um exótico. É normal que eu não tenha visto um antes...",
  ui_story_5031_50311202_58_dialog_content = "Pfft...",
  ui_story_5031_50311202_59_dialog_content = "Não é engraçado! Pare de rir!",
  ui_story_5031_50311202_60_dialog_content = "Tudo bem, tudo bem. Não foi tudo por nada, você sabe.",
  ui_story_5031_50311202_61_option_content = "Nós ganhamos o concurso",
  ui_story_5031_50311202_62_dialog_content = "Fia e Bica agora também são amigas, não é mesmo?",
  ui_story_5031_50311202_63_dialog_content = "Oi!",
  ui_story_5031_50311202_64_dialog_content = "A-Tudo bem! Eu vou te comprar uvas!",
  ui_story_5031_50311202_65_option_content = "Pelo menos você salvou Kyllo.",
  ui_story_5031_50311202_66_dialog_content = "Ei, ei!",
  ui_story_5031_50311202_67_dialog_content = "Infelizmente... Eu só não esperava que o grande prêmio fosse Kyllo.",
  ui_story_5031_50311202_68_dialog_content = "Já que você foi capturado por acidente, então é melhor você voltar a procurar o Cloudwhale.",
  ui_story_5031_50311202_69_dialog_content = "Lo?",
  ui_story_5031_50311202_70_dialog_content = "Não preciso da sua ajuda aqui. Tudo bem, tudo bem, vá em frente!",
  ui_story_5031_50311202_71_dialog_content = "Deixe-me dar-lhe uma mão e lançá-lo no mar, então!",
  ui_story_5031_50311202_72_dialog_content = "Lo—!",
  ui_story_5031_50311202_73_dialog_content = "(Kyllo se torna uma estrela cadente que risca o céu... Fia é tão aterrorizante!)",
  ui_story_5031_50311202_74_dialog_content = "Hmm... Você é mesmo um extrozoologista?",
  ui_story_5031_50311202_75_dialog_content = "É claro que sim!",
  ui_story_5031_50311202_76_dialog_content = "Mas como funcionou sua adivinhação, Jeno?",
  ui_story_5031_50311202_77_dialog_content = "Você também é um celestita que possui habilidades psíquicas?",
  ui_story_5031_50311202_78_dialog_content = "Isso não era adivinhação, não realmente. Foram todas as minhas habilidades de observação.",
  ui_story_5031_50311202_79_dialog_content = "Lembra daquela senhora? Seu vestido pode parecer nada fora do comum à primeira vista, mas o tecido é específico para Petyaburg.",
  ui_story_5031_50311202_80_dialog_content = "Quanto a sua vida amorosa... o anel em seu dedo me disse que ela é casada.",
  ui_story_5031_50311202_81_dialog_content = "E, a maneira como ela continuou olhando para trás significava que ela provavelmente não estava sentada com seu parceiro.",
  ui_story_5031_50311202_82_dialog_content = "Acabei de juntar tudo e...",
  ui_story_5031_50311202_83_dialog_content = "Desculpe a intromissão, Jeno, mas há algo que preciso falar com você, em particular, perto do palco.",
  ui_story_5031_50311202_84_dialog_content = "Claro.",
  ui_story_5031_50311202_85_dialog_content = "Desculpe, todos. Eu volto já.",
  ui_story_5031_50311202_86_dialog_content = "Ei! Pelo menos termine sua frase!",
  ui_story_5031_50311202_87_dialog_content = "Nossa, acabei de sair de uma conversa dessas.",
  ui_story_5031_50311202_88_dialog_content = "Os fogos de artifício começaram!",
  ui_story_5031_50311202_89_dialog_content = "Isso é realmente lindo.",
  ui_story_5031_50311202_90_dialog_content = "Então aí está você!",
  ui_story_5031_50311202_91_dialog_content = "E-Todo mundo está aqui...",
  ui_story_5031_50311202_92_dialog_content = "Rainbow, o que há com essa tigela de comida no colo? Você vai levá-lo de volta para comer?",
  ui_story_5031_50311202_93_dialog_content = "Você não vai se juntar a nós?",
  ui_story_5031_50311202_94_dialog_content = "Eu tenho outros planos!",
  ui_story_5031_50311202_95_dialog_content = "Claro, os fogos de artifício são lindos, mas Ciel e eu tivemos uma ótima ideia de como modificar nosso mecha!",
  ui_story_5031_50311202_96_dialog_content = "Mal podemos esperar para começar a trabalhar nisso!",
  ui_story_5031_50311202_97_dialog_content = "Sim...",
  ui_story_5031_50311202_98_dialog_content = "Desculpe por não podermos passar um tempo com você esta noite.",
  ui_story_5031_50311202_99_dialog_content = "Ah, não se preocupe com isso. Temos muito tempo no futuro!",
  ui_story_5031_50311202_100_dialog_content = "Iremos então!",
  ui_story_5031_50311202_101_dialog_content = "Eles parecem muito próximos. Tenho um pouco de inveja deles.",
  ui_story_5031_50311202_102_dialog_content = "Está faltando alguma coisa, Carleen?",
  ui_story_5031_50311202_103_dialog_content = "Você tem eu e PlayerName!",
  ui_story_5031_50311202_104_dialog_content = "Sim, estivemos viajando e nos mantendo juntos durante todo esse tempo!",
  ui_story_5031_50311202_105_dialog_content = "Exatamente. Assim como desta vez!",
  ui_story_5031_50311202_106_dialog_content = "Teríamos perdido se não fosse pelo seu balé extraordinário que nos rendeu tantos pontos!",
  ui_story_5031_50311202_107_dialog_content = "Isso mesmo! É tudo graças a você!",
  ui_story_5031_50311202_108_dialog_content = "Então não comece a agir como um estranho, você!",
  ui_story_5031_50311202_109_dialog_content = "É assim mesmo...? Tudo bem, tudo bem.",
  ui_story_5031_50311202_110_dialog_content = "Obrigado.",
  ui_story_5031_50311202_111_dialog_content = "Sim!",
  ui_story_5031_50311301_1_dialog_content = "Eu não percebi isso mais cedo durante o dia, mas se você olhar de perto, Harbour City realmente parece encantadora à noite sob os fogos de artifício.",
  ui_story_5031_50311301_2_dialog_content = "Sim. Seus prédios brancos foram pintados pelos radiantes fogos de artifício. É ainda mais charmoso do que durante o dia!",
  ui_story_5031_50311301_3_dialog_content = "PlayerName, Vice, e Fia. Eu quero ir falar com Elvis.",
  ui_story_5031_50311301_4_dialog_content = "Você poderia, por favor, esperar por mim um pouco?",
  ui_story_5031_50311301_5_dialog_content = "Coisa certa! Estaremos bem aqui.",
  ui_story_5031_50311301_6_dialog_content = "Tudo bem. Obrigado.",
  ui_story_5031_50311301_7_dialog_content = "Parece que finalmente acabou...",
  ui_story_5031_50311301_8_dialog_content = "Mas ainda não encontrei meu Cloudwhale...",
  ui_story_5031_50311301_9_dialog_content = "Agora, onde poderia estar a lendária Baleia Nuvem...?",
  ui_story_5031_50311301_10_dialog_content = "Não seja precipitado. Algumas coisas você simplesmente não pode ter pressa.",
  ui_story_5031_50311301_11_dialog_content = "Isso mesmo. Como às vezes, quanto mais eu estava com pressa para encontrar meus grampos de cabelo depois de acordar, mais difícil era encontrá-los.",
  ui_story_5031_50311301_12_dialog_content = "Mas quando finalmente desisti, percebi que estava ao meu lado o tempo todo!",
  ui_story_5031_50311301_13_dialog_content = "Sério?",
  ui_story_5031_50311301_14_dialog_content = "De nada.",
  ui_story_5031_50311301_15_dialog_content = "Tudo bem, eu vou confiar em você desta vez.",
  ui_story_5031_50311301_16_dialog_content = "Oi pessoal.",
  ui_story_5031_50311301_17_dialog_content = "Carleen? Você teve uma conversa rápida?",
  ui_story_5031_50311301_18_dialog_content = "Não, de jeito nenhum. Não consegui encontrar Elvis em lugar nenhum.",
  ui_story_5031_50311301_19_dialog_content = "Ele não arrastou Jeno para conversar no palco?",
  ui_story_5031_50311301_20_dialog_content = "Passei por lá, mas não os vi.",
  ui_story_5031_50311301_21_dialog_content = "Elvis e Jeno...",
  ui_story_5031_50311301_22_dialog_content = "Eles poderiam estar indo para a cabana?",
  ui_story_5031_50311301_23_dialog_content = "Cabine? Jeno nunca deixou ninguém chegar perto disso, não é?",
  ui_story_5031_50311301_24_dialog_content = "Mas se eles não estão em nenhum outro lugar, provavelmente é onde eles estão.",
  ui_story_5031_50311301_25_dialog_content = "Vamos verificar. Deve haver pessoas que saibam para onde foram.",
  ui_story_5031_50311301_26_dialog_content = "Como você conhece bem o caminho para a cabine, PlayerName?",
  ui_story_5031_50311301_27_dialog_content = "Porque Fia e eu fomos perseguidos por Elvis e Patou aqui por um longo tempo.",
  ui_story_5031_50311301_28_dialog_content = "Elvis e Patou? Como isso aconteceu?",
  ui_story_5031_50311301_29_dialog_content = "Para encurtar a história, nós...",
  ui_story_5031_50311301_30_dialog_content = "Olha, PlayerName, tem alguém no chão ali!",
  ui_story_5031_50311301_31_dialog_content = "Isso é... Jeno?!",
  ui_story_5031_50311301_32_dialog_content = "Sério? Você me desenharia um retrato?",
  ui_story_5031_50311301_33_dialog_content = "Sim, mas eu desenho devagar e não muito bom, também.",
  ui_story_5031_50311301_34_dialog_content = "Está bem. Seus desenhos são os melhores para mim!",
  ui_story_5031_50311301_35_dialog_content = "Bem... Acho que te vejo amanhã de manhã no porto?",
  ui_story_5031_50311301_36_dialog_content = "Desenhe para mim depois do seu trabalho à beira-mar, e eu farei uma sopa de frutos do mar para você!",
  ui_story_5031_50311301_37_dialog_content = "Uau, sopa de frutos do mar de Elvis!",
  ui_story_5031_50311301_38_dialog_content = "Incrível! É um acordo, então!",
  ui_story_5031_50311301_39_dialog_content = "Te vejo amanhã!",
  ui_story_5031_50311301_40_dialog_content = "S-até amanhã!",
  ui_story_5031_50311301_41_dialog_content = "...",
  ui_story_5031_50311301_42_dialog_content = "...",
  ui_story_5031_50311301_43_dialog_content = "Tínhamos uma promessa.",
  ui_story_5031_50311301_44_dialog_content = "Tínhamos uma promessa...",
  ui_story_5031_50311301_45_dialog_content = "<size=33>Je...</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>Jeno...</size>",
  ui_story_5031_50311301_47_dialog_content = "Quem está aí?",
  ui_story_5031_50311301_48_dialog_content = "Jeno!",
  ui_story_5031_50311301_49_dialog_content = "Elvis? Isso é você? Você voltou?",
  ui_story_5031_50311301_50_dialog_content = "<size=45>Acorda, Jeno!</size>",
  ui_story_5031_50311301_51_dialog_content = "Elvis!",
  ui_story_5031_50311301_52_dialog_content = "Ahhhh!",
  ui_story_5031_50311301_53_dialog_content = "Ahhhh!",
  ui_story_5031_50311301_54_dialog_content = "Por que você está gritando, PlayerName? Você me assustou!",
  ui_story_5031_50311301_55_dialog_content = "D-Desculpe, eu estava com medo também.",
  ui_story_5031_50311301_56_dialog_content = "Como você está se sentindo, Jeno? Você está machucado?",
  ui_story_5031_50311301_57_dialog_content = "O que... O que estou fazendo aqui?",
  ui_story_5031_50311301_58_dialog_content = "Não deveríamos estar lhe perguntando isso?",
  ui_story_5031_50311301_59_dialog_content = "Por que você está dormindo aqui? Nós estivemos procurando por você.",
  ui_story_5031_50311301_60_dialog_content = "Uh, Fia, isso claramente não é \"dormir\"...",
  ui_story_5031_50311301_61_dialog_content = "Aqui está a coisa. Os fogos de artifício e a celebração terminaram, então queríamos dizer adeus a Laird Elvis.",
  ui_story_5031_50311301_62_dialog_content = "Mas não conseguimos encontrá-lo em lugar nenhum, então pensamos que vocês dois poderiam estar na cabana.",
  ui_story_5031_50311301_63_dialog_content = "Aproveitamos a chance apenas para ver que você estava deitado aqui, inconsciente.",
  ui_story_5031_50311301_64_dialog_content = "Bem, eu... Ai.",
  ui_story_5031_50311301_65_dialog_content = "Ninguém vai nos perturbar aqui. O que você quer dizer, Elvis?",
  ui_story_5031_50311301_66_dialog_content = "Eu só... eu só quero dizer obrigado, Jeno.",
  ui_story_5031_50311301_67_dialog_content = "... Huh? Isso veio do nada.",
  ui_story_5031_50311301_68_dialog_content = "Para que?",
  ui_story_5031_50311301_69_dialog_content = "Obrigado por aceitar meu convite e dar ao povo de Harbour City uma lembrança tão maravilhosa.",
  ui_story_5031_50311301_70_dialog_content = "Para mim, sua presença é... muito significativa.",
  ui_story_5031_50311301_71_dialog_content = "Não é grande coisa. Vagamos por toda parte, então não faz diferença onde trabalhamos.",
  ui_story_5031_50311301_72_dialog_content = "Além disso, você nos pagou mais do que o suficiente. Nesse caso, devemos expressar nossa gratidão.",
  ui_story_5031_50311301_73_dialog_content = "Não, Jeno.",
  ui_story_5031_50311301_74_dialog_content = "Jamais poderei retribuir o que devo.",
  ui_story_5031_50311301_75_dialog_content = "Gratidão a mim? O que você está falando-",
  ui_story_5031_50311301_76_dialog_content = "Argh!",
  ui_story_5031_50311301_77_dialog_content = "Desculpe.",
  ui_story_5031_50311301_78_dialog_content = "Tosse, tosse... O que diabos...",
  ui_story_5031_50311301_79_dialog_content = "Esse é...?",
  ui_story_5031_50311301_80_dialog_content = "Jeno... Sinto muito.",
  ui_story_5031_50311301_81_dialog_content = "Quer dizer que Laird Elvis drogou você?",
  ui_story_5031_50311301_82_dialog_content = "Uhum.",
  ui_story_5031_50311301_83_dialog_content = "Espere, Elvis é um cara mau?",
  ui_story_5031_50311301_84_dialog_content = "Não tire conclusões precipitadas, Fia. Ainda não sabemos a verdade.",
  ui_story_5031_50311301_85_dialog_content = "<size=33>Maldições, acabou...</size>",
  ui_story_5031_50311301_86_dialog_content = "O que há de errado, Jeno? O que você está procurando...",
  ui_story_5031_50311301_87_dialog_content = "Uau! O que está acontecendo?",
  ui_story_5031_50311301_88_dialog_content = "O navio... está balançando?",
  ui_story_5031_50311301_89_dialog_content = "... Nunca pensei que ele se rebaixaria a isso.",
  ui_story_5031_50311301_90_dialog_content = "Espere, Jeno!",
  ui_story_5031_50311301_91_dialog_content = "Je-Jeno... Huff, puff...",
  ui_story_5031_50311301_92_dialog_content = "Importa-se de explicar o que está acontecendo?",
  ui_story_5031_50311301_93_dialog_content = "...",
  ui_story_5031_50311301_94_dialog_content = "Eu estou no meu juízo final.",
  ui_story_5031_50311301_95_dialog_content = "Se ele conseguir ativar aquela COISA, precisarei de todos vocês para ajudar.",
  ui_story_5031_50311301_96_dialog_content = "Aquela coisa?",
  ui_story_5031_50311301_97_dialog_content = "Acabei de descobrir que a chave da câmara central da nave que eu carregava está faltando.",
  ui_story_5031_50311301_98_dialog_content = "Há algo importante naquela sala?",
  ui_story_5031_50311301_99_dialog_content = "o <color=#FFB400>Núcleo de Energia</color>.",
  ui_story_5031_50311301_100_dialog_content = "Núcleo de energia?",
  ui_story_5031_50311301_101_dialog_content = "Como é que todos vocês parecem saber exatamente o que é isso?",
  ui_story_5031_50311301_102_dialog_content = "O núcleo de energia é uma criação de civilizações antigas. Pense nisso como um recurso precioso.",
  ui_story_5031_50311301_103_dialog_content = "Nunca imaginei que haveria um no navio...",
  ui_story_5031_50311301_104_dialog_content = "Porque este navio veio originalmente de uma antiga ruína.",
  ui_story_5031_50311301_105_dialog_content = "E a COISA a que me referi é uma arma antiga que guarda o núcleo de energia...",
  ui_story_5031_50311301_106_dialog_content = "<color=#FFB400>Guardião do Núcleo</color>.",
  ui_story_5031_50311301_107_dialog_content = "Quando o Core Guardian é ativado, ele atacará qualquer forma de vida que se aproxime do núcleo de energia indiscriminadamente.",
  ui_story_5031_50311301_108_dialog_content = "Isso significa que todo o navio está em perigo.",
  ui_story_5031_50311301_109_dialog_content = "Então você está dizendo que Laird Elvis tirou a chave quando você desmaiou.",
  ui_story_5031_50311301_110_dialog_content = "E agora ele entrou na câmara do núcleo, tentando capturar o núcleo de energia?",
  ui_story_5031_50311301_111_dialog_content = "Muito provavelmente, mas...",
  ui_story_5031_50311301_112_dialog_content = "Jeno!",
  ui_story_5031_50311301_113_dialog_content = "É Rainbow e Ciel!",
  ui_story_5031_50311301_114_dialog_content = "Jeno, acabamos de receber o alerta de que a câmara do núcleo foi aberta!",
  ui_story_5031_50311301_115_dialog_content = "Eu sei. Estamos indo para lá agora mesmo.",
  ui_story_5031_50311301_116_dialog_content = "No caminho, notamos que os guardas mercenários também estavam desmaiados...",
  ui_story_5031_50311301_117_dialog_content = "Cuidado, Rainbow!",
  ui_story_5031_50311301_118_dialog_content = "Ah! Essa foi por pouco. Obrigado, Ciel.",
  ui_story_5031_50311301_119_dialog_content = "Huh? Estes são... Guardas da Cidade do Porto?",
  ui_story_5031_50311301_120_dialog_content = "Eles foram designados para nos atrasar?",
  ui_story_5031_50311301_121_dialog_content = "...",
  ui_story_5031_50311301_122_dialog_content = "Saia do caminho, seu servo tolo!",
  ui_story_5031_50311302_1_dialog_content = "Quando Elvis...",
  ui_story_5031_50311302_2_dialog_content = "Desde quando essas pessoas entraram na cabine?",
  ui_story_5031_50311302_3_dialog_content = "Eu posso sentir outro fluxo de Lumina se aproximando!",
  ui_story_5031_50311302_4_dialog_content = "É muito mais do que temos aqui agora...",
  ui_story_5031_50311302_5_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5031_50311302_6_dialog_content = "Argh! Meu navio!",
  ui_story_5031_50311302_7_dialog_content = "O que aquele Elvis está fazendo com minha nave?!",
  ui_story_5031_50311302_8_dialog_content = "Não poderíamos fazer nada além de ficar presos aqui se isso continuar.",
  ui_story_5031_50311302_9_dialog_content = "Todo mundo está em apuros...",
  ui_story_5031_50311302_10_dialog_content = "Eu tenho que fazer isso!",
  ui_story_5031_50311302_11_dialog_content = "Atualização do status do mecanismo de braço—Tipo III.",
  ui_story_5031_50311302_12_dialog_content = "Atualização do status do mecanismo de perna - Tipo III.",
  ui_story_5031_50311302_13_dialog_content = "Aumente a produção de energia em 70%.",
  ui_story_5031_50311302_14_dialog_content = "O quê?",
  ui_story_5031_50311302_15_dialog_content = "O que você está fazendo, Ciel? Seu mecha ainda não foi totalmente testado!",
  ui_story_5031_50311302_16_dialog_content = "Vou mantê-los ocupados enquanto vocês vão para a câmara central.",
  ui_story_5031_50311302_17_dialog_content = "Mas...",
  ui_story_5031_50311302_18_dialog_content = "Não esquenta!",
  ui_story_5031_50311302_19_dialog_content = "Fizemos as calibrações juntos, lembra? Styx vai ficar bem!",
  ui_story_5031_50311302_20_dialog_content = "Ciel está certo, Rainbow.",
  ui_story_5031_50311302_21_dialog_content = "Não podemos passar muito tempo aqui.",
  ui_story_5031_50311302_22_dialog_content = "Devemos confiar em nossos companheiros... Deixe isso para Ciel.",
  ui_story_5031_50311302_23_dialog_content = "Carleen...",
  ui_story_5031_50311302_24_dialog_content = "(Carleen realmente mudou.)",
  ui_story_5031_50311302_25_dialog_content = "...",
  ui_story_5031_50311302_26_dialog_content = "Não se divirta muito e destrua o mecha, Ciel!",
  ui_story_5031_50311302_27_dialog_content = "Caso contrário, você nunca pode me pagar de volta!",
  ui_story_5031_50311302_28_dialog_content = "A-ahn?!",
  ui_story_5031_50311302_29_dialog_content = "Ok, não se preocupe.",
  ui_story_5031_50311302_30_dialog_content = "Você tem isso, Ciel.",
  ui_story_5031_50311302_31_dialog_content = "Cuidado, Ciel!",
  ui_story_5031_50311302_32_dialog_content = "Não queremos pegar uma garota. É melhor você fugir agora.",
  ui_story_5031_50311302_33_dialog_content = "Eu sou mais do que suficiente para enfrentar todos vocês.",
  ui_story_5031_50311302_34_dialog_content = "Bem, se é assim que você quer.",
  ui_story_5031_50311302_35_dialog_content = "Hmm, eles são mais resistentes e têm mais pessoas.",
  ui_story_5031_50311302_36_dialog_content = "Nesse caso terei que...",
  ui_story_5031_50311302_37_dialog_content = "Aumente a produção de energia em 80%.",
  ui_story_5031_50311302_38_dialog_content = "Puxa... Seu poder de fogo melhorou de novo?",
  ui_story_5031_50311302_39_dialog_content = "Este mecha é como um monstro.",
  ui_story_5031_50311302_40_dialog_content = "Mas para o laird, não cairemos.",
  ui_story_5031_50311302_41_dialog_content = "Esquadrão 1! Mantenha sua formação e pressione com seus escudos Lumina!",
  ui_story_5031_50311302_42_dialog_content = "Ela acabou se ela está fora daquele mecha!",
  ui_story_5031_50311302_43_dialog_content = "Sim, senhor!",
  ui_story_5031_50311302_44_dialog_content = "Seus escudos ficaram mais duráveis quando empilhados em um?",
  ui_story_5031_50311302_45_dialog_content = "Prepare-se para as armas Lumina, Esquadrão 2!",
  ui_story_5031_50311302_46_dialog_content = "Oh, não, se eu não posso quebrar este escudo e deixá-los chegar perto...",
  ui_story_5031_50311302_47_dialog_content = "Ok, tenho que se acalmar, respirar...",
  ui_story_5031_50311302_48_dialog_content = "Pode ser mais difícil, mas Lumina é a chave se funcionar com energia.",
  ui_story_5031_50311302_49_dialog_content = "Então eu só tenho que liberar mais Lumina do que ele faz.",
  ui_story_5031_50311302_50_dialog_content = "Mas Styx já caiu uma vez hoje...",
  ui_story_5031_50311302_51_dialog_content = "Se eu aumentar a saída, Styx pode...",
  ui_story_5031_50311302_52_dialog_content = "Eu me decidi. Vou ajudar muito as pessoas depois de construir um mecha dinâmico!",
  ui_story_5031_50311302_53_dialog_content = "Oh? Então, o que você mais quer fazer com isso, Ciel?",
  ui_story_5031_50311302_54_dialog_content = "Bem eu acho...",
  ui_story_5031_50311302_55_dialog_content = "Eu acho...",
  ui_story_5031_50311302_56_dialog_content = "Vou ajudar e proteger meus amigos e ser confiável!",
  ui_story_5031_50311302_57_dialog_content = "Desculpe, Rainbow. Desculpe, Styx!",
  ui_story_5031_50311302_58_dialog_content = "<size=45>Aumente a produção de energia em 100%!</size>",
  ui_story_5031_50311302_59_dialog_content = "O que? O escudo está quebrado! Mas como...",
  ui_story_5031_50311302_60_dialog_content = "Ela deve ser um monstro!",
  ui_story_5031_50311302_61_dialog_content = "Huff... puff...",
  ui_story_5031_50311302_62_dialog_content = "Parece que foi um grande esforço...",
  ui_story_5031_50311302_63_dialog_content = "Não apenas os circuitos das pernas estão falhando, mas o Lumina também está ...",
  ui_story_5031_50311302_64_dialog_content = "Não recues!",
  ui_story_5031_50311302_65_dialog_content = "Não importa se o escudo se foi. Ela só tem tanta energia!",
  ui_story_5031_50311302_66_dialog_content = "Podemos deixar uma garota segurar todos nós?!",
  ui_story_5031_50311302_67_dialog_content = "... Sim senhor!",
  ui_story_5031_50311302_68_dialog_content = "Huff... eu não vou deixar você passar...",
  ui_story_5031_50311302_69_dialog_content = "Sua ofensa está diminuindo. Agora é a hora!",
  ui_story_5031_50311302_70_dialog_content = "Ainda não pode vencer apesar de sua superioridade de números. Tem certeza de que é o melhor de Harbour City?",
  ui_story_5031_50311302_71_dialog_content = "Isso soa como...",
  ui_story_5031_50311302_72_dialog_content = "Ah!",
  ui_story_5031_50311302_73_dialog_content = "E-é ele!",
  ui_story_5031_50311302_74_dialog_content = "Ufa, eu não disse para você não se divertir muito?",
  ui_story_5031_50311302_75_dialog_content = "Styx está parecendo pior para o desgaste! Caramba, eu perdi uma tarde inteira consertando isso!",
  ui_story_5031_50311302_76_dialog_content = "É você, Rainbow! Por que você está de volta?",
  ui_story_5031_50311302_77_dialog_content = "Porque estou preocupado com você.",
  ui_story_5031_50311302_78_dialog_content = "Mas e a câmara central?",
  ui_story_5031_50311302_79_dialog_content = "Jeno e os caras estão nisso.",
  ui_story_5031_50311302_80_dialog_content = "Tut, como te atreves a atacar-me?",
  ui_story_5031_50311302_81_dialog_content = "Argh!",
  ui_story_5031_50311302_82_dialog_content = "...",
  ui_story_5031_50311302_83_dialog_content = "Hum? O que há de errado, Ciel? Por que você parece assim?",
  ui_story_5031_50311302_84_dialog_content = "... Isso faz sentido.",
  ui_story_5031_50311302_85_dialog_content = "Alguém se envergonhando como eu não tem o direito de falar sobre confiança e confiabilidade.",
  ui_story_5031_50311302_86_dialog_content = "Se você não voltou para mim, eu provavelmente...",
  ui_story_5031_50311302_87_dialog_content = "...",
  ui_story_5031_50311302_88_dialog_content = "Você é meio bobo às vezes, Ciel.",
  ui_story_5031_50311302_89_dialog_content = "O quê?",
  ui_story_5031_50311302_90_dialog_content = "Mas eu gosto do seu bobo!",
  ui_story_5031_50311302_91_dialog_content = "Eu confio em você, e é por isso que eu sei que você se esforçaria 100% para nos cobrir.",
  ui_story_5031_50311302_92_dialog_content = "Mas ninguém sabe em que condições Styx está melhor do que nós. Estou ciente de como isso terminaria, e aqui vou eu.",
  ui_story_5031_50311302_93_dialog_content = "...",
  ui_story_5031_50311302_94_dialog_content = "Também confio em Jeno e acredito que eles defenderão a Esmeralda.",
  ui_story_5031_50311302_95_dialog_content = "Então fique tranquilo.",
  ui_story_5031_50311302_96_dialog_content = "Quando tudo acabar, vou enfeitar Styx com você.",
  ui_story_5031_50311302_97_dialog_content = "Vamos torná-lo inteligente, robusto e não quebrar mesmo com 300% de saída!",
  ui_story_5031_50311302_98_dialog_content = "... Tá bem.",
  ui_story_5031_50311302_99_dialog_content = "Mas temos que nos livrar desses incômodos primeiro.",
  ui_story_5031_50311302_100_dialog_content = "Vamos. Você lança ataques furtivos mesmo quando está em grande número nos superando.",
  ui_story_5031_50311302_101_dialog_content = "Você não tem vergonha?",
  ui_story_5031_50311302_102_dialog_content = "...",
  ui_story_5031_50311401_1_dialog_content = "*Tosse*",
  ui_story_5031_50311401_2_dialog_content = "Bem, tudo pronto para ir agora.",
  ui_story_5031_50311401_3_dialog_content = "Só esperando a última peça se encaixar.",
  ui_story_5031_50311401_4_dialog_content = "Passos se aproximando, senhor.",
  ui_story_5031_50311401_5_dialog_content = "Tudo bem, deixe-os vir. Você deve deixar o navio de acordo com o plano e impedir que qualquer outra pessoa se aproxime.",
  ui_story_5031_50311401_6_dialog_content = "...",
  ui_story_5031_50311401_7_dialog_content = "O que foi?",
  ui_story_5031_50311401_8_dialog_content = "Tem certeza, senhor?",
  ui_story_5031_50311401_9_dialog_content = "Eu não deveria deixar você sozinho...",
  ui_story_5031_50311401_10_dialog_content = "Você fez o seu trabalho. Devo enfrentar o que vem a seguir sozinho.",
  ui_story_5031_50311401_11_dialog_content = "...",
  ui_story_5031_50311401_12_dialog_content = "Ou você não acredita em mim, Patou?",
  ui_story_5031_50311401_13_dialog_content = "Eu certamente acredito em você! Você sabe que não foi isso que eu quis dizer.",
  ui_story_5031_50311401_14_dialog_content = "Se você fizer isso, saia agora. Você só vai estragar o plano ficando aqui.",
  ui_story_5031_50311401_15_dialog_content = "Não se preocupe. Tudo está sob meu controle até agora.",
  ui_story_5031_50311401_16_dialog_content = "Lembre-se do que eu disse... Não entre, não importa o que você ouça.",
  ui_story_5031_50311401_17_dialog_content = "... Sim.",
  ui_story_5031_50311401_18_dialog_content = "Por favor tome cuidado.",
  ui_story_5031_50311401_19_dialog_content = "Elvis!",
  ui_story_5031_50311401_20_dialog_content = "Oh? Não é Rainbow e Ciel, mas Sua Alteza e vocês?",
  ui_story_5031_50311401_21_dialog_content = "Mas tudo bem. Você está apenas um pouco mais tarde do que eu pensava.",
  ui_story_5031_50311401_22_dialog_content = "Tudo estava pronto, mas você ainda não apareceu, então eu estava preocupado se aqueles homens realmente pararam você.",
  ui_story_5031_50311401_23_dialog_content = "Ele está nos esperando pelo jeito que falou...?",
  ui_story_5031_50311401_24_dialog_content = "Não vejo Patou. Eu me pergunto o que tem na manga.",
  ui_story_5031_50311401_25_dialog_content = "Independentemente disso, vamos ter cuidado.",
  ui_story_5031_50311401_26_dialog_content = "Uhum.",
  ui_story_5031_50311401_27_dialog_content = "Isso é... o núcleo de energia ao lado dele?",
  ui_story_5031_50311401_28_dialog_content = "Deveria ser. Eu posso sentir uma energia forte e incomum dele.",
  ui_story_5031_50311401_29_dialog_content = "Mas como ele vai levar algo tão grande com ele?",
  ui_story_5031_50311401_30_dialog_content = "Ouça-me, Elvis.",
  ui_story_5031_50311401_31_dialog_content = "Eu não sei o que você planejou fazer com o núcleo de energia.",
  ui_story_5031_50311401_32_dialog_content = "Mas sei que seu objetivo final é proteger as pessoas de Harbour City da Síndrome de Modali.",
  ui_story_5031_50311401_33_dialog_content = "O que você está fazendo agora, no entanto, só colocará a cidade em perigo.",
  ui_story_5031_50311401_34_dialog_content = "Quando o núcleo de energia sair do seu modo normal, ele acordará...",
  ui_story_5031_50311401_35_dialog_content = "Seu Guardião.",
  ui_story_5031_50311401_36_dialog_content = "...",
  ui_story_5031_50311401_37_dialog_content = "Você sabe disso?",
  ui_story_5031_50311401_38_dialog_content = "Você também encontrará as informações de que precisa, depois de ler todos os livros deste mundo.",
  ui_story_5031_50311401_39_dialog_content = "Arma robótica: Core Guardian.",
  ui_story_5031_50311401_40_dialog_content = "Um produto de civilizações antigas, com poder suficiente para destruir uma pequena cidade.",
  ui_story_5031_50311401_41_dialog_content = "Quando o núcleo de energia falha, o Core Guardian é ativado.",
  ui_story_5031_50311401_42_dialog_content = "Se esta operação continuar, não só causará o ataque do Guardião, mas poderá resultar na autodestruição do núcleo.",
  ui_story_5031_50311401_43_dialog_content = "É por isso que vocês, pessoas da Verdadeira Ordem, nunca poderiam colocar suas mãos neste núcleo de energia, certo?",
  ui_story_5031_50311401_44_dialog_content = "...",
  ui_story_5031_50311401_45_dialog_content = "Verdadeira Ordem...?",
  ui_story_5031_50311401_46_dialog_content = "Você está com True Order, Jeno?",
  ui_story_5031_50311401_47_dialog_content = "... É uma longa história. Minha compreensão do núcleo realmente veio de The True Order, mas isso não é importante.",
  ui_story_5031_50311401_48_dialog_content = "Vamos deixar o assunto com Jeno e True Order de lado por enquanto.",
  ui_story_5031_50311401_49_dialog_content = "Se você sabe tanto sobre isso, Elvis, por que ainda faria algo que poderia colocar em perigo as pessoas de Harbour City?",
  ui_story_5031_50311401_50_dialog_content = "Colocar em perigo o povo de Harbour City?",
  ui_story_5031_50311401_51_dialog_content = "Não, não, Alteza, não sou como aqueles velhos nobres mimados de Lumopolis.",
  ui_story_5031_50311401_52_dialog_content = "Eu nunca brincaria com a vida do meu povo.",
  ui_story_5031_50311401_53_dialog_content = "Eu tenho minhas razões para fazer isso.",
  ui_story_5031_50311401_54_dialog_content = "Mas eu acho que você nunca vai conseguir descobrir.",
  ui_story_5031_50311401_55_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_5031_50311401_56_dialog_content = "O que é esse barulho? Tão alto e irritante!",
  ui_story_5031_50311401_57_dialog_content = "Caramba... O que você fez, Elvis?",
  ui_story_5031_50311401_58_dialog_content = "Já que todos os convidados estão presentes, posso colocar o show na estrada.",
  ui_story_5031_50311401_59_dialog_content = "Admiro seu caráter, Alteza, mas estou mais inclinado a fazer qualquer coisa pelo futuro de Harbour City.",
  ui_story_5031_50311401_60_dialog_content = "Se você quer guardar rancor, que seja apenas por mim.",
  ui_story_5031_50311401_61_dialog_content = "O selo não é mais estável, então devo salvar a cidade de qualquer maneira que puder.",
  ui_story_5031_50311401_62_dialog_content = "Olha, a gema em seu cetro está brilhando!",
  ui_story_5031_50311401_63_dialog_content = "Aquela jóia...",
  ui_story_5031_50311401_64_dialog_content = "Está absorvendo energia do núcleo!",
  ui_story_5031_50311401_65_dialog_content = "Ah, você pode até sentir isso, Caelestite?",
  ui_story_5031_50311401_66_dialog_content = "Bem, acho que isso significa que não posso deixar nenhum de vocês vivo.",
  ui_story_5031_50311401_67_dialog_content = "Mas eu estava planejando, de qualquer maneira.",
  ui_story_5031_50311401_68_dialog_content = "\"Atividade incomum detectada.\"",
  ui_story_5031_50311401_69_dialog_content = "\"Defesa automática ativada. Em análise do sistema.\"",
  ui_story_5031_50311401_70_dialog_content = "Ei, aquele robô enorme pendurado embaixo daquele grande bloco está se movendo!",
  ui_story_5031_50311401_71_dialog_content = "Ah, o pior aconteceu.",
  ui_story_5031_50311401_72_dialog_content = "O Guardião do Núcleo está prestes a ser despertado...",
  ui_story_5031_50311401_73_dialog_content = "Cuidado, pessoal.",
  ui_story_5031_50311401_74_dialog_content = "\"Identificação de energia: Lumina.\"",
  ui_story_5031_50311401_75_dialog_content = "\"Análise: Alvos hostis.\"",
  ui_story_5031_50311401_76_dialog_content = "\"Conclusão: inicie o modo de ataque.\"",
  ui_story_5031_50311401_77_dialog_content = "Sua energia está amplificando!",
  ui_story_5031_50311401_78_dialog_content = "Fique atrás de mim, Fia!",
  ui_story_5031_50311401_79_dialog_content = "Oh, tudo bem!",
  ui_story_5031_50311402_1_dialog_content = "Vice, Jeno, vou atacar pela retaguarda esquerda.",
  ui_story_5031_50311402_2_dialog_content = "Eu preciso que você adie o avanço do Guardião do Núcleo!",
  ui_story_5031_50311402_3_dialog_content = "Sim!",
  ui_story_5031_50311402_4_dialog_content = "Cuidado com o aglomerado de energia em seu braço direito, Vice!",
  ui_story_5031_50311402_5_dialog_content = "Está prestes a atacar!",
  ui_story_5031_50311402_6_dialog_content = "Ok, entendi!",
  ui_story_5031_50311402_7_dialog_content = "Gelescer!",
  ui_story_5031_50311402_8_dialog_content = "\"Casco atingido.\"",
  ui_story_5031_50311402_9_dialog_content = "\"Comece a avaliar os danos.\"",
  ui_story_5031_50311402_10_dialog_content = "Uau, o grande robô não está se movendo!",
  ui_story_5031_50311402_11_dialog_content = "Você é incrível, Carleen!",
  ui_story_5031_50311402_12_dialog_content = "Não exatamente. Sua energia ainda está funcionando normalmente dentro dele.",
  ui_story_5031_50311402_13_dialog_content = "Você é muito competente, superando até minha expectativa.",
  ui_story_5031_50311402_14_dialog_content = "Embora eu tenha ouvido muito sobre o que PlayerName pode fazer, mas ver para crer.",
  ui_story_5031_50311402_15_dialog_content = "É uma pena, porém...",
  ui_story_5031_50311402_16_dialog_content = "Que seu esforço será em vão.",
  ui_story_5031_50311402_17_dialog_content = "\"Avaliação completa, sem danos graves.\"",
  ui_story_5031_50311402_18_dialog_content = "\"Atualize os dados do inimigo, ajuste a produção de dano.\"",
  ui_story_5031_50311402_19_dialog_content = "O que é isto...?",
  ui_story_5031_50311402_20_dialog_content = "Carleen, está acumulando energia massiva no peito. Pato!",
  ui_story_5031_50311402_21_dialog_content = "Argh!",
  ui_story_5031_50311402_22_dialog_content = "Essa foi por pouco.",
  ui_story_5031_50311402_23_dialog_content = "Você tá bem, Carleen?",
  ui_story_5031_50311402_24_dialog_content = "Estou bem. Graças ao aviso do PlayerName, é apenas um arranhão.",
  ui_story_5031_50311402_25_dialog_content = "Bom, porque o poder que acabou de liberar é horrível...",
  ui_story_5031_50311402_26_dialog_content = "Metade das paredes da sala derreteu.",
  ui_story_5031_50311402_27_dialog_content = "O poder das armas de civilizações antigas é realmente assustador.",
  ui_story_5031_50311402_28_dialog_content = "Vamos cercá-lo e encontrar um ponto fraco.",
  ui_story_5031_50311402_29_dialog_content = "Sim. Tenha cuidado também.",
  ui_story_5031_50311402_30_dialog_content = "Você sabe, você notou algo estranho?",
  ui_story_5031_50311402_31_dialog_content = "O que foi?",
  ui_story_5031_50311402_32_dialog_content = "Por que o Guardião está apenas nos atacando?",
  ui_story_5031_50311402_33_dialog_content = "Elvis está obviamente de pé ao lado do núcleo e sugando sua energia.",
  ui_story_5031_50311402_34_dialog_content = "Isso é verdade.",
  ui_story_5031_50311402_35_dialog_content = "Porque o Guardião...",
  ui_story_5031_50311402_36_dialog_content = "...",
  ui_story_5031_50311402_37_dialog_content = "Você sabe por quê, Jeno?",
  ui_story_5031_50311402_38_dialog_content = "Não, nada.",
  ui_story_5031_50311402_39_dialog_content = "Por que você não terminou o que estava dizendo?",
  ui_story_5031_50311402_40_dialog_content = "Você ainda se importa com meus sentimentos mesmo agora?",
  ui_story_5031_50311402_41_dialog_content = "Ainda é o mesmo você, Jeno.",
  ui_story_5031_50311402_42_dialog_content = "Está bem. Já estou acostumado, pode cuspir.",
  ui_story_5031_50311402_43_dialog_content = "Elvis...",
  ui_story_5031_50311402_44_dialog_content = "Diga a eles que é porque o Guardião reconhece os inimigos através do Lumina.",
  ui_story_5031_50311402_45_dialog_content = "Mas para mim, com toda a minha Lumina absorvida...",
  ui_story_5031_50311402_46_dialog_content = "Não sou nada mais do que um cadáver.",
  ui_story_5031_50311402_47_dialog_content = "L-Lumina absorvido?",
  ui_story_5031_50311402_48_dialog_content = "Isso explica porque eu não conseguia sentir Lumina em Elvis.",
  ui_story_5031_50311402_49_dialog_content = "Achei que era por causa da doença dele.",
  ui_story_5031_50311402_50_dialog_content = "É o contrário. Perder Lumina levou à doença.",
  ui_story_5031_50311402_51_dialog_content = "A síndrome de Modali é na verdade uma doença resultante da perda de Lumina por um longo período de tempo.",
  ui_story_5031_50311402_52_dialog_content = "As vítimas vivem com a dor de Lumina constantemente deixando seus corpos. Casos graves até...",
  ui_story_5031_50311402_53_dialog_content = "Então, a solução é pegar o núcleo de energia?",
  ui_story_5031_50311402_54_dialog_content = "Não tenho certeza dos detalhes, mas essa é a essência do plano dele.",
  ui_story_5031_50311402_55_dialog_content = "Ouça-me, Elvis.",
  ui_story_5031_50311402_56_dialog_content = "Mesmo que você obtenha o núcleo de energia, você não pode controlar o Guardião.",
  ui_story_5031_50311402_57_dialog_content = "Depois que descermos, ele voltará sua atenção para você e para Harbour City.",
  ui_story_5031_50311402_58_dialog_content = "Tem que haver outra maneira. Podemos...",
  ui_story_5031_50311402_59_dialog_content = "Não há outro jeito, Jeno.",
  ui_story_5031_50311402_60_dialog_content = "Estou procurando uma solução desde que testemunhei pela primeira vez meu povo morrendo da doença.",
  ui_story_5031_50311402_61_dialog_content = "Tentei todas as opções possíveis ao longo dos anos, mesmo quando as chances de sucesso eram quase nulas.",
  ui_story_5031_50311402_62_dialog_content = "Mas tudo o que resta é decepção e um corpo em declínio.",
  ui_story_5031_50311402_63_dialog_content = "Eu devo terminá-lo mesmo que o tempo esteja acabando para mim.",
  ui_story_5031_50311402_64_dialog_content = "Mas...",
  ui_story_5031_50311402_65_dialog_content = "Pare de falar, Jeno. O Guardião está vindo em sua direção!",
  ui_story_5031_50311402_66_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5031_50311402_67_dialog_content = "Jeno!",
  ui_story_5031_50311402_68_dialog_content = "Cof, cof.",
  ui_story_5031_50311402_69_dialog_content = "Estou bem...",
  ui_story_5031_50311402_70_dialog_content = "Graças a Deus, isso me assustou...",
  ui_story_5031_50311402_71_dialog_content = "Isso é baixo, Elvis!",
  ui_story_5031_50311402_72_dialog_content = "Você distraiu Jeno sob o pretexto de uma conversa!",
  ui_story_5031_50311402_73_dialog_content = "Não, você não entendeu, Srta. Fia.",
  ui_story_5031_50311402_74_dialog_content = "Essa não é minha intenção. Pelo contrário, preciso de todos vocês...",
  ui_story_5031_50311402_75_dialog_content = "Você precisa de nós para manter o Guardião ocupado enquanto você absorve a energia, certo?",
  ui_story_5031_50311402_76_dialog_content = "Muito astuto de sua parte, Alteza.",
  ui_story_5031_50311402_77_dialog_content = "Quanto ao Guardião do Núcleo, posso revelar algumas informações, já que você está tão preocupado com as pessoas de Harbour City.",
  ui_story_5031_50311402_78_dialog_content = "A diferença entre True Order e eu é que eu tenho algo que eles não têm.",
  ui_story_5031_50311402_79_dialog_content = "Posso ligar o núcleo de energia ao meu sangue e controlá-lo.",
  ui_story_5031_50311402_80_dialog_content = "Assim que eu terminar de absorver o núcleo de energia, o Guardião também me obedecerá.",
  ui_story_5031_50311402_81_dialog_content = "Assim, você pode descansar em paz com este navio no fundo do oceano, sabendo que meu povo está seguro.",
  ui_story_5031_50311402_82_dialog_content = "Você decidiu nos matar então, Laird Elvis.",
  ui_story_5031_50311402_83_dialog_content = "Sinto muito, mas não posso arriscar que o Conselho dos Anciões descubra isso.",
  ui_story_5031_50311402_84_dialog_content = "Bem, acho que não temos mais nada para discutir.",
  ui_story_5031_50311402_85_dialog_content = "Mas se você teve boas intenções, não vou deixar você machucar meus amigos.",
  ui_story_5031_50311402_86_dialog_content = "Jeno, as ilusões que você conjura carregavam seu Lumina, certo?",
  ui_story_5031_50311402_87_dialog_content = "De uma vez só.",
  ui_story_5031_50311402_88_dialog_content = "Quantas imagens dos soldados você pode projetar?",
  ui_story_5031_50311402_89_dialog_content = "Eu provavelmente poderia controlar mais de dez ao mesmo tempo.",
  ui_story_5031_50311402_90_dialog_content = "Você tem um plano, Carleen?",
  ui_story_5031_50311402_91_dialog_content = "Eu gostaria que você, Vice, e Jeno, para manter o Guardião ocupado para mim.",
  ui_story_5031_50311402_92_dialog_content = "Retornar o núcleo de energia de volta ao normal é o pré-requisito para desativar o Guardião.",
  ui_story_5031_50311402_93_dialog_content = "Isso deve esclarecer nosso objetivo.",
  ui_story_5031_50311402_94_dialog_content = "Vou impedir que Elvis absorva o núcleo de energia.",
  ui_story_5031_50311501_1_dialog_content = "Torrente Rápida!",
  ui_story_5031_50311501_2_dialog_content = "Certo, temos a atenção do Guardião.",
  ui_story_5031_50311501_3_dialog_content = "Agora, Carleen!",
  ui_story_5031_50311501_4_dialog_content = "Faça isso rápido. Não posso manter todas essas ilusões por muito tempo.",
  ui_story_5031_50311501_5_dialog_content = "Tudo bem, obrigado!",
  ui_story_5031_50311501_6_dialog_content = "*Cof Cof*",
  ui_story_5031_50311501_7_dialog_content = "Eu não esperaria nada menos de você, senhora Carleen.",
  ui_story_5031_50311501_8_dialog_content = "Nem conhecendo Jeno um dia e ainda descobri como usar seu poder para distrair o Guardião.",
  ui_story_5031_50311501_9_dialog_content = "Uma mente altamente tática, juntamente com as habilidades de PlayerName...",
  ui_story_5031_50311501_10_dialog_content = "Estou feliz por nunca ter subestimado você desde o início.",
  ui_story_5031_50311501_11_dialog_content = "Argh!",
  ui_story_5031_50311501_12_dialog_content = "O que há de errado, Carleen?!",
  ui_story_5031_50311501_13_dialog_content = "Eu... não consigo... me mexer...",
  ui_story_5031_50311501_14_dialog_content = "Meu poder está se esgotando...",
  ui_story_5031_50311501_15_dialog_content = "Fique aqui e não vá a lugar nenhum, Fia!",
  ui_story_5031_50311501_16_dialog_content = "Mas esse robô vai te matar, PlayerName!",
  ui_story_5031_50311501_17_dialog_content = "Ei, como é que o robô não reagiu?",
  ui_story_5031_50311501_18_dialog_content = "Carleen!",
  ui_story_5031_50311501_19_dialog_content = "PlayerName...",
  ui_story_5031_50311501_20_dialog_content = "(O Lumina em Carleen está drenando rápido!)",
  ui_story_5031_50311501_21_dialog_content = "Droga…",
  ui_story_5031_50311501_22_dialog_content = "<size=45>O que você fez, Elvis?!</size>",
  ui_story_5031_50311501_23_dialog_content = "Não é bom tirar Lumina de você, não é?",
  ui_story_5031_50311501_24_dialog_content = "Como contingência, coloquei um <color=#FFB400>precaução de segurança</color> em Sua Alteza.",
  ui_story_5031_50311501_25_dialog_content = "Precaução de segurança? Quando?",
  ui_story_5031_50311501_26_dialog_content = "É a roupa que ela está vestindo?",
  ui_story_5031_50311501_27_dialog_content = "Correto.",
  ui_story_5031_50311501_28_dialog_content = "Quando você me perguntou como entrar na cabine, eu sabia que poderia chegar a isso.",
  ui_story_5031_50311501_29_dialog_content = "A roupa dela foi especialmente projetada.",
  ui_story_5031_50311501_30_dialog_content = "Quando o <color=#FFB400>Lumothread</color> é ativado, ele adere ao usuário e absorve rapidamente o Lumina.",
  ui_story_5031_50311501_31_dialog_content = "Portanto, é melhor ela não usar Lumina.",
  ui_story_5031_50311501_32_dialog_content = "Você...!",
  ui_story_5031_50311501_33_dialog_content = "Me desculpe... eu o subestimei...",
  ui_story_5031_50311501_34_dialog_content = "Não é sua culpa. Você deve...",
  ui_story_5031_50311501_35_dialog_content = "Cuidado, Jeno!",
  ui_story_5031_50311501_36_dialog_content = "Hã?!",
  ui_story_5031_50311501_37_dialog_content = "Você está bem, Jeno?",
  ui_story_5031_50311501_38_dialog_content = "Ai! Meu braço...",
  ui_story_5031_50311501_39_dialog_content = "Eu não posso movê-lo.",
  ui_story_5031_50311501_40_dialog_content = "Não se mova. Você está sangrando!",
  ui_story_5031_50311501_41_dialog_content = "\"Inimigo ferido. Modo de perseguição ativado.\"",
  ui_story_5031_50311501_42_dialog_content = "O Guardião está avançando em sua direção, Vice!",
  ui_story_5031_50311501_43_dialog_content = "Ah não, é muito rápido!",
  ui_story_5031_50311501_44_dialog_content = "É tarde demais para eu atirar!",
  ui_story_5031_50311501_45_dialog_content = "Pare... Ugh!",
  ui_story_5031_50311501_46_dialog_content = "J-Jeno?",
  ui_story_5031_50311501_47_dialog_content = "...",
  ui_story_5031_50311501_48_dialog_content = "Ele desmaiou.",
  ui_story_5031_50311501_49_dialog_content = "Oh não, o que vamos fazer agora?",
  ui_story_5031_50311501_50_dialog_content = "Ah sim, eu ainda tenho isso!",
  ui_story_5031_50311501_51_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5031_50311501_52_dialog_content = "\"?\"",
  ui_story_5031_50311501_53_dialog_content = "Peguei vocês! Felizmente eu ainda tenho o mestre de armas que me deu!",
  ui_story_5031_50311501_54_dialog_content = "Como você gosta disso, robô?",
  ui_story_5031_50311501_55_dialog_content = "\"Sob ataque desconhecido, dano sofrido: 0.\"",
  ui_story_5031_50311501_56_dialog_content = "\"A Target não gastou Lumina. Análise: Eliminação prioritária.\"",
  ui_story_5031_50311501_57_dialog_content = "Uaaau! Por que está me cobrando agora?!",
  ui_story_5031_50311501_58_dialog_content = "Aaaah!",
  ui_story_5031_50311501_59_dialog_content = "Fia!",
  ui_story_5031_50311501_60_dialog_content = "...",
  ui_story_5031_50311501_61_dialog_content = "Estamos acabados se isso continuar.",
  ui_story_5031_50311501_62_dialog_content = "Eu sou o único que resta agora, então não entre em pânico.",
  ui_story_5031_50311501_63_dialog_content = "Eu tenho que parar Elvis primeiro para parar o Guardian.",
  ui_story_5031_50311501_64_dialog_content = "...",
  ui_story_5031_50311501_65_dialog_content = "Deite-se um pouco, Carleen, e não use Lumina novamente.",
  ui_story_5031_50311501_66_dialog_content = "O que você está fazendo, PlayerName?",
  ui_story_5031_50311501_67_dialog_content = "Eu vou parar Elvis.",
  ui_story_5031_50311501_68_dialog_content = "Eu acho que é hora de eu colocar o treinamento de Sinsa e outros para bom uso.",
  ui_story_5031_50311501_69_dialog_content = "Mas...",
  ui_story_5031_50311501_70_dialog_content = "Relaxe, Carleen.",
  ui_story_5031_50311501_71_dialog_content = "Posso não ter Lumina, mas contra um homem doentio como Elvis...",
  ui_story_5031_50311501_72_dialog_content = "Eu não vou perder.",
  ui_story_5031_50311501_73_dialog_content = "Tenha muito cuidado.",
  ui_story_5031_50311501_74_dialog_content = "Discurso muito emocionante. Impressionante.",
  ui_story_5031_50311501_75_dialog_content = "Mas chamar alguém de homem doente é incrivelmente rude.",
  ui_story_5031_50311501_76_dialog_content = "Corte o absurdo.",
  ui_story_5031_50311501_77_dialog_content = "Cale a boca e-",
  ui_story_5031_50311501_78_dialog_content = "Descer!",
  ui_story_5031_50311501_79_dialog_content = "Hehe.",
  ui_story_5031_50311501_80_dialog_content = "<size=45>PlayerName! Atenção!</size>",
  ui_story_5031_50311501_81_dialog_content = "\"Alternando a prioridade do comando, substituindo o comando padrão. Mudar de destino.\"",
  ui_story_5031_50311501_82_dialog_content = "Eca!!",
  ui_story_5031_50311501_83_dialog_content = "PlayerName!",
  ui_story_5031_50311501_84_dialog_content = "Não é possível...",
  ui_story_5031_50311501_85_dialog_content = "Isto é impossível...",
  ui_story_5031_50311501_86_dialog_content = "Você chegou tão perto, PlayerName.",
  ui_story_5031_50311501_87_dialog_content = "Pena que absorvi toda a energia do núcleo.",
  ui_story_5031_50311501_88_dialog_content = "Agora, estou no controle do Core Guardian.",
  ui_story_5031_50311501_89_dialog_content = "Caso contrário, alguém sem Lumina como você seria realmente um incômodo.",
  ui_story_5031_50311501_90_dialog_content = "\"Comando de prioridade mais alta atualizado, comutado para o modo de controle manual.\"",
  ui_story_5031_50311501_91_dialog_content = "\"Sistema de autodefesa desligado.\"",
  ui_story_5031_50311501_92_dialog_content = "(Isso machuca!)",
  ui_story_5031_50311501_93_dialog_content = "(Não consigo sentir minhas pernas.)",
  ui_story_5031_50311501_94_dialog_content = "Deixe-me ver, o único que ainda pode se mover é...",
  ui_story_5031_50311501_95_dialog_content = "Senhorita Vice, Eu acho.",
  ui_story_5031_50311501_96_dialog_content = "Vá acabar com ela, e então iremos para o próximo local.",
  ui_story_5031_50311501_97_dialog_content = "\"Novo comando recebido. Alvo de comutação.\"",
  ui_story_5031_50311501_98_dialog_content = "(Não, Vice!)",
  ui_story_5031_50311501_99_dialog_content = "<size=33>Corre, Vice...</size>",
  ui_story_5031_50311501_100_dialog_content = "Oh? Ainda pode ficar de pé, hein?",
  ui_story_5031_50311501_101_dialog_content = "<size=33>Hã?</size>",
  ui_story_5031_50311501_102_dialog_content = "Eu respeito você, por ainda ser capaz de tanta força nessas circunstâncias.",
  ui_story_5031_50311501_103_dialog_content = "No entanto – e perdoe-me por minha franqueza – isso apenas acelerará sua morte.",
  ui_story_5031_50311501_104_dialog_content = "<size=33>Carleen...?</size>",
  ui_story_5031_50311501_105_dialog_content = "É tudo por minha causa...",
  ui_story_5031_50311501_106_dialog_content = "Sua Alteza?",
  ui_story_5031_50311501_107_dialog_content = "É tudo... por minha causa...",
  ui_story_5031_50311501_108_dialog_content = "Ah, ela está delirando de perder Lumina...",
  ui_story_5031_50311501_109_dialog_content = "Muito louvável como você ainda está tentando proteger seus amigos quando está em um estado tão triste.",
  ui_story_5031_50311501_110_dialog_content = "\"Novo alvo detectado. Iniciar ataque?\"",
  ui_story_5031_50311501_111_dialog_content = "Não há necessidade. Ela não é uma ameaça.",
  ui_story_5031_50311501_112_dialog_content = "<size=45>Pare com isso, Carleen!</size>",
  ui_story_5031_50311501_113_dialog_content = "(Droga, eu não posso nem fazer um som.)",
  ui_story_5031_50311501_114_dialog_content = "(Eu tenho que fazer alguma coisa...)",
  ui_story_5031_50311501_115_option_content = "Controle forçado!",
  ui_story_5031_50311501_116_dialog_content = "O que você está preparado para fazer se um dia sua cidade for atacada pelo Eclipsite?",
  ui_story_5031_50311501_117_dialog_content = "(É aquele... Schwartz?)",
  ui_story_5031_50311501_118_dialog_content = "(Isso é um sonho? É porque Carleen está prestes a perder a consciência?)",
  ui_story_5031_50311501_119_dialog_content = "Eu imediatamente montaria um exército para defendê-lo.",
  ui_story_5031_50311501_120_dialog_content = "E se uma força Eclipsite passar pela sua defesa?",
  ui_story_5031_50311501_121_dialog_content = "Eu correria com tropas de reserva.",
  ui_story_5031_50311501_122_dialog_content = "E então Eclipsites que cavaram um túnel subterrâneo emergem no centro da cidade.",
  ui_story_5031_50311501_123_dialog_content = "Eu ordenaria aos soldados que se mantivessem firmes, e então eu...",
  ui_story_5031_50311501_124_dialog_content = "Agora a muralha está começando a cair.",
  ui_story_5031_50311501_125_dialog_content = "...",
  ui_story_5031_50311501_126_dialog_content = "Eu derrotaria todos os Eclipsitas.",
  ui_story_5031_50311501_127_dialog_content = "Você e eu sabemos que eles não podem ser eliminados.",
  ui_story_5031_50311501_128_dialog_content = "...",
  ui_story_5031_50311501_129_dialog_content = "Parece-me que você ainda está longe de se tornar um excelente governante...",
  ui_story_5031_50311501_130_dialog_content = "Lumopolis ainda não pode depender de você.",
  ui_story_5031_50311501_131_dialog_content = "F-Pai?",
  ui_story_5031_50311501_132_dialog_content = "Eu mandei você para Northland para estudar sob Bethlehem, mas não vejo evidência de progresso.",
  ui_story_5031_50311501_133_dialog_content = "Sua força é insuficiente e você não tem poder mental.",
  ui_story_5031_50311501_134_dialog_content = "É por isso que você perdeu seus amigos.",
  ui_story_5031_50311501_135_dialog_content = "Eles se machucaram, até morreram, tudo por sua causa, Alteza.",
  ui_story_5031_50311501_136_dialog_content = "E-eu...",
  ui_story_5031_50311501_137_dialog_content = "Eu confiei em você, e eu segui seu plano de batalha, Carleen.",
  ui_story_5031_50311501_138_dialog_content = "Mas o que isso me trouxe?",
  ui_story_5031_50311501_139_dialog_content = "PlayerName e eu estamos prestes a morrer por sua causa.",
  ui_story_5031_50311501_140_dialog_content = "Eu sinto Muito, Vice...",
  ui_story_5031_50311501_141_dialog_content = "Foco, Carleen, isso não é Vice!",
  ui_story_5031_50311501_142_dialog_content = "É aquele...",
  ui_story_5031_50311501_143_dialog_content = "PlayerName?",
  ui_story_5031_50311501_144_dialog_content = "Sim, sou eu!",
  ui_story_5031_50311501_145_dialog_content = "Desculpe por nunca perceber quanto conflito interno você estava enfrentando, Carleen.",
  ui_story_5031_50311501_146_dialog_content = "Mas Vice nunca diria isso. O que você está vendo não é real, mas ilusões!",
  ui_story_5031_50311501_147_dialog_content = "Você está tentando fugir de suas responsabilidades?",
  ui_story_5031_50311501_148_dialog_content = "Que pena. Continue falando como você protegerá os outros quando estiver realmente fraco.",
  ui_story_5031_50311501_149_dialog_content = "Você não foi feito para governar.",
  ui_story_5031_50311501_150_dialog_content = "Eu...",
  ui_story_5031_50311501_151_dialog_content = "Escute-me, Carleen.",
  ui_story_5031_50311501_152_dialog_content = "Você não precisa carregar o peso de ser governante o tempo todo!",
  ui_story_5031_50311501_153_dialog_content = "Para mim e Vice, você é Carleen e somente Carleen!",
  ui_story_5031_50311501_154_dialog_content = "Milímetros?",
  ui_story_5031_50311501_154X1_dialog_content = "Você se lembra daquela coisa Vice disse, Carleen?",
  ui_story_5031_50311501_154X2_dialog_content = "Você não deve ceder à sua obsessão!",
  ui_story_5031_50311501_154X3_dialog_content = "Minha obsessão...",
  ui_story_5031_50311501_154X4_dialog_content = "Eu estava em tal sono durante o processo. Achei que nunca fosse acordar.",
  ui_story_5031_50311501_154X5_dialog_content = "Continuei pensando no antigo eu, com medo de me perder se relaxasse mesmo por um segundo.",
  ui_story_5031_50311501_154X6_dialog_content = "Também vi muitas coisas maravilhosas, como se estivesse lá.",
  ui_story_5031_50311501_154X7_dialog_content = "Essas ilusões pareciam tão reais, como um teste para mim.",
  ui_story_5031_50311501_154X8_dialog_content = "Felizmente, agarrei-me a um brilho na consciência e preservei até o fim.",
  ui_story_5031_50311501_154X9_dialog_content = "Brilho? Lembro que você mencionou. O que foi isso?",
  ui_story_5031_50311501_154X10_dialog_content = "Hum... Pensei nas coisas divertidas que fiz com você e PlayerName.",
  ui_story_5031_50311501_154X11_dialog_content = "E antes que eu percebesse, havia silêncio dentro de mim.",
  ui_story_5031_50311501_154X12_dialog_content = "Sim, Carleen, não desista e não se perca!",
  ui_story_5031_50311501_155_dialog_content = "Lutamos juntos e recuamos juntos.",
  ui_story_5031_50311501_156_dialog_content = "Nós sempre teremos as costas um do outro.",
  ui_story_5031_50311501_157_dialog_content = "Não o responsabilizamos quando estamos em apuros.",
  ui_story_5031_50311501_158_dialog_content = "Você não precisa nos proteger sozinho.",
  ui_story_5031_50311501_159_dialog_content = "Devemos estar trabalhando em equipe e enfrentando problemas como uma equipe!",
  ui_story_5031_50311501_160_dialog_content = "PlayerName...",
  ui_story_5031_50311501_161_dialog_content = "Aconteça o que acontecer, Vice e eu nunca iria culpá-lo!",
  ui_story_5031_50311501_162_dialog_content = "Então se recomponha, Carleen! Não se deixe enganar pelas ilusões!",
  ui_story_5031_50311501_163_dialog_content = "O Real Vice não desistiu e continua lutando por nós.",
  ui_story_5031_50311501_164_dialog_content = "Ela precisa de você!",
  ui_story_5031_50311501_165_dialog_content = "...",
  ui_story_5031_50311501_166_dialog_content = "Você está certo, PlayerName.",
  ui_story_5031_50311501_167_dialog_content = "Meus amigos ainda estão brigando, como posso perder tempo me deprimindo?",
  ui_story_5031_50311501_168_dialog_content = "Então, você só vai ignorar o erro que cometeu?",
  ui_story_5031_50311501_169_dialog_content = "É óbvio que sua subestimação e incompetência...",
  ui_story_5031_50311501_170_dialog_content = "Levou à situação atual.",
  ui_story_5031_50311501_171_dialog_content = "Sim, mas não serei prisioneiro das minhas próprias decisões, certas ou erradas.",
  ui_story_5031_50311501_172_dialog_content = "...",
  ui_story_5031_50311501_173_dialog_content = "Porque isso não tem sentido. Se eu errar...",
  ui_story_5031_50311501_174_dialog_content = "Vou me esforçar para corrigi-lo.",
  ui_story_5031_50311501_175_dialog_content = "Se foi assim que você definiu o \"jeito do governante\"...",
  ui_story_5031_50311501_176_dialog_content = "Espero que você permaneça inflexível nessa crença.",
  ui_story_5031_50311501_176X1_dialog_content = "Pode deixar.",
  ui_story_5031_50311501_176X2_dialog_content = "Porque eu...",
  ui_story_5031_50311501_176X3_dialog_content = "Eu descobri que algo que eu posso segurar.",
  ui_story_5031_50311501_177_dialog_content = "Ah, a imagem é...",
  ui_story_5031_50311501_178_dialog_content = "Desculpe mantê-lo esperando, Vice.",
  ui_story_5031_50311501_179_dialog_content = "Carleen!",
  ui_story_5031_50311501_180_dialog_content = "\"Aviso: Massive Lumina detectado, nível de ameaça alto.\"",
  ui_story_5031_50311501_181_dialog_content = "\"Elimine o alvo imediatamente.\"",
  ui_story_5031_50311501_182_dialog_content = "Brilho Esplêndido!",
  ui_story_5031_50311501_183_dialog_content = "O que você está pensando?",
  ui_story_5031_50311501_184_dialog_content = "Mas o <color=#FFB400>Lumothread</color> ainda está absorvendo sua Lumina?!",
  ui_story_5031_50311501_185_dialog_content = "Carleen está tomando banho em Lumina!",
  ui_story_5031_50311501_186_dialog_content = "O que está acontecendo aqui?",
  ui_story_5031_50311501_187_dialog_content = "Dúvidas desnecessárias e ansiedade só servirão para diminuir.",
  ui_story_5031_50311501_188_dialog_content = "Uma batalha está sempre mudando. Deve-se focar no que está acontecendo, não no medo interno.",
  ui_story_5031_50311501_189_dialog_content = "Eu agora vou lutar a batalha com você, Vice.",
  ui_story_5031_50311501_190_dialog_content = "Você está bem fisicamente, Carleen?",
  ui_story_5031_50311501_191_dialog_content = "Não sei por que, mas estou sentindo uma energia ininterrupta.",
  ui_story_5031_50311501_192_dialog_content = "Independentemente disso, eu tenho apenas um objetivo agora...",
  ui_story_5031_50311501_193_dialog_content = "E isso é derrotar o inimigo com você.",
  ui_story_5031_50311501_194_dialog_content = "Direita!",
  ui_story_5031_50311501_195_dialog_content = "\"Aviso: Massive Lumina detectado, nível de ameaça super alto.\"",
  ui_story_5031_50311501_196_dialog_content = "\"Ativando o modo de confronto.\"",
  ui_story_5031_50311502_1_dialog_content = "\"Aviso... Dano no casco acima de 70%.\"",
  ui_story_5031_50311502_2_dialog_content = "\"Braço direito desconectado e não pode ser reparado automaticamente.\"",
  ui_story_5031_50311502_3_dialog_content = "Você está aguentando bem, Vice?",
  ui_story_5031_50311502_4_dialog_content = "Sim. A supressão de longo alcance não vai me gastar muita energia!",
  ui_story_5031_50311502_5_dialog_content = "Certo, vamos concentrar o fogo à sua direita.",
  ui_story_5031_50311502_6_dialog_content = "O braço direito está abaixado, então isso afetará seu ataque e defesa.",
  ui_story_5031_50311502_7_dialog_content = "Sim!",
  ui_story_5031_50311502_8_dialog_content = "Devo dizer que você superou minhas expectativas, Carleen.",
  ui_story_5031_50311502_9_dialog_content = "Admiro isso, mesmo estando em lados opostos.",
  ui_story_5031_50311502_10_dialog_content = "No entanto, tenho razões para não falhar.",
  ui_story_5031_50311502_11_dialog_content = "Portanto, por favor, desculpe-me por não ficar para ver o final desta performance.",
  ui_story_5031_50311502_12_dialog_content = "Você não vai a lugar nenhum, Elvis!",
  ui_story_5031_50311502_13_dialog_content = "Pare-os.",
  ui_story_5031_50311502_14_dialog_content = "Tenha cuidado, Vice, não vire as costas para o Guardião!",
  ui_story_5031_50311502_15_dialog_content = "Aaai!",
  ui_story_5031_50311502_16_dialog_content = "...",
  ui_story_5031_50311502_17_dialog_content = "Ratos, ele fugiu.",
  ui_story_5031_50311502_18_dialog_content = "Está bem. Vamos descobrir quando terminarmos aqui.",
  ui_story_5031_50311502_19_dialog_content = "Você tem razão.",
  ui_story_5031_50311502_20_dialog_content = "Agora, o problema do Guardião.",
  ui_story_5031_50311502_21_dialog_content = "Então, devemos... Hmm?",
  ui_story_5031_50311502_22_dialog_content = "O que é isso, Carleen?",
  ui_story_5031_50311502_23_dialog_content = "(Lumina de Carleen ficou mais forte?)",
  ui_story_5031_50311502_24_dialog_content = "Esta roupa não está mais sugando meu Lumina.",
  ui_story_5031_50311502_25_dialog_content = "É porque Elvis foi embora?",
  ui_story_5031_50311502_26_dialog_content = "Isso explicaria por que você estava bem nisso antes.",
  ui_story_5031_50311502_27_dialog_content = "Acho que Elvis tem que mantê-lo pessoalmente para que funcione.",
  ui_story_5031_50311502_28_dialog_content = "Nesse caso, não preciso me conter.",
  ui_story_5031_50311502_29_dialog_content = "Vamos dar o golpe final nessa máquina estúpida e indiscriminada antes que ela destrua o navio.",
  ui_story_5031_50311502_30_dialog_content = "Sim! Jeno é melhor ser grato assim que acordar.",
  ui_story_5031_50311502_31_dialog_content = "Você está me desafiando?",
  ui_story_5031_50311502_32_dialog_content = "O laird está se reunindo com o dono do circo e ninguém pode embarcar no navio.",
  ui_story_5031_50311502_33_dialog_content = "Estamos apenas cumprindo ordens, então, por favor, entenda.",
  ui_story_5031_50311502_34_dialog_content = "Todos vocês não parecem estar apenas observando as instalações.",
  ui_story_5031_50311502_35_dialog_content = "Sem mencionar os sons de explosões vindos do navio.",
  ui_story_5031_50311502_36_dialog_content = "Reunião? Mais como um rancor para mim.",
  ui_story_5031_50311502_37_dialog_content = "Você não está preocupado com seu mestre? Ele é muito magrelo para lutar com Jeno.",
  ui_story_5031_50311502_38_dialog_content = "Por favor saia.",
  ui_story_5031_50311502_39_dialog_content = "Oh? Você vai me obrigar?",
  ui_story_5031_50311502_40_dialog_content = "Então é melhor você estar pronto para as consequências, já que eu vou denunciá-lo para...",
  ui_story_5031_50311502_41_dialog_content = "Não seja insolente, Patou.",
  ui_story_5031_50311502_42_dialog_content = "Laird!",
  ui_story_5031_50311502_43_dialog_content = "Oh, não é Laird Elvis? A reunião acabou?",
  ui_story_5031_50311502_44_dialog_content = "Desculpe deixá-lo esperando, Matthieu, mas eu tinha negócios importantes com um velho amigo.",
  ui_story_5031_50311502_45_dialog_content = "Patou e seus homens estão apenas seguindo ordens. Por favor, perdoe-os.",
  ui_story_5031_50311502_46_dialog_content = "Eu vejo. May embarcamos no navio agora?",
  ui_story_5031_50311502_47_dialog_content = "Por favor sinta-se livre.",
  ui_story_5031_50311502_48_dialog_content = "<size=33>Vamos deixá-lo entrar assim, senhor?</size>",
  ui_story_5031_50311502_49_dialog_content = "<size=33>Não importa. O navio vai detonar em breve, de qualquer maneira.</size>",
  ui_story_5031_50311502_50_dialog_content = "<size=33>Eu prefiro ir para...</size>",
  ui_story_5031_50311502_51_dialog_content = "Um momento, Laird Elvis.",
  ui_story_5031_50311502_52_dialog_content = "O que foi?",
  ui_story_5031_50311502_53_dialog_content = "Você viu Sua Alteza Carleen a bordo?",
  ui_story_5031_50311502_54_dialog_content = "Não. Ela e seus amigos estavam a bordo?",
  ui_story_5031_50311502_55_dialog_content = "Isso é estranho. Estou esperando desde que a celebração acabou, mas nunca vi Sua Alteza.",
  ui_story_5031_50311502_56_dialog_content = "Ela não desembarcou ou viu você, então por que ela ficaria no navio?",
  ui_story_5031_50311502_57_dialog_content = "Talvez ela esteja se despedindo dos novos amigos que fez.",
  ui_story_5031_50311502_58_dialog_content = "Uma vez que eles provavelmente se conheceram muito bem ao longo do dia.",
  ui_story_5031_50311502_59_dialog_content = "Fui designado para Sua Alteza como guarda-costas. Então eu basicamente cuidei dela o dia todo, com medo que ela pudesse se machucar.",
  ui_story_5031_50311502_60_dialog_content = "Acho que ela não tinha muito a ver com o pessoal do circo, pelas minhas observações.",
  ui_story_5031_50311502_61_dialog_content = "Mas senhorita Vice e Miss Ciel são velhas amigas.",
  ui_story_5031_50311502_62_dialog_content = "E PlayerName se dá muito bem com Miss Rainbow...",
  ui_story_5031_50311502_63_dialog_content = "Permita-me intervir, Laird Elvis.",
  ui_story_5031_50311502_64_dialog_content = "Sim?",
  ui_story_5031_50311502_65_dialog_content = "Acredito que não mencionei mais ninguém.",
  ui_story_5031_50311502_66_dialog_content = "Se você não a viu, como pode ter tanta certeza de que ela está com eles?",
  ui_story_5031_50311502_67_dialog_content = "...",
  ui_story_5031_50311502_68_dialog_content = "Isso porque todos os quatro são próximos e sempre saem juntos.",
  ui_story_5031_50311502_69_dialog_content = "Você parece saber muito por conhecê-los por apenas um dia.",
  ui_story_5031_50311502_70_dialog_content = "Estou perto daquele meu parceiro bem embrulhado, mas ele não está aqui.",
  ui_story_5031_50311502_71_dialog_content = "...",
  ui_story_5031_50311502_72_dialog_content = "Patou.",
  ui_story_5031_50311502_73_dialog_content = "Sim, senhor.",
  ui_story_5031_50311502_74_dialog_content = "Vejo que estamos entrando na fase \"sem testemunhas\".",
  ui_story_5031_50311502_75_dialog_content = "Não é uma pose de luta ruim lá.",
  ui_story_5031_50311502_76_dialog_content = "Mas você pode não saber que por baixo do exterior gelado de nosso Senhor da Cidade, ele é extremamente protetor com sua filha.",
  ui_story_5031_50311502_77_dialog_content = "Então você acha que eu, como guarda-costas dela, poderia ser facilmente tratada?",
  ui_story_5031_50311502_78_dialog_content = "Hora de fazer sua entrada, Loewe!",
  ui_story_5031_50311502_79_dialog_content = "O quê?",
  ui_story_5031_50311502_80_dialog_content = "Você fala demais, Matthieu.",
  ui_story_5031_50311502_81_dialog_content = "Esse é o seu negócio como?",
  ui_story_5031_50311502_82_dialog_content = "Apenas dois de vocês?",
  ui_story_5031_50311502_83_dialog_content = "Você espera lutar contra meus homens só com vocês dois?",
  ui_story_5031_50311502_84_dialog_content = "Errado, apenas um.",
  ui_story_5031_50311502_85_dialog_content = "Você tem isso, Loewe. Estou indo para um resgate.",
  ui_story_5031_50311502_86_dialog_content = "...",
  ui_story_5031_50311502_87_dialog_content = "Não será necessário.",
  ui_story_5031_50311502_88_dialog_content = "Ei, isso soa como...",
  ui_story_5031_50311502_89_dialog_content = "O quê?!",
  ui_story_5031_50311502_90_dialog_content = "Obrigado por manter Elvis ocupado.",
  ui_story_5031_50311502_91_dialog_content = "Isso é muito útil.",
  ui_story_5031_50311502_92_dialog_content = "Sua Alteza! É ótimo ver você ainda vivo!",
  ui_story_5031_50311502_93_dialog_content = "Impossível!",
  ui_story_5031_50311502_94_dialog_content = "Onde está o Guardião? Como é que o navio não explodiu?",
  ui_story_5031_50311502_95_dialog_content = "Carleen acerte-o com força total, e agora é uma pilha de sucata.",
  ui_story_5031_50311502_96_dialog_content = "Embora eu tenha que dizer que o robô foi fantasticamente construído!",
  ui_story_5031_50311502_97_dialog_content = "Pena que parou de se mover quando chegamos lá.",
  ui_story_5031_50311502_98_dialog_content = "Está bem. Ainda é bom para pesquisa.",
  ui_story_5031_50311502_99_dialog_content = "Tem razão!",
  ui_story_5031_50311502_100_dialog_content = "Mas como? Como você ainda pode exercer tal poder sob restrição?",
  ui_story_5031_50311502_101_dialog_content = "Espere, o Lumothread parou de absorver?",
  ui_story_5031_50311502_102_dialog_content = "Você não controla isso, Elvis?",
  ui_story_5031_50311502_103_dialog_content = "Não me diga que atingiu a capacidade máxima?",
  ui_story_5031_50311502_104_dialog_content = "Isso não pode ser... A roupa deve ser capaz de absorver Lumina de dois, até mesmo três Aurorianos!",
  ui_story_5031_50311502_105_dialog_content = "Isso não é importante.",
  ui_story_5031_50311502_106_dialog_content = "O que é, é que seu plano falhou, Elvis.",
  ui_story_5031_50311502_107_dialog_content = "Desistir. Você não pode fugir agora.",
  ui_story_5031_50311502_108_dialog_content = "Não, não... Eu não posso falhar! Eu não devo falhar!",
  ui_story_5031_50311502_109_dialog_content = "o <color=#FFB400>selo</color> em breve...",
  ui_story_5031_50311502_110_dialog_content = "Patou!",
  ui_story_5031_50311502_111_dialog_content = "Sim, senhor!",
  ui_story_5031_50311502_112_dialog_content = "A resistência é inútil.",
  ui_story_5031_50311502_113_dialog_content = "Ugh...",
  ui_story_5031_50311502_114_dialog_content = "Agora, senhor!",
  ui_story_5031_50311502_115_dialog_content = "Serei motivo de chacota se você fugir. Acha que vou deixar isso acontecer?",
  ui_story_5031_50311502_116_dialog_content = "Argh!",
  ui_story_5031_50311502_117_dialog_content = "Vamos! Eu apenas \"cutuquei\" ele, e ele terminou?",
  ui_story_5031_50311502_118_dialog_content = "Quão fraco é o homem?",
  ui_story_5031_50311502_119_dialog_content = "Laird!",
  ui_story_5031_50311502_120_dialog_content = "Eu sou quem você está lutando.",
  ui_story_5031_50311502_121_dialog_content = "Porcaria!",
  ui_story_5031_50311502_122_dialog_content = "Nenhum de vocês está fugindo.",
  ui_story_5031_50311601_1_dialog_content = "Você tem Ciel, certo, Rainbow?",
  ui_story_5031_50311601_2_dialog_content = "Sim! Eu vou cuidar bem dela, oficial!",
  ui_story_5031_50311601_3_dialog_content = "Frimet vai ajudar também!",
  ui_story_5031_50311601_4_dialog_content = "E Subli!",
  ui_story_5031_50311601_5_dialog_content = "M-Merylt também.",
  ui_story_5031_50311601_6_dialog_content = "Oh muito bom!",
  ui_story_5031_50311601_7_dialog_content = "Obrigado, oficial Gronru, por me deixar ficar.",
  ui_story_5031_50311601_8_dialog_content = "É tudo de bom. Nada muito está acontecendo ultimamente.",
  ui_story_5031_50311601_9_dialog_content = "Você pode ter calma aqui, Ciel.",
  ui_story_5031_50311601_10_dialog_content = "... Seriamente? Basta deixar esse núcleo de energia assim?",
  ui_story_5031_50311601_11_dialog_content = "Oh, é apenas um pequeno núcleo de energia. Não é precioso para a Illumina.",
  ui_story_5031_50311601_12_dialog_content = "Embora seja muito semelhante ao núcleo de energia, é pior em muitos aspectos, e a pureza da energia emitida não é boa.",
  ui_story_5031_50311601_13_dialog_content = "Além disso, após o manuseio sem sentido daquele laird, é basicamente um pedaço de sucata.",
  ui_story_5031_50311601_14_dialog_content = "Falando em valor de pesquisa... Talvez isso lhe dê alguma inspiração para atualizar seu \"Styx\".",
  ui_story_5031_50311601_15_dialog_content = "Droga, ainda não estudei esta nave o suficiente. Por que devo ser chamado neste momento!",
  ui_story_5031_50311601_15X1_dialog_content = "Ciel, você deve prestar atenção extra ao sistema de transmissão ao consertar o núcleo para eles!",
  ui_story_5031_50311601_15X2_dialog_content = "Faça boas anotações! Vou lê-los quando você voltar!",
  ui_story_5031_50311601_15X3_dialog_content = "Eu, eu entendo...",
  ui_story_5031_50311601_16_dialog_content = "Ei, o que você está sussurrando?",
  ui_story_5031_50311601_17_dialog_content = "Eu também quero ouvir!",
  ui_story_5031_50311601_18_dialog_content = "Uh, se fosse por nós, eles não teriam que sussurrar...",
  ui_story_5031_50311601_19_dialog_content = "Hum, isso fazia sentido.",
  ui_story_5031_50311601_20_dialog_content = "Esqueça, então.",
  ui_story_5031_50311601_21_dialog_content = "Ai está.",
  ui_story_5031_50311601_22_dialog_content = "O que você disse?",
  ui_story_5031_50311601_23_dialog_content = "Quem está fazendo tanto barulho?",
  ui_story_5031_50311601_24_dialog_content = "Tem certeza, Alteza?",
  ui_story_5031_50311601_25_dialog_content = "Você está realmente ficando aqui para administrar o lugar?",
  ui_story_5031_50311601_26_dialog_content = "De uma vez só.",
  ui_story_5031_50311601_27_dialog_content = "Mas Elvis pegou em armas contra você. Isso é traição!",
  ui_story_5031_50311601_28_dialog_content = "Senhor Schwartz não suportaria isso!",
  ui_story_5031_50311601_29_dialog_content = "É exatamente por isso que preciso da ajuda de vocês dois.",
  ui_story_5031_50311601_30_dialog_content = "Por que eu tenho um mau pressentimento sobre isso?",
  ui_story_5031_50311601_31_dialog_content = "Espero que você e o Sr. Loewe mantenham em segredo partes deste incidente.",
  ui_story_5031_50311601_32_dialog_content = "Além disso, gostaria que vocês dois ficassem comigo em Harbor City por um tempo.",
  ui_story_5031_50311601_33_dialog_content = "Receio que não.",
  ui_story_5031_50311601_34_dialog_content = "Desculpe, Alteza, veio diretamente de Lady Irridon.",
  ui_story_5031_50311601_35_dialog_content = "Eu sou obrigado a honrar isso.",
  ui_story_5031_50311601_36_dialog_content = "...",
  ui_story_5031_50311601_37_dialog_content = "Eu entendo, Sr. Matthieu. Eu não questiono sua lealdade em tudo.",
  ui_story_5031_50311601_38_dialog_content = "Mas prefiro não causar problemas para você e Loewe.",
  ui_story_5031_50311601_39_dialog_content = "Afinal, levei 17 pontos para minhas feridas, sem mencionar a incapacidade de usar Lumina por exaustão.",
  ui_story_5031_50311601_40_dialog_content = "Isso pode ser problemático se Lady Irridon ou Senhor Schwartz descubra sobre isso.",
  ui_story_5031_50311601_41_dialog_content = "Claro, mas...",
  ui_story_5031_50311601_42_dialog_content = "Claro, isso resultou de minha própria negligência, e estou bem agora.",
  ui_story_5031_50311601_43_dialog_content = "O médico também me disse que eu deveria me recuperar totalmente, com o tempo.",
  ui_story_5031_50311601_44_dialog_content = "Então, se você quiser evitar acusações desnecessárias, ficarei feliz em concordar.",
  ui_story_5031_50311601_45_dialog_content = "...",
  ui_story_5031_50311601_46_dialog_content = "Por quê?",
  ui_story_5031_50311601_47_dialog_content = "Porque o que?",
  ui_story_5031_50311601_48_dialog_content = "Por que insiste em ficar para trás, Alteza?",
  ui_story_5031_50311601_49_dialog_content = "Por que encobrir a transgressão de Elvis?",
  ui_story_5031_50311601_50_dialog_content = "Porque, em primeiro lugar, ele fez isso pelo bem do povo de Harbour City.",
  ui_story_5031_50311601_51_dialog_content = "Segundo, Harbour City sempre foi vassalo de Lumopolis, e Laird Elvis até estudou em Lumopolis antes.",
  ui_story_5031_50311601_52_dialog_content = "No entanto, ele não pediu ajuda a Lumopolis, mas buscou uma solução por conta própria e até a manteve de Lumopolis.",
  ui_story_5031_50311601_53_dialog_content = "Por que você acha que é isso?",
  ui_story_5031_50311601_54_dialog_content = "...",
  ui_story_5031_50311601_55_dialog_content = "É porque ele não acreditava que Lumopolis pudesse ou iria ajudá-lo.",
  ui_story_5031_50311601_56_dialog_content = "Um laird que não quer confiar em nós é a causa principal.",
  ui_story_5031_50311601_57_dialog_content = "Não podemos garantir que o próximo laird não fará a mesma escolha que Elvis fez.",
  ui_story_5031_50311601_58_dialog_content = "Se não chegarmos à raiz do problema e simplesmente ignorá-lo, ele se aprofundará.",
  ui_story_5031_50311601_59_dialog_content = "Assim, gostaria de descobrir a verdadeira intenção de Elvis.",
  ui_story_5031_50311601_60_dialog_content = "E arrancá-lo antes que seja cavado muito fundo.",
  ui_story_5031_50311601_61_dialog_content = "...",
  ui_story_5031_50311601_62_dialog_content = "Heh, para mim, você sempre foi nada mais do que uma princesa ingênua e protegida.",
  ui_story_5031_50311601_63_dialog_content = "...?",
  ui_story_5031_50311601_64_dialog_content = "Mas...",
  ui_story_5031_50311601_65_dialog_content = "Tenho de admitir que foi um discurso sensato.",
  ui_story_5031_50311601_66_dialog_content = "Não é mesmo, Loewe?",
  ui_story_5031_50311601_67_dialog_content = "De uma vez só.",
  ui_story_5031_50311601_68_dialog_content = "Então...",
  ui_story_5031_50311601_69_dialog_content = "No entanto!",
  ui_story_5031_50311601_70_dialog_content = "...",
  ui_story_5031_50311601_71_dialog_content = "Nós nunca mentiríamos para Lady Irridon.",
  ui_story_5031_50311601_72_dialog_content = "Portanto, ainda vamos relatar tudo através do Courier Union para ela hoje à noite.",
  ui_story_5031_50311601_73_dialog_content = "Onde está aquela Courier Union de novo?",
  ui_story_5031_50311601_74_dialog_content = "O-o que foi isso? Loewe?",
  ui_story_5031_50311601_75_dialog_content = "...",
  ui_story_5031_50311601_76_dialog_content = "White Pearl Street, ao lado do Restaurante Lucky Garden.",
  ui_story_5031_50311601_77_dialog_content = "Esse é o único.",
  ui_story_5031_50311601_78_dialog_content = "É com você, então.",
  ui_story_5031_50311601_79_dialog_content = "...",
  ui_story_5031_50311601_80_dialog_content = "Por que você não está fazendo isso?",
  ui_story_5031_50311601_81_dialog_content = "Porque eu ainda tenho que proteger a vizinhança.",
  ui_story_5031_50311601_82_dialog_content = "Uma situação tão perigosa exige uma pessoa mais forte para garantir a segurança de Sua Alteza.",
  ui_story_5031_50311601_83_dialog_content = "...",
  ui_story_5031_50311601_84_dialog_content = "O que, você quer lutar comigo?",
  ui_story_5031_50311601_85_dialog_content = "Vamos fazê-lo.",
  ui_story_5031_50311601_86_dialog_content = "Vamos, vamos pegar aquele lote ali. Eu vou bater em você hoje.",
  ui_story_5031_50311601_87_dialog_content = "Nos seus sonhos.",
  ui_story_5031_50311601_88_dialog_content = "...",
  ui_story_5031_50311601_89_dialog_content = "Você chegou a um acordo, Carleen?",
  ui_story_5031_50311601_90_dialog_content = "Como eles começaram a brigar?",
  ui_story_5031_50311601_91_dialog_content = "É assim que eles são. Eles brigam e brigam, mas nunca se separam.",
  ui_story_5031_50311601_92_dialog_content = "Quanto ao boletim de ocorrência...",
  ui_story_5031_50311601_93_dialog_content = "Acredito que temos um entendimento neutro.",
  ui_story_5031_50311601_94_dialog_content = "Isso é ótimo!",
  ui_story_5031_50311601_95_dialog_content = "Eles podem parecer estranhos, mas acabaram sendo surpreendentemente agradáveis.",
  ui_story_5031_50311601_96_dialog_content = "Tem certeza que vocês dois não estão feridos?",
  ui_story_5031_50311601_97_dialog_content = "Você não tem que me fazer companhia aqui.",
  ui_story_5031_50311601_98_dialog_content = "Como podemos deixá-lo sozinho em sua condição atual?",
  ui_story_5031_50311601_98X1_dialog_content = "Seu Lumina estava irradiando como se estivesse fora de controle, e você desmaiou logo depois que escapamos...",
  ui_story_5031_50311601_98X2_dialog_content = "Isso realmente nos assustou!",
  ui_story_5031_50311601_98X3_dialog_content = "Minhas desculpas por ter feito você se preocupar.",
  ui_story_5031_50311601_98X4_dialog_content = "Como você conseguiu o avanço de repente, Carleen? Isso foi incrível.",
  ui_story_5031_50311601_98X5_dialog_content = "Na época... eu senti o que você descreveu, Vice.",
  ui_story_5031_50311601_98X6_dialog_content = "Encontrei todas aquelas ansiedades que têm me incomodado.",
  ui_story_5031_50311601_98X7_dialog_content = "Eles eram tão reais, dominadores e sufocantes.",
  ui_story_5031_50311601_98X8_dialog_content = "Ah, Carleen...",
  ui_story_5031_50311601_98X9_dialog_content = "Felizmente, PlayerName entrou em contato com minha mente e me puxou de volta do abismo.",
  ui_story_5031_50311601_98X10_dialog_content = "Isso me fez perceber que vocês dois são o \"algo\" que eu precisava...",
  ui_story_5031_50311601_98X11_dialog_content = "Obrigado, PlayerName. E você também, Vice.",
  ui_story_5031_50311601_98X12_dialog_content = "Você fez isso sozinho, Carleen. Você superou a bagagem emocional e dominou sua própria mente.",
  ui_story_5031_50311601_98X13_dialog_content = "Isso é verdade, mas PlayerName sempre tem uma canja de galinha verbal para a alma pronta!",
  ui_story_5031_50311601_98X14_dialog_content = "O que é meio maravilhoso!",
  ui_story_5031_50311601_98X15_dialog_content = "E-é real?",
  ui_story_5031_50311601_98X16_dialog_content = "Estou apenas falando como me sinto.",
  ui_story_5031_50311601_98X17_dialog_content = "Isso é muito bom em si.",
  ui_story_5031_50311601_98X18_dialog_content = "De uma vez só.",
  ui_story_5031_50311601_98X19_dialog_content = "Mas você deve ter calma por um tempo, Carleen. Não apresse sua recuperação.",
  ui_story_5031_50311601_98X20_dialog_content = "Desmaiar por vazamentos de Lumina pode acontecer se você ainda não estiver acostumado.",
  ui_story_5031_50311601_98X21_dialog_content = "Portanto, não se force com o novo poder antes de se recuperar!",
  ui_story_5031_50311601_98X22_dialog_content = "Isso soa como algo Carleen faria.",
  ui_story_5031_50311601_98X23_dialog_content = "OK eu entendi.",
  ui_story_5031_50311601_98X24_dialog_content = "Eu vou cuidar de mim. Tenha certeza.",
  ui_story_5031_50311601_98X25_dialog_content = "Quanto ao avanço, vou procurar o melhor caminho com Vice depois que eu estiver completamente recuperado.",
  ui_story_5031_50311601_98X26_dialog_content = "Sem problemas!",
  ui_story_5031_50311601_99_dialog_content = "Você não precisa se preocupar conosco. PlayerName e eu somos durões, certo?",
  ui_story_5031_50311601_100_dialog_content = "Sim. Você pode se apoiar em nós de vez em quando, Carleen.",
  ui_story_5031_50311601_101_dialog_content = "Então deixe-nos cuidar de você desta vez!",
  ui_story_5031_50311601_102_dialog_content = "Pois então, muito obrigado.",
  ui_story_5031_50311601_103_dialog_content = "Sem problemas!",
  ui_story_5031_50311601_104_dialog_content = "O que devemos fazer em seguida?",
  ui_story_5031_50311601_105_dialog_content = "Dada a grande bagunça, há muitas coisas para lidar em Harbour City.",
  ui_story_5031_50311601_106_dialog_content = "Carleen estará muito ocupado como o laird interino.",
  ui_story_5031_50311601_107_dialog_content = "De fato. Mas antes que isso se torne oficial, tenho alguém que quero ver.",
  ui_story_5031_50311601_108_dialog_content = "Quem é esse?",
  ui_story_5031_50311601_109_dialog_content = "Elvis.",
  ui_story_5031_50311601_110_dialog_content = "<color=#e8d9bb>Continua...</color>"
}
return config
